INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a40b584-7596-446c-8d15-e9a7b840d612', '少室雪晴送王寧', '少室雪晴送王寧', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["少室衆峯幾峰別，一峰晴見一峰雪。","隔城半山連青松，素色峨峨千萬重。","過景斜臨不可道，白雲欲盡難爲容。","行人與我翫幽境，北風切切吹衣冷。","惜別浮橋駐馬時，舉頭試望南山嶺。"]', '["少室衆峯幾峰別，一峰晴见一峰雪。","隔城半山連青松，素色峨峨千万重。","過景斜臨不可道，白云欲尽难爲容。","行人與我翫幽境，北风切切吹衣冷。","惜別浮橋駐马时，舉头試望南山嶺。"]', '诗', 'shi', '', NULL, '少室雪晴送王寧 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e6cbc1b-95ed-406b-8c9d-d05876a1342c', '送陳章甫', '送陳章甫', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["四月南風大麥黃，棗花未落桐陰長。","青山朝別暮還見，嘶馬出門思舊鄉。","陳侯立身何坦蕩，虬鬚虎眉仍大顙。","腹中貯書一萬卷，不肯低頭在草莽。","東門酤酒飲我曹，心輕萬事皆鴻毛。","醉臥不知白日暮，有時空望孤雲高。","長河浪頭連天黑，津口停舟渡不得。","鄭國遊人未及家，洛陽行子空歎息。","聞道故林相識多，罷官昨日今如何。"]', '["四月南风大麦黄，棗花未落桐陰长。","青山朝別暮還见，嘶马出门思旧乡。","陳侯立身何坦蕩，虬鬚虎眉仍大顙。","腹中貯书一万卷，不肯低头在草莽。","东门酤酒饮我曹，心轻万事皆鴻毛。","醉臥不知白日暮，有时空望孤云高。","长河浪头連天黑，津口停舟渡不得。","鄭国游人未及家，洛陽行子空歎息。","闻道故林相識多，罷官昨日今如何。"]', '诗', 'shi', '', NULL, '送陳章甫 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d66a9e4-7b4d-4be4-91fd-6a4b2cd8817b', '聽安萬善吹觱篥歌', '听安万善吹觱篥歌', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["南山截竹爲觱篥，此樂本自龜茲出。","流傳漢地曲轉奇，涼州胡人爲我吹。","傍鄰聞者多歎息，遠客思鄉皆淚垂。","世人解聽不解賞，長飆風中自來往。","枯桑老柏寒颼飀，九雛鳴鳳亂啾啾。","龍吟虎嘯一時發，萬籟百泉相與秋。","忽然更作漁陽摻，黃雲蕭條白日暗。","變調如聞楊柳春，上林繁花照眼新。","歲夜高堂列明燭，美酒一杯聲一曲。"]', '["南山截竹爲觱篥，此乐本自龟茲出。","流傳漢地曲轉奇，涼州胡人爲我吹。","傍鄰闻者多歎息，远客思乡皆泪垂。","世人解听不解賞，长飆风中自来往。","枯桑老柏寒颼飀，九雛鳴鳳亂啾啾。","龙吟虎嘯一时發，万籟百泉相與秋。","忽然更作漁陽摻，黄云蕭條白日暗。","变調如闻楊柳春，上林繁花照眼新。","歲夜高堂列明燭，美酒一杯声一曲。"]', '诗', 'shi', '', NULL, '聽安萬善吹觱篥歌 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de5aad73-75e5-4e19-be62-d52ac7ec7402', '魏倉曹東堂檉樹', '魏倉曹东堂檉樹', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["愛君雙檉一樹奇，千葉齊生萬葉垂。","長頭拂石帶烟雨，獨立空山人莫知。","攢青蓄翠陰滿屋，紫穗紅英曾斷目。","洛陽墨客遊雲間，若到麻源第三谷。"]', '["愛君雙檉一樹奇，千葉齊生万葉垂。","长头拂石带烟雨，独立空山人莫知。","攢青蓄翠陰满屋，紫穗紅英曾斷目。","洛陽墨客游云间，若到麻源第三谷。"]', '诗', 'shi', '', NULL, '魏倉曹東堂檉樹 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('662bf0af-9040-4780-aa07-7fde14e32096', '照公院雙橙', '照公院雙橙', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["種橙夾階生得地，細葉隔簾見雙翠。","抽條向長未及肩，泉水遶根日三四。","青青何必楚人家，帶雨凝烟新著花。","永願香爐灑甘露，夕陽時映東枝斜。"]', '["種橙夾階生得地，細葉隔簾见雙翠。","抽條向长未及肩，泉水遶根日三四。","青青何必楚人家，带雨凝烟新著花。","永願香爐灑甘露，夕陽时映东枝斜。"]', '诗', 'shi', '', NULL, '照公院雙橙 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6610895-5ff8-425a-b5fd-705b349d221a', '愛敬寺古藤歌', '愛敬寺古藤歌', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["古藤池水盤樹根，左攫右拏龍虎蹲。","橫空直上相陵突，丰茸離纚若無骨。","風雷霹靂連黑枝，人言其下藏妖魑。","空庭落葉乍開合，十月苦寒常倒垂。","憶昨花飛滿空殿，密葉吹香飯僧遍。","南階雙桐一百尺，相與年年老霜霰。"]', '["古藤池水盤樹根，左攫右拏龙虎蹲。","橫空直上相陵突，丰茸離纚若無骨。","风雷霹靂連黑枝，人言其下藏妖魑。","空庭落葉乍开合，十月苦寒常倒垂。","憶昨花飞满空殿，密葉吹香飯僧遍。","南階雙桐一百尺，相與年年老霜霰。"]', '诗', 'shi', '', NULL, '愛敬寺古藤歌 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e86ad7b-5212-45a0-b64e-5b48f36c289a', '崔五六圖屏風各賦一物得烏孫佩刀', '崔五六圖屏风各賦一物得烏孫佩刀', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["烏孫腰間佩兩刀，刃可吹毛錦爲帶。","握手枕宿穹廬室，馬上割飛翳螉塞。","執之魍魎誰能前，氣凜清風沙漠邊。","磨用陰山一片玉，洗將胡地獨流泉。","主人屏風寫奇狀，鐵鞘金鐶儼相向。","回頭瞪目時一看，使予心在江湖上。"]', '["烏孫腰间佩兩刀，刃可吹毛錦爲带。","握手枕宿穹廬室，马上割飞翳螉塞。","執之魍魎誰能前，氣凜清风沙漠邊。","磨用陰山一片玉，洗將胡地独流泉。","主人屏风寫奇狀，鐵鞘金鐶儼相向。","回头瞪目时一看，使予心在江湖上。"]', '诗', 'shi', '', NULL, '崔五六圖屏風各賦一物得烏孫佩刀 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1496cf4-4f85-4f9e-9e0e-dd05370641d3', '古意', '古意', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["男兒事長征，少小幽燕客。","賭勝馬蹄下，由來輕七尺。","殺人莫敢前，鬚如蝟毛磔。","黃雲隴底白雪飛，未得報恩不能歸。","遼東小婦年十五，慣彈琵琶解歌舞。","今爲羗笛出塞聲，使我三軍淚如雨。"]', '["男兒事长征，少小幽燕客。","賭勝马蹄下，由来轻七尺。","殺人莫敢前，鬚如蝟毛磔。","黄云隴底白雪飞，未得報恩不能归。","遼东小婦年十五，慣彈琵琶解歌舞。","今爲羗笛出塞声，使我三軍泪如雨。"]', '诗', 'shi', '', NULL, '古意 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68a02d7f-453d-42bf-bf41-af9aa64556bd', '采蓮', '采蓮', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["越溪女，越溪蓮，齊菡萏，雙嬋娟。","嬉遊向何處，采摘且同船。","浩唱發容與，清波生漪漣。","時逢島嶼泊，幾伴鴦鴛眠。","襟袖既盈溢，馨香亦相傳。","薄暮歸去來，苧羅生碧烟。"]', '["越溪女，越溪蓮，齊菡萏，雙嬋娟。","嬉游向何处，采摘且同船。","浩唱發容與，清波生漪漣。","时逢島嶼泊，幾伴鴦鴛眠。","襟袖既盈溢，馨香亦相傳。","薄暮归去来，苧羅生碧烟。"]', '诗', 'shi', '', NULL, '采蓮 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adba4578-a5cc-4829-b247-3e48f04159e9', '雜興', '杂兴', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["沈沈牛渚磯，舊說多靈怪。","行人夜秉生犀燭，洞照洪深闢滂湃。","乘車駕馬往復旋，赤紱朱冠何偉然。","波驚海若潛幽石，龍抱胡髯臥黑泉。","水濱丈人曾有語，物或惡之當害汝。","武昌妖夢果爲災，百代英威埋鬼府。","青青蘭艾本殊香，察見泉魚固不祥。","濟水自清河自濁，周公大聖接輿狂。","千年魑魅逢華表，九日茱萸作佩囊。","善惡死生齊一貫，祗應斗酒任蒼蒼。"]', '["沈沈牛渚磯，旧说多靈怪。","行人夜秉生犀燭，洞照洪深闢滂湃。","乘车駕马往复旋，赤紱朱冠何偉然。","波驚海若潛幽石，龙抱胡髯臥黑泉。","水濱丈人曾有語，物或惡之當害汝。","武昌妖梦果爲災，百代英威埋鬼府。","青青蘭艾本殊香，察见泉鱼固不祥。","濟水自清河自濁，周公大聖接輿狂。","千年魑魅逢华表，九日茱萸作佩囊。","善惡死生齊一貫，祗應斗酒任蒼蒼。"]', '诗', 'shi', '', NULL, '雜興 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbbb2d00-acd3-4d89-86cb-02ed1db5c10e', '絕纓歌', '絕纓歌', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["楚王宴客章華臺，章華美人善歌舞。","玉顏豔豔空相向，滿堂目成不得語。","紅燭滅，芳酒闌，羅衣半醉春夜寒。","絕纓解帶一爲歡，君王赦過不之罪。","暗中珠翠鳴珊珊，寧愛賢，不愛色。","青娥買死誰能識，果却一軍全社稷。"]', '["楚王宴客章华台，章华美人善歌舞。","玉顏豔豔空相向，满堂目成不得語。","紅燭滅，芳酒闌，羅衣半醉春夜寒。","絕纓解带一爲歡，君王赦過不之罪。","暗中珠翠鳴珊珊，寧愛賢，不愛色。","青娥買死誰能識，果却一軍全社稷。"]', '诗', 'shi', '', NULL, '絕纓歌 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24242e3c-c8d7-48b9-8d63-84a799d97cf8', '鄭櫻桃歌', '鄭櫻桃歌', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["石季龍，僭天祿，擅雄豪，美人姓鄭名櫻桃。","櫻桃美顏香且澤，娥娥侍寢專宮掖。","後庭卷衣三萬人，翠眉清鏡不得親。","宮軍女騎一千匹，繁花照耀漳河春。","織成花映紅綸巾，紅旗掣曳鹵簿新。","鳴鼙走馬接飛鳥，銅馱瑟瑟隨去塵。","鳳陽重門如意館，百尺金梯倚銀漢。","自言富貴不可量，女爲公主男爲王。","赤花雙簟珊瑚牀，盤龍斗帳琥珀光。","淫昏僞位神所惡，滅石者陵終不悟。","鄴城蒼蒼白露微，世事翻覆黃雲飛。"]', '["石季龙，僭天祿，擅雄豪，美人姓鄭名櫻桃。","櫻桃美顏香且澤，娥娥侍寢專宮掖。","後庭卷衣三万人，翠眉清镜不得親。","宮軍女騎一千匹，繁花照耀漳河春。","织成花映紅綸巾，紅旗掣曳鹵簿新。","鳴鼙走马接飞鸟，銅馱瑟瑟隨去塵。","鳳陽重门如意館，百尺金梯倚銀漢。","自言富貴不可量，女爲公主男爲王。","赤花雙簟珊瑚牀，盤龙斗帳琥珀光。","淫昏僞位神所惡，滅石者陵終不悟。","鄴城蒼蒼白露微，世事翻覆黄云飞。"]', '诗', 'shi', '', NULL, '鄭櫻桃歌 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7592779c-b7f4-4ae1-b4b0-c2f7e889c241', '送劉昱', '送劉昱', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["八月寒葦花，秋江浪頭白。","北風吹五兩，誰是潯陽客。","鸕鷀山頭微雨晴，揚州郭裏暮潮生。","行人夜宿金陵渚，試聽沙邊有鴈聲。"]', '["八月寒葦花，秋江浪头白。","北风吹五兩，誰是潯陽客。","鸕鷀山头微雨晴，揚州郭裏暮潮生。","行人夜宿金陵渚，試听沙邊有鴈声。"]', '诗', 'shi', '', NULL, '送劉昱 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('710b3902-dd99-4e13-9a11-21eee9e603c9', '送郝判官', '送郝判官', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["楚城木葉落，夏口青山遍。","鴻鴈向南時，君乘使者傳。","楓林帶水驛，夜火明山縣。","千里送行人，蔡州如眼見。","江連清漢東逶迤，遙望荆雲相蔽虧。","應問襄陽舊風俗，爲余騎馬習家池。"]', '["楚城木葉落，夏口青山遍。","鴻鴈向南时，君乘使者傳。","楓林带水驛，夜火明山縣。","千里送行人，蔡州如眼见。","江連清漢东逶迤，遙望荆云相蔽虧。","應问襄陽旧风俗，爲余騎马習家池。"]', '诗', 'shi', '', NULL, '送郝判官 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7df35400-246a-42e6-b37b-3c9cda55a016', '送劉方平', '送劉方平', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["綺紈遊上國，多作少年行。","二十二詞賦，惟君著美名。","童顏且白皙，佩德如瑤瓊。","荀氏風流盛，胡家公子清。","有才不偶誰之過，肯即藏鋒事高臥。","洛陽草色猶自春，遊子東歸喜拜親。","漳水橋頭值鳴鴈，朝歌縣北少行人。","別離斗酒心相許，落日青郊半微雨。","請君騎馬望西陵，爲我殷勤弔魏武。"]', '["綺紈游上国，多作少年行。","二十二词賦，惟君著美名。","童顏且白皙，佩德如瑤瓊。","荀氏风流盛，胡家公子清。","有才不偶誰之過，肯即藏鋒事高臥。","洛陽草色猶自春，游子东归喜拜親。","漳水橋头值鳴鴈，朝歌縣北少行人。","別離斗酒心相許，落日青郊半微雨。","請君騎马望西陵，爲我殷勤弔魏武。"]', '诗', 'shi', '', NULL, '送劉方平 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('361a3e5e-ef71-4749-b39a-aa2f5d9180e4', '聽董大彈胡笳聲兼寄語弄房給事', '听董大彈胡笳声兼寄語弄房給事', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["蔡女昔造胡笳聲，一彈一十有八拍。","胡人落淚沾邊草，漢使斷腸對歸客。","古戍蒼蒼烽火寒，大荒沈沈飛雪白。","先拂商弦後角羽，四郊秋葉驚摵摵。","董夫子，通神明，深山竊聽來妖精。","言遲更速皆應手，將往復旋如有情。","空山百鳥散還合，萬里浮雲陰且晴。","嘶酸雛鴈失羣夜，斷絕胡兒戀母聲。","川爲淨其波，鳥亦罷其鳴。","烏孫部落家鄉遠，邏娑沙塵哀怨生。","幽音變調忽飄灑，長風吹林雨墮瓦。","迸泉颯颯飛木末，野鹿呦呦走堂下。","長安城連東掖垣，鳳凰池對青瑣門。","高才脫略名與利，日夕望君抱琴至。"]', '["蔡女昔造胡笳声，一彈一十有八拍。","胡人落泪沾邊草，漢使斷腸对归客。","古戍蒼蒼烽火寒，大荒沈沈飞雪白。","先拂商弦後角羽，四郊秋葉驚摵摵。","董夫子，通神明，深山竊听来妖精。","言遲更速皆應手，將往复旋如有情。","空山百鸟散還合，万里浮云陰且晴。","嘶酸雛鴈失羣夜，斷絕胡兒戀母声。","川爲淨其波，鸟亦罷其鳴。","烏孫部落家乡远，邏娑沙塵哀怨生。","幽音变調忽飄灑，长风吹林雨墮瓦。","迸泉颯颯飞木末，野鹿呦呦走堂下。","长安城連东掖垣，鳳凰池对青瑣门。","高才脫略名與利，日夕望君抱琴至。"]', '诗', 'shi', '', NULL, '聽董大彈胡笳聲兼寄語弄房給事 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3bcafdf-092e-4744-83c4-b73f789f483c', '彈棋歌', '彈棋歌', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["崔侯善彈棋，巧妙盡於此。","藍田美玉清如砥，白黑相分十二子。","聯翩百中皆造微，魏文手巾不足比。","緣邊度隴未可嘉，鳥跂星懸危復斜。","迴飆轉指速飛電，拂四取五旋風花。","坐中齊聲稱絕藝，仙人六博何能繼。","一別常山道路遙，爲余更作三五勢。"]', '["崔侯善彈棋，巧妙尽於此。","藍田美玉清如砥，白黑相分十二子。","聯翩百中皆造微，魏文手巾不足比。","緣邊度隴未可嘉，鸟跂星懸危复斜。","迴飆轉指速飞電，拂四取五旋风花。","坐中齊声稱絕藝，仙人六博何能繼。","一別常山道路遙，爲余更作三五勢。"]', '诗', 'shi', '', NULL, '彈棋歌 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a064a36-c5a2-424e-bb2f-e87d41a288a7', '送山陰姚丞攜妓之任兼寄蘇少府', '送山陰姚丞携妓之任兼寄蘇少府', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["東風香草路，南客心容與。","白皙吳王孫，青蛾柳家女。","都門數騎出，河口片帆舉。","夜簟眠橘洲，春衫傍楓嶼。","山陰政簡甚從容，到罷惟求物外蹤。","落日花邊剡溪水，晴烟竹裏會稽峰。","才子風流蘇伯玉，同官曉暮應相逐。","加飡共愛鱸魚肥，醒酒仍憐甘蔗熟。","知君練思本清新，季子如今得爲鄰。","他日知尋始寧墅，題詩早晚寄西人。"]', '["东风香草路，南客心容與。","白皙吳王孫，青蛾柳家女。","都门數騎出，河口片帆舉。","夜簟眠橘洲，春衫傍楓嶼。","山陰政簡甚從容，到罷惟求物外蹤。","落日花邊剡溪水，晴烟竹裏會稽峰。","才子风流蘇伯玉，同官晓暮應相逐。","加飡共愛鱸鱼肥，醒酒仍怜甘蔗熟。","知君練思本清新，季子如今得爲鄰。","他日知尋始寧墅，題诗早晚寄西人。"]', '诗', 'shi', '', NULL, '送山陰姚丞攜妓之任兼寄蘇少府 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bca0b77-e9bb-4581-8f83-358b77803d74', '塞下曲', '塞下曲', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["少年學騎射，勇冠幷州兒。","直愛出身早，邊功沙漠垂。","戎鞭腰下插，羌笛雪中吹。","膂力今應盡，將軍猶未知。"]', '["少年学騎射，勇冠幷州兒。","直愛出身早，邊功沙漠垂。","戎鞭腰下插，羌笛雪中吹。","膂力今應尽，將軍猶未知。"]', '诗', 'shi', '', NULL, '塞下曲 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('096b0d3e-2863-4d0a-b806-a0a470272729', '寄鏡湖朱處士', '寄镜湖朱处士', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["澄霽晚流闊，微風吹綠蘋。","鱗鱗遠峰見，淡淡平湖春。","芳草日堪把，白雲心所親。","何時可爲樂，夢裏東山人。"]', '["澄霽晚流闊，微风吹綠蘋。","鱗鱗远峰见，淡淡平湖春。","芳草日堪把，白云心所親。","何时可爲乐，梦裏东山人。"]', '诗', 'shi', '', NULL, '寄鏡湖朱處士 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('133c0ca6-642a-4645-aa1f-a8b2485f1e19', '宴陳十六樓', '宴陳十六楼', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["西樓對金谷，此地古人心。","白日落庭內，黃花生澗陰。","四鄰見疎木，萬井度寒砧。","石上題詩處，千年留至今。"]', '["西楼对金谷，此地古人心。","白日落庭內，黄花生澗陰。","四鄰见疎木，万井度寒砧。","石上題诗处，千年留至今。"]', '诗', 'shi', '', NULL, '宴陳十六樓 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd04484b-5baa-452a-a264-47c84b478e13', '送相里造入京', '送相里造入京', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["子月過秦正，寒雲覆洛城。","嗟君未得志，猶作苦辛行。","煖酒嫌衣薄，瞻風候雨晴。","春官含笑待，驅馬速前程。"]', '["子月過秦正，寒云覆洛城。","嗟君未得志，猶作苦辛行。","煖酒嫌衣薄，瞻风候雨晴。","春官含笑待，驱马速前程。"]', '诗', 'shi', '', NULL, '送相里造入京 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9279e4f0-0561-4caa-9ee7-2966862b7659', '送錢子入京', '送錢子入京', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["夜夢還京北，鄉心恨擣衣。","朝逢入秦使，走馬喚君歸。","驛路清霜下，關門黃葉稀。","還家應信宿，看子速如飛。"]', '["夜梦還京北，乡心恨擣衣。","朝逢入秦使，走马喚君归。","驛路清霜下，关门黄葉稀。","還家應信宿，看子速如飞。"]', '诗', 'shi', '', NULL, '送錢子入京 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f73328c-e408-4037-93b0-f170f89a5afc', '送綦毋三寺中賦得紗燈', '送綦毋三寺中賦得紗灯', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["禪室吐香燼，輕紗籠翠烟。","長繩挂青竹，百尺垂紅蓮。","熠爚衆星下，玲瓏雙塔前。","含光待明發，此別豈徒然。"]', '["禪室吐香燼，轻紗籠翠烟。","长繩挂青竹，百尺垂紅蓮。","熠爚衆星下，玲瓏雙塔前。","含光待明發，此別豈徒然。"]', '诗', 'shi', '', NULL, '送綦毋三寺中賦得紗燈 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b7964f3-4f04-469f-a8f2-539298fbe2c2', '送人尉閩中', '送人尉閩中', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["可歎芳菲日，分爲萬里情。","閶門折垂柳，御苑聽殘鶯。","海戍通閩邑，江航過楚城。","客心君莫問，春草是王程。"]', '["可歎芳菲日，分爲万里情。","閶门折垂柳，御苑听殘鶯。","海戍通閩邑，江航過楚城。","客心君莫问，春草是王程。"]', '诗', 'shi', '', NULL, '送人尉閩中 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e961071-11e8-4e8d-a11d-e7ce4213239d', '送人歸沔南', '送人归沔南', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["梅花今正發，失路復何如。","舊國雲山在，新年風景餘。","春饒漢陽夢，日寄武陵書。","可即明時老，臨川莫羨魚。"]', '["梅花今正發，失路复何如。","旧国云山在，新年风景餘。","春饒漢陽梦，日寄武陵书。","可即明时老，臨川莫羨鱼。"]', '诗', 'shi', '', NULL, '送人歸沔南 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14db03d3-7e86-4e56-bbda-9ea681cd5ae8', '送盧逸人', '送盧逸人', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["洛陽爲此別，攜手更何時。","不復人間見，祗應海上期。","清谿入雲木，白首臥茅茨。","共惜盧敖去，天邊望所思。"]', '["洛陽爲此別，携手更何时。","不复人间见，祗應海上期。","清谿入云木，白首臥茅茨。","共惜盧敖去，天邊望所思。"]', '诗', 'shi', '', NULL, '送盧逸人 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c584e126-947e-44b3-9d0b-1ea3cb8913e9', '送顧朝陽還吳', '送顧朝陽還吳', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["寂寞俱不偶，裹糧空入秦。","宦途已可識，歸臥包山春。","舊國指飛鳥，滄波愁旅人。","開樽洛水上，怨別柳花新。"]', '["寂寞俱不偶，裹糧空入秦。","宦途已可識，归臥包山春。","旧国指飞鸟，滄波愁旅人。","开樽洛水上，怨別柳花新。"]', '诗', 'shi', '', NULL, '送顧朝陽還吳 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0700bf45-2199-428a-9da7-0df637195f8a', '送竇參軍', '送竇參軍', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["城南送歸客，舉酒對林巒。","暄鳥迎風囀，春衣度雨寒。","桃花開翠幕，柳色拂金鞍。","公子何時至，無令芳草闌。"]', '["城南送归客，舉酒对林巒。","暄鸟迎风囀，春衣度雨寒。","桃花开翠幕，柳色拂金鞍。","公子何时至，無令芳草闌。"]', '诗', 'shi', '', NULL, '送竇參軍 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fa51383-e58c-4252-b000-ae3614667694', '望秦川', '望秦川', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["秦川朝望迥，日出正東峰。","遠近山河淨，逶迤城闕重。","秋聲萬戶竹，寒色五陵松。","客有歸歟歎，悽其霜露濃。"]', '["秦川朝望迥，日出正东峰。","远近山河淨，逶迤城闕重。","秋声万戶竹，寒色五陵松。","客有归歟歎，悽其霜露濃。"]', '诗', 'shi', '', NULL, '望秦川 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0256b0a6-d8f1-4b23-9c84-461e2c99c9c5', '晚歸東園', '晚归东园', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["荆扉帶郊郭，稼穡滿東葘。","倚杖寒山暮，鳴梭秋葉時。","回雲覆陰谷，返景照霜梨。","澹泊真吾事，清風別自茲。"]', '["荆扉带郊郭，稼穡满东葘。","倚杖寒山暮，鳴梭秋葉时。","回云覆陰谷，返景照霜梨。","澹泊真吾事，清风別自茲。"]', '诗', 'shi', '', NULL, '晚歸東園 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbe51772-97af-4374-b728-97e70eec3652', '覺公院施鳥石臺', '覺公院施鸟石台', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["石臺置香飯，齋後施諸禽。","童子亦知善，衆生無懼心。","苔痕蒼曉露，盤勢出香林。","錫杖或圍繞，吾師一念深。"]', '["石台置香飯，斋後施諸禽。","童子亦知善，衆生無懼心。","苔痕蒼晓露，盤勢出香林。","錫杖或圍繞，吾師一念深。"]', '诗', 'shi', '', NULL, '覺公院施鳥石臺 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93fc27c7-af33-4fde-8984-286d0547b585', '籬筍', '籬筍', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["東園長新笋，映日復穿籬。","迸出依青嶂，攢生半綠池。","色因林向背，行逐地高卑。","但恐春將老，青青獨爾爲。"]', '["东园长新笋，映日复穿籬。","迸出依青嶂，攢生半綠池。","色因林向背，行逐地高卑。","但恐春將老，青青独爾爲。"]', '诗', 'shi', '', NULL, '籬筍 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('531d1278-2f48-45e6-9114-82c14612d5bc', '達奚吏部夫人寇氏挽歌', '達奚吏部夫人寇氏挽歌', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["存歿令名傳，青青松柏田。","事姑稱孝婦，生子繼先賢。","露濕銘旌重，風吹鹵簿前。","陰堂從此閉，誰誦女師篇。"]', '["存歿令名傳，青青松柏田。","事姑稱孝婦，生子繼先賢。","露濕銘旌重，风吹鹵簿前。","陰堂從此閉，誰誦女師篇。"]', '诗', 'shi', '', NULL, '達奚吏部夫人寇氏挽歌 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf71d2e0-f802-4aef-8997-a0ca554aeea1', '寄司勳盧員外', '寄司勳盧員外', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["流澌臘月下河陽，草色新年發建章。","秦地立春傳太史，漢宮題柱憶仙郎。","歸鴻欲度千門雪，侍女新添五夜香。","早晚薦雄文似者，故人今已賦長楊。"]', '["流澌臘月下河陽，草色新年發建章。","秦地立春傳太史，漢宮題柱憶仙郎。","归鴻欲度千门雪，侍女新添五夜香。","早晚薦雄文似者，故人今已賦长楊。"]', '诗', 'shi', '', NULL, '寄司勳盧員外 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('818f2c7f-86ff-4cd3-bff2-eba44cfc45fb', '寄綦毋三', '寄綦毋三', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["新加大邑綬仍黃，近與單車去洛陽。","顧眄一過丞相府，風流三接令公香。","南川稉稻花侵縣，西嶺雲霞色滿堂。","共道進賢蒙上賞，看君幾歲作臺郎。"]', '["新加大邑綬仍黄，近與單车去洛陽。","顧眄一過丞相府，风流三接令公香。","南川稉稻花侵縣，西嶺云霞色满堂。","共道進賢蒙上賞，看君幾歲作台郎。"]', '诗', 'shi', '', NULL, '寄綦毋三 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6340ef19-35e2-4194-96a9-3ee0a667905b', '送魏萬之京', '送魏万之京', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["朝聞遊子唱離歌，昨夜微霜初渡河。","鴻鴈不堪愁裏聽，雲山況是客中過。","關城樹色催寒近，御苑砧聲向晚多。","莫見長安行樂處，空令歲月易蹉跎。"]', '["朝闻游子唱離歌，昨夜微霜初渡河。","鴻鴈不堪愁裏听，云山況是客中過。","关城樹色催寒近，御苑砧声向晚多。","莫见长安行乐处，空令歲月易蹉跎。"]', '诗', 'shi', '', NULL, '送魏萬之京 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d9edb8d-9abd-47f0-8441-95435901b9f8', '送李回', '送李回', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["知君官屬大司農，詔幸驪山職事雄。","歲發金錢供御府，晝看仙液注離宮。","千巖曙雪旌門上，十月寒花輦路中。","不覩聲明與文物，自傷流滯去關東。"]', '["知君官屬大司農，詔幸驪山職事雄。","歲發金錢供御府，晝看仙液注離宮。","千巖曙雪旌门上，十月寒花輦路中。","不覩声明與文物，自傷流滯去关东。"]', '诗', 'shi', '', NULL, '送李回 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3dd960a-4589-496f-912f-38e0e8380d4a', '宿瑩公禪房聞梵', '宿瑩公禪房闻梵', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["花宮仙梵遠微微，月隱高城鐘漏稀。","夜動霜林驚落葉，曉聞天籟發清機。","蕭條已入寒空靜，颯沓仍隨秋雨飛。","始覺浮生無住著，頓令心地欲皈依。"]', '["花宮仙梵远微微，月隐高城鐘漏稀。","夜动霜林驚落葉，晓闻天籟發清機。","蕭條已入寒空静，颯沓仍隨秋雨飞。","始覺浮生無住著，頓令心地欲皈依。"]', '诗', 'shi', '', NULL, '宿瑩公禪房聞梵 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a7e3beb-7631-42d3-abeb-42ce887d3a12', '題璿公山池', '題璿公山池', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["遠公遯跡廬山岑，開士幽居祇樹林。","片石孤峯窺色相，清池皓月照禪心。","指揮如意天花落，坐臥閑房春草深。","此外俗塵都不染，惟餘玄度得相尋。"]', '["远公遯跡廬山岑，开士幽居祇樹林。","片石孤峯窺色相，清池皓月照禪心。","指揮如意天花落，坐臥闲房春草深。","此外俗塵都不染，惟餘玄度得相尋。"]', '诗', 'shi', '', NULL, '題璿公山池 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8c90f9e-f292-472a-8f5c-653b27e43de6', '題盧五舊居', '題盧五旧居', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["物在人亡無見期，閑庭繫馬不勝悲。","窓前綠竹生空地，門外青山如舊時。","悵望秋天鳴墜葉，巑岏枯柳宿寒鴟。","憶君淚落東流水，歲歲花開知爲誰。"]', '["物在人亡無见期，闲庭繫马不勝悲。","窓前綠竹生空地，门外青山如旧时。","悵望秋天鳴墜葉，巑岏枯柳宿寒鴟。","憶君泪落东流水，歲歲花开知爲誰。"]', '诗', 'shi', '', NULL, '題盧五舊居 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a62f42e5-d321-4d43-9405-6acebd1f25bd', '贈別張兵曹', '贈別張兵曹', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["漢家蕭相國，功蓋五諸侯。","勳業河山重，丹青錫命優。","君爲禁臠壻，爭看玉人遊。","荀令焚香日，潘郎振藻秋。","新成鸚鵡賦，能衣鷫鸘裘。","不憚軒車遠，仍尋薜荔幽。","苑梨飛絳葉，伊水淨寒流。","雪滿故關道，雲遮祥鳳樓。","一身輕寸祿，萬物任虛舟。","別後如相問，滄波雙白鷗。"]', '["漢家蕭相国，功蓋五諸侯。","勳業河山重，丹青錫命優。","君爲禁臠壻，爭看玉人游。","荀令焚香日，潘郎振藻秋。","新成鸚鵡賦，能衣鷫鸘裘。","不憚軒车远，仍尋薜荔幽。","苑梨飞絳葉，伊水淨寒流。","雪满故关道，云遮祥鳳楼。","一身轻寸祿，万物任虛舟。","別後如相问，滄波雙白鷗。"]', '诗', 'shi', '', NULL, '贈別張兵曹 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('259f1f93-dcd7-4698-8e7f-4eb3c27d517f', '宿香山寺石樓', '宿香山寺石楼', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["夜宿翠微半，高樓聞暗泉。","漁舟帶遠火，山磬發孤烟。","衣拂雲松外，門清河漢邊。","峰巒低枕席，世界接人天。","靄靄花出霧，輝輝星映川。","東林曙鶯滿，惆悵欲言旋。"]', '["夜宿翠微半，高楼闻暗泉。","漁舟带远火，山磬發孤烟。","衣拂云松外，门清河漢邊。","峰巒低枕席，世界接人天。","靄靄花出霧，輝輝星映川。","东林曙鶯满，惆悵欲言旋。"]', '诗', 'shi', '', NULL, '宿香山寺石樓 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15d12326-5a85-493c-bde8-80e6b2ba85ec', '聖善閣送裴迪入京', '聖善閣送裴迪入京', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["雲華滿高閣，苔色上鈎欄。","藥草空階靜，梧桐返照寒。","清吟可愈疾，攜手暫同歡。","墮葉和金磬，飢烏鳴露盤。","伊流惜東別，灞水向西看。","舊託含香署，雲霄何足難。"]', '["云华满高閣，苔色上鈎欄。","藥草空階静，梧桐返照寒。","清吟可愈疾，携手暫同歡。","墮葉和金磬，飢烏鳴露盤。","伊流惜东別，灞水向西看。","旧託含香署，云霄何足难。"]', '诗', 'shi', '', NULL, '聖善閣送裴迪入京 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc784f57-296b-4a24-98ce-315d33706fdc', '奉送漪叔遊潁川兼謁淮陽太守', '奉送漪叔游潁川兼謁淮陽太守', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["罷吏今何適，辭家方獨行。","嵩陽入歸夢，潁水半前程。","聞道淮陽守，東南臥理清。","郡齋觀政日，人馬望鄉情。","疊嶺雪初霽，寒砧霜後鳴。","臨川嗟拜手，寂寞事躬耕。"]', '["罷吏今何適，辞家方独行。","嵩陽入归梦，潁水半前程。","闻道淮陽守，东南臥理清。","郡斋观政日，人马望乡情。","叠嶺雪初霽，寒砧霜後鳴。","臨川嗟拜手，寂寞事躬耕。"]', '诗', 'shi', '', NULL, '奉送漪叔遊潁川兼謁淮陽太守 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c591c14-2c7f-4f25-a2fe-51b89ce68143', '二妃廟送裴侍御使桂陽', '二妃廟送裴侍御使桂陽', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["沅上秋草晚，蒼蒼堯女祠。","無人見精魄，萬古寒猿悲。","桂水身歿後，椒漿神降時。","回雲迎赤豹，驟雨颯文狸。","受命出炎海，焚香徵楚詞。","乘驄感遺跡，一弔清川湄。"]', '["沅上秋草晚，蒼蒼堯女祠。","無人见精魄，万古寒猿悲。","桂水身歿後，椒漿神降时。","回云迎赤豹，驟雨颯文狸。","受命出炎海，焚香徵楚词。","乘驄感遺跡，一弔清川湄。"]', '诗', 'shi', '', NULL, '二妃廟送裴侍御使桂陽 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d19e2ab5-f5db-47c4-8b8a-ff5706d615b7', '送暨道士還玉清觀', '送暨道士還玉清观', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["仙宮有名籍，度世吳江濆。","大道本無我，青春長與君。","中州俄已到，至理得而聞。","明主降黃屋，時人看白雲。","空山何窈窕，三秀日氛氳。","遂此留書客，超遙烟駕分。"]', '["仙宮有名籍，度世吳江濆。","大道本無我，青春长與君。","中州俄已到，至理得而闻。","明主降黄屋，时人看白云。","空山何窈窕，三秀日氛氳。","遂此留书客，超遙烟駕分。"]', '诗', 'shi', '', NULL, '送暨道士還玉清觀 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c8f8e35-27a6-4e5f-afd9-114ffd0e76ea', '送劉主簿歸金壇', '送劉主簿归金壇', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["與子十年舊，其如離別何。","宦遊鄰故國，歸夢是滄波。","京口青山遠，金陵芳草多。","雲帆曉容裔，江日晝清和。","縣郭舟人飲，津亭漁者歌。","茅山有仙洞，羨爾再經過。"]', '["與子十年旧，其如離別何。","宦游鄰故国，归梦是滄波。","京口青山远，金陵芳草多。","云帆晓容裔，江日晝清和。","縣郭舟人饮，津亭漁者歌。","茅山有仙洞，羨爾再經過。"]', '诗', 'shi', '', NULL, '送劉主簿歸金壇 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b13d1a30-3c51-4411-ad5c-591ac6c11412', '送盧少府赴延陵', '送盧少府赴延陵', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["問君從宦所，何日府中趨。","遙指金陵縣，青山天一隅。","行人懷寸祿，小吏獻新圖。","北固波濤險，南天風俗殊。","春江連橘柚，晚景媚菰蒲。","漠漠花生渚，亭亭雲過湖。","灘沙映村火，水霧歛檣烏。","回首東門路，鄉書不可無。"]', '["问君從宦所，何日府中趨。","遙指金陵縣，青山天一隅。","行人懷寸祿，小吏獻新圖。","北固波濤險，南天风俗殊。","春江連橘柚，晚景媚菰蒲。","漠漠花生渚，亭亭云過湖。","灘沙映村火，水霧歛檣烏。","回首东门路，乡书不可無。"]', '诗', 'shi', '', NULL, '送盧少府赴延陵 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fcb174d-3d15-4996-8df3-b149765745c5', '送皇甫曾遊襄陽山水兼謁韋太守', '送皇甫曾游襄陽山水兼謁韋太守', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["峴山枕襄陽，滔滔江漢長。","山深臥龍宅，水淨斬蛟鄉。","元凱春秋傳，昭明文選堂。","風流滿今古，烟島思微茫。","白鴈暮衝雪，青林寒帶霜。","蘆花獨戍晚，柑實萬家香。","舊國欲茲別，輕舟眇未央。","百花亭漫漫，一柱觀蒼蒼。","按俗荆南牧，持衡吏部郎。","逢君立五馬，應醉習家塘。"]', '["峴山枕襄陽，滔滔江漢长。","山深臥龙宅，水淨斬蛟乡。","元凱春秋傳，昭明文選堂。","风流满今古，烟島思微茫。","白鴈暮衝雪，青林寒带霜。","蘆花独戍晚，柑實万家香。","旧国欲茲別，轻舟眇未央。","百花亭漫漫，一柱观蒼蒼。","按俗荆南牧，持衡吏部郎。","逢君立五马，應醉習家塘。"]', '诗', 'shi', '', NULL, '送皇甫曾遊襄陽山水兼謁韋太守 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c52fe18-7800-47e0-95fe-bc2de4e06dce', '龍門送裴侍御監五嶺選', '龙门送裴侍御監五嶺選', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["萬里番禺地，官人繼帝憂。","君爲柱下史，將命出東周。","歇馬傍川路，張燈臨石樓。","稜稜靜疎木，濞濞響寒流。","榔葉四荒外，梅花五嶺頭。","明珠尉佗國，翠羽夜郎洲。","夷俗富珍產，土風資宦遊。","心清物不雜，弊革事無留。","舉善必稱最，持姦當去尤。","何辭桂江遠，今日用賢秋。"]', '["万里番禺地，官人繼帝憂。","君爲柱下史，將命出东周。","歇马傍川路，張灯臨石楼。","稜稜静疎木，濞濞响寒流。","榔葉四荒外，梅花五嶺头。","明珠尉佗国，翠羽夜郎洲。","夷俗富珍產，土风資宦游。","心清物不杂，弊革事無留。","舉善必稱最，持姦當去尤。","何辞桂江远，今日用賢秋。"]', '诗', 'shi', '', NULL, '龍門送裴侍御監五嶺選 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe2004c3-7ef1-477c-bbff-6f6b95679239', '送喬琳', '送喬琳', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["草綠小平津，花開伊水濱。","今君不得意，孤負帝鄉春。","口不言金帛，心常任屈伸。","阮公惟飲酒，陶令肯羞貧。","陽羨風流地，滄海遊寓人。","菱歌五湖遠，桂樹八公鄰。","青鳥迎孤棹，白雲隨一身。","潮隨秣陵上，月映石頭新。","未可逃名利，應須在縉紳。","汀洲芳杜色，勸爾暫垂綸。"]', '["草綠小平津，花开伊水濱。","今君不得意，孤負帝乡春。","口不言金帛，心常任屈伸。","阮公惟饮酒，陶令肯羞貧。","陽羨风流地，滄海游寓人。","菱歌五湖远，桂樹八公鄰。","青鸟迎孤棹，白云隨一身。","潮隨秣陵上，月映石头新。","未可逃名利，應須在縉紳。","汀洲芳杜色，勸爾暫垂綸。"]', '诗', 'shi', '', NULL, '送喬琳 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbb34578-e435-4b68-89b4-f0e4c61fcc2d', '題少府監李丞山池', '題少府監李丞山池', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["能向府亭內，置茲山與林。","他人驌驦馬，而我薜蘿心。","雨止禁門肅，鶯啼官柳深。","長廊閟軍器，積水背城陰。","窓外王孫草，牀頭中散琴。","清風多仰慕，吾亦爾知音。"]', '["能向府亭內，置茲山與林。","他人驌驦马，而我薜蘿心。","雨止禁门肅，鶯啼官柳深。","长廊閟軍器，積水背城陰。","窓外王孫草，牀头中散琴。","清风多仰慕，吾亦爾知音。"]', '诗', 'shi', '', NULL, '題少府監李丞山池 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('759ba4c1-69e7-4e6d-a631-e1e4ad834ac3', '長壽寺粲公院新甃井', '长壽寺粲公院新甃井', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["僧房來往久，露井每同觀。","白石抱新甃，蒼苔依舊欄。","空瓶宛轉下，長綆轆轤盤。","境界因心淨，泉源見底寒。","鐘鳴時灌頂，對此日閑安。"]', '["僧房来往久，露井每同观。","白石抱新甃，蒼苔依旧欄。","空瓶宛轉下，长綆轆轤盤。","境界因心淨，泉源见底寒。","鐘鳴时灌頂，对此日闲安。"]', '诗', 'shi', '', NULL, '長壽寺粲公院新甃井 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b451422-9604-43ea-a48e-fd35c2634c10', '魏倉曹宅各賦一物得當軒石竹', '魏倉曹宅各賦一物得當軒石竹', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["羅生殊衆色，獨爲表華滋。","雖雜蕙蘭處，無爭桃李時。","同人趨府暇，落日後庭期。","密葉散紅點，靈條驚紫蕤。","芳菲看不厭，采摘願來茲。"]', '["羅生殊衆色，独爲表华滋。","雖杂蕙蘭处，無爭桃李时。","同人趨府暇，落日後庭期。","密葉散紅点，靈條驚紫蕤。","芳菲看不厭，采摘願来茲。"]', '诗', 'shi', '', NULL, '魏倉曹宅各賦一物得當軒石竹 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b36a19d-3623-4165-887e-f2f00704efe3', '奉送五叔入京兼寄綦毋三', '奉送五叔入京兼寄綦毋三', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["雲陰帶殘日，悵別此何時。","欲望黃山道，無由見所思。"]', '["云陰带殘日，悵別此何时。","欲望黄山道，無由见所思。"]', '诗', 'shi', '', NULL, '奉送五叔入京兼寄綦毋三 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a1ad234-a935-42b9-bdbc-5633180d1a99', '寄韓鵬', '寄韓鵬', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["爲政心閑物自閑，朝看飛鳥暮飛還。","寄書河上神明宰，羨爾城頭姑射山。"]', '["爲政心闲物自闲，朝看飞鸟暮飞還。","寄书河上神明宰，羨爾城头姑射山。"]', '诗', 'shi', '', NULL, '寄韓鵬 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d09f3c4-f3eb-4ece-b255-91a06da1e6a8', '百花原', '百花原', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["百花原頭望京師，黃河水流無已時。","窮秋曠野行人絕，馬首東來知是誰。"]', '["百花原头望京師，黄河水流無已时。","窮秋曠野行人絕，马首东来知是誰。"]', '诗', 'shi', '', NULL, '百花原 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c339392c-eb50-40b2-b223-6c98ab879d53', '遇劉五', '遇劉五', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["洛陽一別梨花新，黃鳥飛飛逢故人。","攜手當年共爲樂，無驚蕙草惜殘春。"]', '["洛陽一別梨花新，黄鸟飞飞逢故人。","携手當年共爲乐，無驚蕙草惜殘春。"]', '诗', 'shi', '', NULL, '遇劉五 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('262c723c-0d6e-4491-af0b-468c25872575', '送崔嬰赴漢陽', '送崔嬰赴漢陽', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["中外相連弟與兄，新加小縣子男名。","纔年三十佩銅印，知爾弦歌漢水清。"]', '["中外相連弟與兄，新加小縣子男名。","纔年三十佩銅印，知爾弦歌漢水清。"]', '诗', 'shi', '', NULL, '送崔嬰赴漢陽 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1880e64-2612-4d8b-a9fc-24164e6e75da', '送五叔入京兼寄綦毋三', '送五叔入京兼寄綦毋三', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["吏部明年拜官後，西城必與故人期。","寄書春草年年色，莫道相逢玉女祠。"]', '["吏部明年拜官後，西城必與故人期。","寄书春草年年色，莫道相逢玉女祠。"]', '诗', 'shi', '', NULL, '送五叔入京兼寄綦毋三 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f7d8969-6d94-486f-97e4-2f2b315c7ca3', '野老曝背', '野老曝背', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["百歲老翁不種田，惟知曝背樂殘年。","有時捫虱獨搔首，目送歸鴻籬下眠。"]', '["百歲老翁不種田，惟知曝背乐殘年。","有时捫虱独搔首，目送归鴻籬下眠。"]', '诗', 'shi', '', NULL, '野老曝背 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('098f81a6-a202-4656-ba49-0f7ed72ad8a0', '送東陽王太守', '送东陽王太守', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["江臯杜蘅綠，芳草日遲遲。","檜楫今何去，星郎出守時。","彤襜問風俗，明主寄惸嫠。","令下不徒爾，人和當在茲。","昔年經此地，微月有佳期。","洞口桂花白，巖前春草滋。","素沙靜津瀨，青壁帶川坻。","野鶴每孤立，林鼯常晝悲。"]', '["江臯杜蘅綠，芳草日遲遲。","檜楫今何去，星郎出守时。","彤襜问风俗，明主寄惸嫠。","令下不徒爾，人和當在茲。","昔年經此地，微月有佳期。","洞口桂花白，巖前春草滋。","素沙静津瀨，青壁带川坻。","野鹤每孤立，林鼯常晝悲。"]', '诗', 'shi', '', NULL, '送東陽王太守 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed525dd2-587a-440e-80bd-47abd0b222b0', '詠張諲山水', '詠張諲山水', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["小山破體閑支策，落日梨花照空壁。","詩堪記室妬風流，畫與將軍作勍敵。"]', '["小山破體闲支策，落日梨花照空壁。","诗堪記室妬风流，畫與將軍作勍敵。"]', '诗', 'shi', '', NULL, '詠張諲山水 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94e374cb-d887-4b10-b39d-d9e9f1f1757b', '失題', '失題', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["紫極殿前朝伏奏，龍華會裏日相望。","別離歲歲如流水，誰辨他鄉與故鄉。"]', '["紫極殿前朝伏奏，龙华會裏日相望。","別離歲歲如流水，誰辨他乡與故乡。"]', '诗', 'shi', '', NULL, '失題 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('291f404b-fab4-4097-ae66-bbca79e55f89', '冬夜寓居寄儲太祝', '冬夜寓居寄儲太祝', 'c3ca2e48-e31e-49e2-a1c4-1c929e92c8cf', '唐', '["自爲洛陽客，夫子吾知音。","盡義能下士，時人無此心。","奈何離居夜，巢鳥悲空林。","愁坐至月上，復聞南鄰砧。"]', '["自爲洛陽客，夫子吾知音。","尽義能下士，时人無此心。","奈何離居夜，巢鸟悲空林。","愁坐至月上，复闻南鄰砧。"]', '诗', 'shi', '', NULL, '冬夜寓居寄儲太祝 綦毋潛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6290b8f0-48de-407f-be2c-629140d91f83', '春泛若耶溪', '春泛若耶溪', 'c3ca2e48-e31e-49e2-a1c4-1c929e92c8cf', '唐', '["幽意無斷絕，此去隨所偶。","晚風吹行舟，花路入溪口。","際夜轉西壑，隔山望南斗。","潭煙飛溶溶，林月低向後。","生事且彌漫，願爲持竿叟。"]', '["幽意無斷絕，此去隨所偶。","晚风吹行舟，花路入溪口。","際夜轉西壑，隔山望南斗。","潭煙飞溶溶，林月低向後。","生事且彌漫，願爲持竿叟。"]', '诗', 'shi', '', NULL, '春泛若耶溪 綦毋潛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5742a099-ffbf-4ae8-9d49-07230cc778de', '題鶴林寺', '題鹤林寺', 'c3ca2e48-e31e-49e2-a1c4-1c929e92c8cf', '唐', '["道林隱形勝，向背臨層霄。","松覆山殿[冷]，花藏谿路遙。","珊珊寶幡挂，焰焰明燈燒。","遲日半空谷，春風連上潮。","少憑水木興，暫令身心調。","願謝攜手客，茲山禪誦饒。"]', '["道林隐形勝，向背臨層霄。","松覆山殿[冷]，花藏谿路遙。","珊珊寶幡挂，焰焰明灯燒。","遲日半空谷，春风連上潮。","少憑水木兴，暫令身心調。","願謝携手客，茲山禪誦饒。"]', '诗', 'shi', '', NULL, '題鶴林寺 綦毋潛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9982e29b-869e-46d8-921e-806398ee19fb', '題栖霞寺', '題栖霞寺', 'c3ca2e48-e31e-49e2-a1c4-1c929e92c8cf', '唐', '["南山勢迴合，靈境依此住。","殿轉雲崖陰，僧探石泉度。","龍蛇爭翕習，神鬼皆密護。","萬壑奔道場，羣峰向雙樹。","天花飛不著，水月白成路。","今日觀身我，歸心復何處。"]', '["南山勢迴合，靈境依此住。","殿轉云崖陰，僧探石泉度。","龙蛇爭翕習，神鬼皆密護。","万壑奔道場，羣峰向雙樹。","天花飞不著，水月白成路。","今日观身我，归心复何处。"]', '诗', 'shi', '', NULL, '題栖霞寺 綦毋潛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54547cd5-6844-4c78-8817-e9c4bd70a229', '送儲十二還莊城', '送儲十二還莊城', 'c3ca2e48-e31e-49e2-a1c4-1c929e92c8cf', '唐', '["西坂何繚繞，青林問子家。","天寒噪野雀，日晚度城鴉。","寂歷道傍樹，曈曨原上霞。","茲情不可說，長恨隱淪賒。"]', '["西坂何繚繞，青林问子家。","天寒噪野雀，日晚度城鴉。","寂歷道傍樹，曈曨原上霞。","茲情不可说，长恨隐淪賒。"]', '诗', 'shi', '', NULL, '送儲十二還莊城 綦毋潛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a05621e-d87d-43a4-9537-168baca4de02', '送章彝下第', '送章彝下第', 'c3ca2e48-e31e-49e2-a1c4-1c929e92c8cf', '唐', '["長安渭橋路，行客別時心。","獻賦溫泉畢，無媒魏闕深。","黃鶯啼就馬，白日暗歸林。","三十名未立，君還惜寸陰。"]', '["长安渭橋路，行客別时心。","獻賦溫泉畢，無媒魏闕深。","黄鶯啼就马，白日暗归林。","三十名未立，君還惜寸陰。"]', '诗', 'shi', '', NULL, '送章彝下第 綦毋潛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ab99853-9e39-4cc2-b8fe-9f80d5c250ee', '送崔員外黔中監選', '送崔員外黔中監選', 'c3ca2e48-e31e-49e2-a1c4-1c929e92c8cf', '唐', '["持衡出帝畿，星指夜郎飛。","神女雲迎馬，荆門雨濕衣。","聽猿收淚罷，繫鴈待書稀。","蠻貊雖殊俗，知君肝膽微。"]', '["持衡出帝畿，星指夜郎飞。","神女云迎马，荆门雨濕衣。","听猿收泪罷，繫鴈待书稀。","蠻貊雖殊俗，知君肝膽微。"]', '诗', 'shi', '', NULL, '送崔員外黔中監選 綦毋潛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1cf74ec-4e8f-4d96-a6e0-6450c4690e79', '送賈恆明府兼寄溫張二司戶', '送賈恆明府兼寄溫張二司戶', 'c3ca2e48-e31e-49e2-a1c4-1c929e92c8cf', '唐', '["越客新安別，秦人舊國情。","舟乘晚風便，月帶上潮平。","花路西施石，雲峰句踐城。","明州報兩掾，相憶二毛生。"]', '["越客新安別，秦人旧国情。","舟乘晚风便，月带上潮平。","花路西施石，云峰句踐城。","明州報兩掾，相憶二毛生。"]', '诗', 'shi', '', NULL, '送賈恆明府兼寄溫張二司戶 綦毋潛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d3c02c9-beb6-4eb1-81f1-a6530dd55f6f', '送宋秀才', '送宋秀才', 'c3ca2e48-e31e-49e2-a1c4-1c929e92c8cf', '唐', '["冠古積榮盛，當時數戟門。","舊交丞相子，繼世五侯孫。","長劒倚天外，短書盈萬言。","秋風一送別，江上黯消魂。"]', '["冠古積榮盛，當时數戟门。","旧交丞相子，繼世五侯孫。","长劒倚天外，短书盈万言。","秋风一送別，江上黯消魂。"]', '诗', 'shi', '', NULL, '送宋秀才 綦毋潛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd62ebec-0580-407f-b10c-7c828ab2421a', '送平判官入秦', '送平判官入秦', 'c3ca2e48-e31e-49e2-a1c4-1c929e92c8cf', '唐', '["謫遠自安命，三年已忘歸。","同聲願執手，驛騎到門扉。","云是帝鄉去，軍書謁紫微。","曾爲金馬客，向日淚沾衣。"]', '["謫远自安命，三年已忘归。","同声願執手，驛騎到门扉。","云是帝乡去，軍书謁紫微。","曾爲金马客，向日泪沾衣。"]', '诗', 'shi', '', NULL, '送平判官入秦 綦毋潛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ab56a35-a129-4f6a-ad7b-bf0e0232bc2b', '送鄭務拜伯父', '送鄭務拜伯父', 'c3ca2e48-e31e-49e2-a1c4-1c929e92c8cf', '唐', '["名公作逐臣，驅馬拂行塵。","舊國問鄖子，勞歌過郢人。","一川花送客，二月柳宜春。","奉料竹林興，寬懷此別晨。"]', '["名公作逐臣，驱马拂行塵。","旧国问鄖子，勞歌過郢人。","一川花送客，二月柳宜春。","奉料竹林兴，寬懷此別晨。"]', '诗', 'shi', '', NULL, '送鄭務拜伯父 綦毋潛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3d1052d-5b2f-4f65-9f97-a41b848d5c1d', '題招隱寺絢公房', '題招隐寺絢公房', 'c3ca2e48-e31e-49e2-a1c4-1c929e92c8cf', '唐', '["開士度人久，空巖花霧深。","徒知燕坐處，不見有爲心。","蘭若門對壑，田家路隔林。","還言證法性，歸去比黃金。"]', '["开士度人久，空巖花霧深。","徒知燕坐处，不见有爲心。","蘭若门对壑，田家路隔林。","還言證法性，归去比黄金。"]', '诗', 'shi', '', NULL, '題招隱寺絢公房 綦毋潛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('706d8c47-3008-4e58-a275-9f048ebb19d7', '宿太平觀', '宿太平观', 'c3ca2e48-e31e-49e2-a1c4-1c929e92c8cf', '唐', '["夕到玉京寢，窅冥雲漢低。","魂交仙室蝶，曙聽羽人雞。","滴瀝花上露，清泠松下谿。","明當訪真隱，揮手入無倪。"]', '["夕到玉京寢，窅冥云漢低。","魂交仙室蝶，曙听羽人雞。","滴瀝花上露，清泠松下谿。","明當訪真隐，揮手入無倪。"]', '诗', 'shi', '', NULL, '宿太平觀 綦毋潛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42cf3a65-dee7-495d-abc2-47ac39fbba8d', '題靈隱寺山頂禪院', '題靈隐寺山頂禪院', 'c3ca2e48-e31e-49e2-a1c4-1c929e92c8cf', '唐', '["招提此山頂，下界不相聞。","塔影挂清漢，鐘聲和白雲。","觀空靜室掩，行道衆香焚。","且駐西來駕，人天日未曛。"]', '["招提此山頂，下界不相闻。","塔影挂清漢，鐘声和白云。","观空静室掩，行道衆香焚。","且駐西来駕，人天日未曛。"]', '诗', 'shi', '', NULL, '題靈隱寺山頂禪院 綦毋潛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f6ffb21-59dd-4e71-8f59-5280fcc1d92b', '若耶溪逢孔九', '若耶溪逢孔九', 'c3ca2e48-e31e-49e2-a1c4-1c929e92c8cf', '唐', '["相逢此溪曲，勝託在煙霞。","潭影竹間動，巖陰簷外斜。","人言上皇代，犬吠武陵家。","借問淹留日，春風滿若耶。"]', '["相逢此溪曲，勝託在煙霞。","潭影竹间动，巖陰簷外斜。","人言上皇代，犬吠武陵家。","借问淹留日，春风满若耶。"]', '诗', 'shi', '', NULL, '若耶溪逢孔九 綦毋潛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf89be7e-31a7-4e7c-9120-dccb9396cd94', '宿龍興寺', '宿龙兴寺', 'c3ca2e48-e31e-49e2-a1c4-1c929e92c8cf', '唐', '["香剎夜忘歸，松青古殿扉。","燈明方丈室，珠繫比丘衣。","白日傳心靜，青蓮喻法微。","天花落不盡，處處鳥銜飛。"]', '["香剎夜忘归，松青古殿扉。","灯明方丈室，珠繫比丘衣。","白日傳心静，青蓮喻法微。","天花落不尽，处处鸟銜飞。"]', '诗', 'shi', '', NULL, '宿龍興寺 綦毋潛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69def054-408a-424e-b288-1f720a7b6280', '題沈東美員外山池', '題沈东美員外山池', 'c3ca2e48-e31e-49e2-a1c4-1c929e92c8cf', '唐', '["仙郎偏好道，鑿沼象瀛洲。","魚樂隨情性，船行任去留。","秦人辨雞犬，堯日識巢由。","歸客衡門外，仍憐返景幽。"]', '["仙郎偏好道，鑿沼象瀛洲。","鱼乐隨情性，船行任去留。","秦人辨雞犬，堯日識巢由。","归客衡门外，仍怜返景幽。"]', '诗', 'shi', '', NULL, '題沈東美員外山池 綦毋潛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f60e2e5-813b-4186-8be3-690c9a94b446', '茅山洞口', '茅山洞口', 'c3ca2e48-e31e-49e2-a1c4-1c929e92c8cf', '唐', '["華陽仙洞口，半嶺拂雲看。","窈窕穿苔壁，差池對石壇。","方隨地脉轉，稍覺水晶寒。","未果變金骨，歸來茲路難。"]', '["华陽仙洞口，半嶺拂云看。","窈窕穿苔壁，差池对石壇。","方隨地脉轉，稍覺水晶寒。","未果变金骨，归来茲路难。"]', '诗', 'shi', '', NULL, '茅山洞口 綦毋潛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7911c240-6791-42df-a986-4a7a1f584e1d', '過方尊師院', '過方尊師院', 'c3ca2e48-e31e-49e2-a1c4-1c929e92c8cf', '唐', '["羽客北山尋，草堂松徑深。","養神宗示法，得道不知心。","洞戶逢雙履，寥天有一琴。","更登玄圃上，仍種杏成林。"]', '["羽客北山尋，草堂松徑深。","養神宗示法，得道不知心。","洞戶逢雙履，寥天有一琴。","更登玄圃上，仍種杏成林。"]', '诗', 'shi', '', NULL, '過方尊師院 綦毋潛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b363113-5825-4d4e-a5e0-4eece9ec0a8b', '經陸補闕隱居', '經陸補闕隐居', 'c3ca2e48-e31e-49e2-a1c4-1c929e92c8cf', '唐', '["不敢要君徵亦起，致君全得似唐虞。","讜言昨歎離天聽，新象今聞入縣圖。","琴鎖壞窗風自響，鶴歸喬木隱難呼。","學書弟子何人在，點檢猶存諫草無。"]', '["不敢要君徵亦起，致君全得似唐虞。","讜言昨歎離天听，新象今闻入縣圖。","琴鎖壞窗风自响，鹤归喬木隐难呼。","学书弟子何人在，点檢猶存諫草無。"]', '诗', 'shi', '', NULL, '經陸補闕隱居 綦毋潛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78cb7f8b-5906-469f-a964-c73388b1a3c2', '登天竺寺', '登天竺寺', 'c3ca2e48-e31e-49e2-a1c4-1c929e92c8cf', '唐', '["郡有化城最，西窮疊嶂深。","松門當澗口，石路在峰心。","幽見夕陽霽，高逢暮雨陰。","佛身瞻紺髮，寶地踐黃金。","雲向竹谿盡，月從花洞臨。","因物成真悟，遺世在茲岑。"]', '["郡有化城最，西窮叠嶂深。","松门當澗口，石路在峰心。","幽见夕陽霽，高逢暮雨陰。","佛身瞻紺髮，寶地踐黄金。","云向竹谿尽，月從花洞臨。","因物成真悟，遺世在茲岑。"]', '诗', 'shi', '', NULL, '登天竺寺 綦毋潛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02b96a97-bf2b-4bca-885d-4477637f85e5', '滿公房', '满公房', 'c3ca2e48-e31e-49e2-a1c4-1c929e92c8cf', '唐', '["世界蓮花藏，行人香火緣。","燈王照不盡，中夜寂相傳。"]', '["世界蓮花藏，行人香火緣。","灯王照不尽，中夜寂相傳。"]', '诗', 'shi', '', NULL, '滿公房 綦毋潛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c575c996-1310-448f-a30a-e3f4842b2f45', '過融上人蘭若', '過融上人蘭若', 'c3ca2e48-e31e-49e2-a1c4-1c929e92c8cf', '唐', '["山頭禪室挂僧衣，窗外無人溪鳥飛。","黃昏半在下山路，却聽鐘聲連翠微。"]', '["山头禪室挂僧衣，窗外無人溪鸟飞。","黄昏半在下山路，却听鐘声連翠微。"]', '诗', 'shi', '', NULL, '過融上人蘭若 綦毋潛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d548d87c-f901-4ac2-bf2a-42249c164aa3', '早發上東門', '早發上东门', 'c3ca2e48-e31e-49e2-a1c4-1c929e92c8cf', '唐', '["十五能行西入秦，三十無家作路人。","時命不將明主合，布衣空染洛陽塵。"]', '["十五能行西入秦，三十無家作路人。","时命不將明主合，布衣空染洛陽塵。"]', '诗', 'shi', '', NULL, '早發上東門 綦毋潛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04bb42bd-b530-47a1-b16d-194ade6f07cf', '祇園寺', '祇园寺', 'c3ca2e48-e31e-49e2-a1c4-1c929e92c8cf', '唐', '["寶坊求往跡，神理駐沿洄。","鴈塔酬前願，王身更後來。","加持將暝合，朗悟豁然開。","兩世分明見，餘生復幾哉。"]', '["寶坊求往跡，神理駐沿洄。","鴈塔酬前願，王身更後来。","加持將暝合，朗悟豁然开。","兩世分明见，餘生复幾哉。"]', '诗', 'shi', '', NULL, '祇園寺 綦毋潛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a55071fb-7c28-4b91-99e7-c171064c2779', '送集賢學士伊闕史少府放歸江東覲省', '送集賢学士伊闕史少府放归江东覲省', 'c3ca2e48-e31e-49e2-a1c4-1c929e92c8cf', '唐', '["墨客鍾張侶，材高吳越珍。","千門來謁帝，駟馬去榮親。","吏邑沿清洛，鄉山指白蘋。","歸期應不遠，當及未央春。"]', '["墨客鍾張侶，材高吳越珍。","千门来謁帝，駟马去榮親。","吏邑沿清洛，乡山指白蘋。","归期應不远，當及未央春。"]', '诗', 'shi', '', NULL, '送集賢學士伊闕史少府放歸江東覲省 綦毋潛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('286afdbf-943f-4db8-ae95-4771364f294e', '述韋昭應畫犀牛', '述韋昭應畫犀牛', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["遐方獻文犀，萬里隨南金。","大邦柔遠人，以之居山林。","食棘無秋冬，絕流無淺深。","雙角前嶄嶄，三蹄下駸駸。","朝賢壯其容，未能辨其音。","有我衰鳥郎，新邑長鳴琴。","陛閣飛嘉聲，丘甸盈仁心。","閑居命國工，作繪北堂陰。","眈眈若有神，庶比來儀禽。","昔有舞天庭，爲君奏龍吟。"]', '["遐方獻文犀，万里隨南金。","大邦柔远人，以之居山林。","食棘無秋冬，絕流無淺深。","雙角前嶄嶄，三蹄下駸駸。","朝賢壯其容，未能辨其音。","有我衰鸟郎，新邑长鳴琴。","陛閣飞嘉声，丘甸盈仁心。","闲居命国工，作繪北堂陰。","眈眈若有神，庶比来儀禽。","昔有舞天庭，爲君奏龙吟。"]', '诗', 'shi', '', NULL, '述韋昭應畫犀牛 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ec7ee8c-d3d1-4bc6-a039-4690aaae44de', '獻王威儀', '獻王威儀', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["入與真主言，有騎天馬來。","但有華清宮，不用神明臺。","肅肅長自閑，門靜無人開。"]', '["入與真主言，有騎天马来。","但有华清宮，不用神明台。","肅肅长自闲，门静無人开。"]', '诗', 'shi', '', NULL, '獻王威儀 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5933a7ce-8229-4c73-8ee3-0512a999b93f', '野田黃雀行', '野田黄雀行', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["嘖嘖野田雀，不知軀體微。","閑穿深蒿裏，爭食復爭飛。","窮老一頹舍，棗多桑樹稀。","無棗猶可食，無桑何以衣。","蕭條空倉暮，相引時來歸。","斜路豈不捷，渚田豈不肥。","水長路且壞，惻惻與心違。"]', '["嘖嘖野田雀，不知軀體微。","闲穿深蒿裏，爭食复爭飞。","窮老一頹舍，棗多桑樹稀。","無棗猶可食，無桑何以衣。","蕭條空倉暮，相引时来归。","斜路豈不捷，渚田豈不肥。","水长路且壞，惻惻與心違。"]', '诗', 'shi', '', NULL, '野田黃雀行 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8d49a74-fe0a-4003-a0da-5653665504f5', '樵父詞', '樵父词', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["山北饒朽木，山南多枯枝。","枯枝作採薪，爨室私自知。","詰朝礪斧尋，視暮行歌歸。","先雪隱薜荔，迎暄臥茅茨。","清澗日濯足，喬木時曝衣。","終年登險阻，不復憂安危。","蕩漾與神遊，莫知是與非。"]', '["山北饒朽木，山南多枯枝。","枯枝作採薪，爨室私自知。","詰朝礪斧尋，視暮行歌归。","先雪隐薜荔，迎暄臥茅茨。","清澗日濯足，喬木时曝衣。","終年登險阻，不复憂安危。","蕩漾與神游，莫知是與非。"]', '诗', 'shi', '', NULL, '樵父詞 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce84ec5f-cac1-4ed4-a04b-07d740c76585', '漁父詞', '漁父词', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["澤魚好鳴水，溪魚好上流。","漁梁不得意，下渚潛垂鉤。","亂荇時礙楫，新蘆復隱舟。","靜言念終始，安坐看沈浮。","素髮隨風揚，遠心與雲遊。","逆浪還極浦，信潮下滄洲。","非爲徇形役，所樂在行休。"]', '["澤鱼好鳴水，溪鱼好上流。","漁梁不得意，下渚潛垂鉤。","亂荇时礙楫，新蘆复隐舟。","静言念終始，安坐看沈浮。","素髮隨风揚，远心與云游。","逆浪還極浦，信潮下滄洲。","非爲徇形役，所乐在行休。"]', '诗', 'shi', '', NULL, '漁父詞 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cf09a50-e553-4e24-a7c9-7249464a56d7', '牧童詞', '牧童词', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["不言牧田遠，不道牧陂深。","所念牛馴擾，不亂牧童心。","圓笠覆我首，長簑披我襟。","方將憂暑雨，亦以懼寒陰。","大牛隱層坂，小牛穿近林。","同類相鼓舞，觸物成謳吟。","取樂須臾間，寧問聲與音。"]', '["不言牧田远，不道牧陂深。","所念牛馴擾，不亂牧童心。","圓笠覆我首，长簑披我襟。","方將憂暑雨，亦以懼寒陰。","大牛隐層坂，小牛穿近林。","同類相鼓舞，觸物成謳吟。","取乐須臾间，寧问声與音。"]', '诗', 'shi', '', NULL, '牧童詞 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62be752e-7964-4b51-97c6-d86415ab8654', '采蓮詞', '采蓮词', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["淺渚荇花繁，深潭菱葉疎。","獨往方自得，恥邀淇上姝。","廣江無術阡，大澤絕方隅。","浪中海童語，流下鮫人居。","春鴈時隱舟，新萍復滿湖。","采采乘日暮，不思賢與愚。"]', '["淺渚荇花繁，深潭菱葉疎。","独往方自得，恥邀淇上姝。","廣江無術阡，大澤絕方隅。","浪中海童語，流下鮫人居。","春鴈时隐舟，新萍复满湖。","采采乘日暮，不思賢與愚。"]', '诗', 'shi', '', NULL, '采蓮詞 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09f5cc10-01a4-4ec2-be4a-3deab75787fd', '採菱詞', '採菱词', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["濁水菱葉肥，清水菱葉鮮。","義不遊濁水，志士多苦言。","潮沒具區藪，潦深雲夢田。","朝隨北風去，暮逐南風旋。","浦口多漁家，相與邀我船。","飯稻以終日，羹蓴將永年。","方冬水物窮，又欲休山樊。","盡室相隨從，所貴無憂患。"]', '["濁水菱葉肥，清水菱葉鲜。","義不游濁水，志士多苦言。","潮沒具區藪，潦深云梦田。","朝隨北风去，暮逐南风旋。","浦口多漁家，相與邀我船。","飯稻以終日，羹蓴將永年。","方冬水物窮，又欲休山樊。","尽室相隨從，所貴無憂患。"]', '诗', 'shi', '', NULL, '採菱詞 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80b7dcdf-a5af-46c8-9ce4-f01a77a0f890', '射雉詞', '射雉词', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["曝暄理新翳，迎春射鳴雉。","原田遙一色，臯陸曠千里。","遙聞咿喔聲，時見雙飛起。","冪䍥疎蒿下，毰毸深叢裏。","顧敵已忘生，爭雄方決死。","仁心貴勇義，豈能復傷此。","超遙下故墟，迢遞回高畤。","大夫昔何苦，取笑歡妻子。"]', '["曝暄理新翳，迎春射鳴雉。","原田遙一色，臯陸曠千里。","遙闻咿喔声，时见雙飞起。","冪䍥疎蒿下，毰毸深叢裏。","顧敵已忘生，爭雄方決死。","仁心貴勇義，豈能复傷此。","超遙下故墟，迢遞回高畤。","大夫昔何苦，取笑歡妻子。"]', '诗', 'shi', '', NULL, '射雉詞 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba47801f-e80d-4381-8a6e-523809fd1d76', '猛虎詞', '猛虎词', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["寒亦不憂雪，飢亦不食人。","人肉豈不甘，所惡傷明神。","太室爲我宅，孟門爲我鄰。","百獸爲我膳，五龍爲我賓。","蒙馬一何威，浮江一以仁。","彩章耀朝日，爪牙雄武臣。","高雲逐氣浮，厚地隨聲震。","君能賈餘勇，日夕長相親。"]', '["寒亦不憂雪，飢亦不食人。","人肉豈不甘，所惡傷明神。","太室爲我宅，孟门爲我鄰。","百獸爲我膳，五龙爲我賓。","蒙马一何威，浮江一以仁。","彩章耀朝日，爪牙雄武臣。","高云逐氣浮，厚地隨声震。","君能賈餘勇，日夕长相親。"]', '诗', 'shi', '', NULL, '猛虎詞 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('562c378e-1d6f-43a1-96f6-a7efd799a3e9', '渭橋北亭作', '渭橋北亭作', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["停車渭陽暮，望望入秦京。","不見鵷鸞道，如聞歌吹聲。","鄉魂涉江水，客路指蒲城。","獨有故樓月，今來亭上明。"]', '["停车渭陽暮，望望入秦京。","不见鵷鸾道，如闻歌吹声。","乡魂涉江水，客路指蒲城。","独有故楼月，今来亭上明。"]', '诗', 'shi', '', NULL, '渭橋北亭作 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97033757-7f04-4642-a13c-ab76622ca0ef', '述華清宮五首 一', '述华清宮五首 一', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["上在蓬萊宮，莫若居華清。","朝朝禮玄閣，日日聞體輕。","大聖不私己，精禋爲羣氓。"]', '["上在蓬萊宮，莫若居华清。","朝朝禮玄閣，日日闻體轻。","大聖不私己，精禋爲羣氓。"]', '诗', 'shi', '', NULL, '述華清宮五首 一 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9fea8fa6-3c29-45d0-83ed-3eacf059f158', '述華清宮五首 二', '述华清宮五首 二', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["上出蓬萊時，六龍儼齊首。","長道舒羽儀，彤雲暎前後。","天聲殷宇宙，真氣到林藪。"]', '["上出蓬萊时，六龙儼齊首。","长道舒羽儀，彤云暎前後。","天声殷宇宙，真氣到林藪。"]', '诗', 'shi', '', NULL, '述華清宮五首 二 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5615d8d0-7549-48cf-8cbc-e164f5f7e7a5', '述華清宮五首 三', '述华清宮五首 三', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["昔在軒轅朝，五城十二樓。","今我神泉宮，獨在驪山陬。","羣方趨順動，百辟隨天遊。"]', '["昔在軒轅朝，五城十二楼。","今我神泉宮，独在驪山陬。","羣方趨順动，百辟隨天游。"]', '诗', 'shi', '', NULL, '述華清宮五首 三 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b5036a9-e8ff-4b87-9a79-71baed7d10b0', '述華清宮五首 四', '述华清宮五首 四', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["正月開陽和，通門緝元化。","穆穆睟容歸，豈爲明燈夜。","高山大風起，肅肅隨龍駕。"]', '["正月开陽和，通门緝元化。","穆穆睟容归，豈爲明灯夜。","高山大风起，肅肅隨龙駕。"]', '诗', 'shi', '', NULL, '述華清宮五首 四 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82eef091-ce72-4483-b43d-b5fee95a1afc', '述華清宮五首 五', '述华清宮五首 五', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["上林神君宮，此地即明庭。","山開鴻濛色，天轉招搖星。","三雪報大有，孰爲非我靈。"]', '["上林神君宮，此地即明庭。","山开鴻濛色，天轉招搖星。","三雪報大有，孰爲非我靈。"]', '诗', 'shi', '', NULL, '述華清宮五首 五 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2295758a-d709-4f67-b0fa-86270479657e', '雜詠五首 石子松', '杂詠五首 石子松', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["盤石青巖下，松生盤石中。","冬春無異色，朝暮有清風。","五鬣何人采，西山舊兩童。"]', '["盤石青巖下，松生盤石中。","冬春無異色，朝暮有清风。","五鬣何人采，西山旧兩童。"]', '诗', 'shi', '', NULL, '雜詠五首 石子松 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('226dca1e-5a98-4f44-a3c1-aa76fbb7d166', '雜詠五首 架簷藤', '杂詠五首 架簷藤', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["得從軒墀下，殊勝松柏林。","生枝逐架遠，吐葉向門深。","何許答君子，簷間朝暝陰。"]', '["得從軒墀下，殊勝松柏林。","生枝逐架远，吐葉向门深。","何許答君子，簷间朝暝陰。"]', '诗', 'shi', '', NULL, '雜詠五首 架簷藤 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9977d464-9d73-4e6e-a8ff-ae70c3ad2b22', '雜詠五首 池邊鶴', '杂詠五首 池邊鹤', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["舞鶴傍池邊，水清毛羽鮮。","立如依岸雪，飛似向池泉。","江海雖言曠，無如君子前。"]', '["舞鹤傍池邊，水清毛羽鲜。","立如依岸雪，飞似向池泉。","江海雖言曠，無如君子前。"]', '诗', 'shi', '', NULL, '雜詠五首 池邊鶴 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74b8ae25-a739-49fc-8c2e-d3165ea6471c', '雜詠五首 釣魚灣', '杂詠五首 釣鱼灣', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["垂釣綠灣春，春深杏花亂。","潭清疑水淺，荷動知魚散。","日暮待情人，維舟綠楊岸。"]', '["垂釣綠灣春，春深杏花亂。","潭清疑水淺，荷动知鱼散。","日暮待情人，維舟綠楊岸。"]', '诗', 'shi', '', NULL, '雜詠五首 釣魚灣 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e811658a-f938-46ae-9acc-9d04d305c9b0', '雜詠五首 幽人居', '杂詠五首 幽人居', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["幽人下山徑，去去夾青林。","滑處莓苔濕，暗中蘿薜深。","春朝煙雨散，猶帶浮雲陰。"]', '["幽人下山徑，去去夾青林。","滑处莓苔濕，暗中蘿薜深。","春朝煙雨散，猶带浮云陰。"]', '诗', 'shi', '', NULL, '雜詠五首 幽人居 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('caa9b91e-7626-4baf-9d62-ef924a70022a', '題太玄觀', '題太玄观', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["門外車馬喧，門裏宮殿清。","行即翳若木，坐即吹玉笙。","所喧既非我，真道其冥冥。"]', '["门外车马喧，门裏宮殿清。","行即翳若木，坐即吹玉笙。","所喧既非我，真道其冥冥。"]', '诗', 'shi', '', NULL, '題太玄觀 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da1194a2-8f8a-4e96-b09e-bd7756bc3c5e', '至嵩陽觀觀即天皇故宅', '至嵩陽观观即天皇故宅', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["真人上清室，乃在中峰前。","花霧生玉井，霓裳畫列仙。","念茲宮故宇，多此地新泉。","松柏有清陰，薜蘿亦自妍。","一聞步虛子，又話逍遙篇。","忽若在雲漢，風中意泠然。"]', '["真人上清室，乃在中峰前。","花霧生玉井，霓裳畫列仙。","念茲宮故宇，多此地新泉。","松柏有清陰，薜蘿亦自妍。","一闻步虛子，又話逍遙篇。","忽若在云漢，风中意泠然。"]', '诗', 'shi', '', NULL, '至嵩陽觀觀即天皇故宅 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1493859d-0727-4927-b91b-e3444fc31c44', '貽韋鍊師', '貽韋鍊師', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["精思莫知日，意靜如空虛。","三鳥自來去，九光遙卷舒。","新池近天井，玉宇停雲車。","余亦苦山路，洗心祈道書。"]', '["精思莫知日，意静如空虛。","三鸟自来去，九光遙卷舒。","新池近天井，玉宇停云车。","余亦苦山路，洗心祈道书。"]', '诗', 'shi', '', NULL, '貽韋鍊師 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e6ebc0b-0134-4a55-aecd-2616e80cc74c', '霽後貽馬十二巽', '霽後貽马十二巽', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["高天風雨散，清氣在園林。","況我夜初靜，當軒鳴綠琴。","雲開北堂月，庭滿南山陰。","不見長裾者，空歌遊子吟。"]', '["高天风雨散，清氣在园林。","況我夜初静，當軒鳴綠琴。","云开北堂月，庭满南山陰。","不见长裾者，空歌游子吟。"]', '诗', 'shi', '', NULL, '霽後貽馬十二巽 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26409e2d-2a62-4860-982e-905713740b4e', '題陸山人樓', '題陸山人楼', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["暮聲雜初鴈，夜色涵早秋。","獨見海中月，照君池上樓。","山雲拂高棟，天漢入雲流。","不惜朝光滿，其如千里遊。"]', '["暮声杂初鴈，夜色涵早秋。","独见海中月，照君池上楼。","山云拂高棟，天漢入云流。","不惜朝光满，其如千里游。"]', '诗', 'shi', '', NULL, '題陸山人樓 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2565e126-7159-4b28-beec-f19a14cac556', '獻八舅東歸', '獻八舅东归', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["高位莫能捨，捨之世所賢。","雲車遊日華，豈比龍樓前。","寢疾乃就枕，情感唯靈仙。","帝鴻思道宗，臣彭亦長年。","天書加羽服，又許歸東川。","鏡水涵太清，禹山朝上玄。","誠亡真混沌，玉立方嬋娟。","素業作仙居，子孫當自傳。","門多松柏樹，篋有逍遙篇。","獨往不可羣，滄海成桑田。"]', '["高位莫能捨，捨之世所賢。","云车游日华，豈比龙楼前。","寢疾乃就枕，情感唯靈仙。","帝鴻思道宗，臣彭亦长年。","天书加羽服，又許归东川。","镜水涵太清，禹山朝上玄。","誠亡真混沌，玉立方嬋娟。","素業作仙居，子孫當自傳。","门多松柏樹，篋有逍遙篇。","独往不可羣，滄海成桑田。"]', '诗', 'shi', '', NULL, '獻八舅東歸 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c9313b8-bcef-45e5-b4ae-25e281307257', '泛茅山東溪', '泛茅山东溪', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["清晨登仙峰，峰遠行未極。","江海霽初景，草木含新色。","而我任天和，此時聊動息。","望鄉白雲裏，發棹清溪側。","松柏生深山，無心自貞直。"]', '["清晨登仙峰，峰远行未極。","江海霽初景，草木含新色。","而我任天和，此时聊动息。","望乡白云裏，發棹清溪側。","松柏生深山，無心自貞直。"]', '诗', 'shi', '', NULL, '泛茅山東溪 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3658ec58-110e-4eed-8761-5b8910883e8c', '喫茗粥作', '喫茗粥作', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["當晝暑氣盛，鳥雀靜不飛。","念君高梧陰，復解山中衣。","數片遠雲度，曾不蔽炎暉。","淹留膳茶粥，共我飯蕨薇。","敝廬既不遠，日暮徐徐歸。"]', '["當晝暑氣盛，鸟雀静不飞。","念君高梧陰，复解山中衣。","數片远云度，曾不蔽炎暉。","淹留膳茶粥，共我飯蕨薇。","敝廬既不远，日暮徐徐归。"]', '诗', 'shi', '', NULL, '喫茗粥作 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74afbaa0-bea6-4408-8268-5970cbc949e2', '遊茅山五首 一', '游茅山五首 一', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["十年別鄉縣，西去入皇州。","此意在觀國，不言空遠遊。","九衢平若水，利往無輕舟。","北洛反初路，東江還故丘。","春山多秀木，碧澗盡清流。","不見子桑扈，當從方外求。"]', '["十年別乡縣，西去入皇州。","此意在观国，不言空远游。","九衢平若水，利往無轻舟。","北洛反初路，东江還故丘。","春山多秀木，碧澗尽清流。","不见子桑扈，當從方外求。"]', '诗', 'shi', '', NULL, '遊茅山五首 一 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba855c71-24b1-441b-aaad-95428df93159', '遊茅山五首 二', '游茅山五首 二', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["世業傳儒行，行成非不榮。","其如懷獨善，況以聞長生。","家近華陽洞，早年深此情。","巾車雲路入，理棹瑤溪行。","天地朝光滿，江山春色明。","王庭有軒冕，此日方知輕。"]', '["世業傳儒行，行成非不榮。","其如懷独善，況以闻长生。","家近华陽洞，早年深此情。","巾车云路入，理棹瑤溪行。","天地朝光满，江山春色明。","王庭有軒冕，此日方知轻。"]', '诗', 'shi', '', NULL, '遊茅山五首 二 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89e360a8-7fa8-4dd8-aaf8-0a7080695a09', '遊茅山五首 三', '游茅山五首 三', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["平生非作者，望古懷清芬。","心以道爲際，行將時不羣。","茲山在人境，靈貺久傳聞。","遠勢一峰出，近形千嶂分。","冬春有茂草，朝暮多鮮雲。","此去亦何極，但言西日曛。"]', '["平生非作者，望古懷清芬。","心以道爲際，行將时不羣。","茲山在人境，靈貺久傳闻。","远勢一峰出，近形千嶂分。","冬春有茂草，朝暮多鲜云。","此去亦何極，但言西日曛。"]', '诗', 'shi', '', NULL, '遊茅山五首 三 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f949d6a1-f457-445b-9f1c-809694ece7c6', '遊茅山五首 四', '游茅山五首 四', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["昔賢居柱下，今我去人間。","良以直心曠，兼之外視閑。","垂綸非釣國，好學異希顏。","落日登高嶼，悠然望遠山。","溪流碧水去，雲帶清陰還。","想見中林士，巖扉長不關。"]', '["昔賢居柱下，今我去人间。","良以直心曠，兼之外視闲。","垂綸非釣国，好学異希顏。","落日登高嶼，悠然望远山。","溪流碧水去，云带清陰還。","想见中林士，巖扉长不关。"]', '诗', 'shi', '', NULL, '遊茅山五首 四 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a15619e-69d8-49a5-b319-8be60e4ec1f2', '遊茅山五首 五', '游茅山五首 五', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["名嶽徵仙事，清都訪道書。","山門入松柏，天路涵空虛。","南極見朝采，西潭聞夜漁。","遠心尚雲宿，浪跡出林居。","爲己存實際，忘形同化初。","此行良已矣，不樂復何如。"]', '["名嶽徵仙事，清都訪道书。","山门入松柏，天路涵空虛。","南極见朝采，西潭闻夜漁。","远心尚云宿，浪跡出林居。","爲己存實際，忘形同化初。","此行良已矣，不乐复何如。"]', '诗', 'shi', '', NULL, '遊茅山五首 五 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41a27c44-6404-4e6d-b7dc-202b2d87c35c', '述降聖觀', '述降聖观', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["一山盡天苑，一峰開道宮。","道花飛羽衞，天鳥遊雲空。","玉殿俯玄水，春旗搖素風。","夾門小松柏，覆井新梧桐。","自昔大仙下，乃知元化功。","神皇作桂館，此意與天通。"]', '["一山尽天苑，一峰开道宮。","道花飞羽衞，天鸟游云空。","玉殿俯玄水，春旗搖素风。","夾门小松柏，覆井新梧桐。","自昔大仙下，乃知元化功。","神皇作桂館，此意與天通。"]', '诗', 'shi', '', NULL, '述降聖觀 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e67e320-c626-401e-a546-e768e8fcf993', '題眄上人禪居', '題眄上人禪居', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["真王清淨子，燕居復行心。","結宇鄰居邑，寤言非遠尋。","丹青丈室滿，草樹一庭深。","秀色玄冬發，交枝白日陰。","江流暎朱戶，山鳥鳴香林。","獨住已寂寂，安知浮與沈。"]', '["真王清淨子，燕居复行心。","結宇鄰居邑，寤言非远尋。","丹青丈室满，草樹一庭深。","秀色玄冬發，交枝白日陰。","江流暎朱戶，山鸟鳴香林。","独住已寂寂，安知浮與沈。"]', '诗', 'shi', '', NULL, '題眄上人禪居 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b35f4e36-2000-4a2e-9500-37318c52f3f3', '過新豐道中', '過新豐道中', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["西下長樂坂，東入新豐道。","雨多車馬稀，道上生秋草。","太陰蔽臯陸，莫知晚與早。","雷雨杳冥冥，川谷漫浩浩。","詔書植嘉木，衆言桃李好。","自媿無此容，歸從漢陰老。"]', '["西下长乐坂，东入新豐道。","雨多车马稀，道上生秋草。","太陰蔽臯陸，莫知晚與早。","雷雨杳冥冥，川谷漫浩浩。","詔书植嘉木，衆言桃李好。","自媿無此容，归從漢陰老。"]', '诗', 'shi', '', NULL, '過新豐道中 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b5fb428-57f2-45e8-bd6b-ed61ebce6fcd', '夜到洛口入黃河', '夜到洛口入黄河', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["河洲多青草，朝暮增客愁。","客愁惜朝暮，枉渚蹔停舟。","中宵大川靜，解纜逐歸流。","浦漵既清曠，沿洄非阻修。","登艫望落月，擊汰悲新秋。","倘遇乘槎客，永言星漢遊。"]', '["河洲多青草，朝暮增客愁。","客愁惜朝暮，枉渚蹔停舟。","中宵大川静，解纜逐归流。","浦漵既清曠，沿洄非阻修。","登艫望落月，擊汰悲新秋。","倘遇乘槎客，永言星漢游。"]', '诗', 'shi', '', NULL, '夜到洛口入黃河 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b2be217-4c67-40b7-98fc-4f15fae0f25d', '使過彈箏峽作', '使過彈箏峽作', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["鳥雀知天雪，羣飛復羣鳴。","原田無遺粟，日暮滿空城。","達士憂世務，鄙夫念王程。","晨過彈箏峽，馬足凌兢行。","雙壁隱靈曜，莫能知晦明。","皚皚堅冰白，漫漫陰雲平。","始信古人言，苦節不可貞。"]', '["鸟雀知天雪，羣飞复羣鳴。","原田無遺粟，日暮满空城。","達士憂世務，鄙夫念王程。","晨過彈箏峽，马足凌兢行。","雙壁隐靈曜，莫能知晦明。","皚皚堅冰白，漫漫陰云平。","始信古人言，苦節不可貞。"]', '诗', 'shi', '', NULL, '使過彈箏峽作 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c776c897-2104-4261-8517-9dd0c729395e', '泊舟貽潘少府', '泊舟貽潘少府', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["行子苦風潮，維舟未能發。","宵分卷前幔，臥視清秋月。","四澤蒹葭深，中洲煙火絕。","蒼蒼水霧起，落落疎星沒。","所遇盡漁商，與言多楚越。","其如念極浦，又以思明哲。","常若千里餘，況之異鄉別。"]', '["行子苦风潮，維舟未能發。","宵分卷前幔，臥視清秋月。","四澤蒹葭深，中洲煙火絕。","蒼蒼水霧起，落落疎星沒。","所遇尽漁商，與言多楚越。","其如念極浦，又以思明哲。","常若千里餘，況之異乡別。"]', '诗', 'shi', '', NULL, '泊舟貽潘少府 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34fbd63f-f80a-4ca2-8842-e5f9ddbbc943', '仲夏入園中東陂', '仲夏入园中东陂', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["方塘深且廣，伊昔俯吾廬。","環岸垂綠柳，盈澤發紅蕖。","上延北原秀，下屬幽人居。","暑雨若混沌，清明如空虛。","此鄉多隱逸，水陸見樵漁。","廢賞亦何貴，爲歡良易攄。","且言重觀國，當此賦歸歟。"]', '["方塘深且廣，伊昔俯吾廬。","环岸垂綠柳，盈澤發紅蕖。","上延北原秀，下屬幽人居。","暑雨若混沌，清明如空虛。","此乡多隐逸，水陸见樵漁。","廢賞亦何貴，爲歡良易攄。","且言重观国，當此賦归歟。"]', '诗', 'shi', '', NULL, '仲夏入園中東陂 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('411d50c5-64f7-49e4-bb04-040b8633fa87', '效古二首 一', '效古二首 一', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["晨登涼風臺，暮走邯鄲道。","曜靈何赫烈，四野無青草。","大軍北集燕，天子西居鎬。","婦人役州縣，丁男事征討。","老幼相別離，哭泣無昏早。","稼穡既殄絕，川澤復枯槁。","曠哉遠此憂，冥冥商山皓。"]', '["晨登涼风台，暮走邯鄲道。","曜靈何赫烈，四野無青草。","大軍北集燕，天子西居鎬。","婦人役州縣，丁男事征討。","老幼相別離，哭泣無昏早。","稼穡既殄絕，川澤复枯槁。","曠哉远此憂，冥冥商山皓。"]', '诗', 'shi', '', NULL, '效古二首 一 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b68bbb5c-3aa4-4649-9202-dabdb523519e', '效古二首 二', '效古二首 二', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["東風吹大河，河水如倒流。","河洲塵沙起，有若黃雲浮。","赬霞燒廣澤，洪曜赫高丘。","野老泣相語，無地可蔭休。","翰林有客卿，獨負蒼生憂。","中夜起躑躅，思欲獻厥謀。","君門峻且深，踠足空夷猶。"]', '["东风吹大河，河水如倒流。","河洲塵沙起，有若黄云浮。","赬霞燒廣澤，洪曜赫高丘。","野老泣相語，無地可蔭休。","翰林有客卿，独負蒼生憂。","中夜起躑躅，思欲獻厥謀。","君门峻且深，踠足空夷猶。"]', '诗', 'shi', '', NULL, '效古二首 二 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a3148e7-97cf-4a62-b8e4-a0ecf7064b15', '雜詩二首 一', '杂诗二首 一', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["混沌本無象，末路多是非。","達士志寥廓，所在能忘禨。","耕鑿時未至，還山聊采薇。","虎豹對我蹲，鸑鷟旁我飛。","仙人空中來，謂我勿復歸。","格澤爲君駕，虹蜺爲君衣。","西遊崑崙墟，可與世人違。"]', '["混沌本無象，末路多是非。","達士志寥廓，所在能忘禨。","耕鑿时未至，還山聊采薇。","虎豹对我蹲，鸑鷟旁我飞。","仙人空中来，謂我勿复归。","格澤爲君駕，虹蜺爲君衣。","西游崑崙墟，可與世人違。"]', '诗', 'shi', '', NULL, '雜詩二首 一 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8141f67-1f00-4d17-9b81-28aac0264590', '雜詩二首 二', '杂诗二首 二', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["秋氣肅天地，太行高崔嵬。","猨狖清夜吟，其聲一何哀。","寂寞掩圭蓽，夢寐遊蓬萊。","琪樹遠亭亭，玉堂雲中開。","洪崖吹簫管，玉女飄颻來。","雨師既先後，道路無纖埃。","鄙哉楚襄王，獨好陽雲臺。"]', '["秋氣肅天地，太行高崔嵬。","猨狖清夜吟，其声一何哀。","寂寞掩圭蓽，梦寐游蓬萊。","琪樹远亭亭，玉堂云中开。","洪崖吹簫管，玉女飄颻来。","雨師既先後，道路無纖埃。","鄙哉楚襄王，独好陽云台。"]', '诗', 'shi', '', NULL, '雜詩二首 二 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('289e14b7-4e83-4968-9491-e141e44e883d', '陸著作挽歌 一', '陸著作挽歌 一', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["世業江湖側，郊原休沐處。","獨言五日歸，未道千秋去。","鄉亭春水綠，昌閣寒光暮。","昔爲晝錦遊，今成逝川路。"]', '["世業江湖側，郊原休沐处。","独言五日归，未道千秋去。","乡亭春水綠，昌閣寒光暮。","昔爲晝錦游，今成逝川路。"]', '诗', 'shi', '', NULL, '陸著作挽歌 一 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b835e44-8fd3-40b9-ae17-da1533a2bbf8', '陸著作挽歌 二', '陸著作挽歌 二', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["歸路秦城下，寒雲慘平田。","故園滄海邊，綠柳覆平川。","送客異他日，還舟殊昔年。","華亭有明月，長向隴頭懸。"]', '["归路秦城下，寒云慘平田。","故园滄海邊，綠柳覆平川。","送客異他日，還舟殊昔年。","华亭有明月，长向隴头懸。"]', '诗', 'shi', '', NULL, '陸著作挽歌 二 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63ba36c8-6e5d-49de-ab6d-9e696d978a3b', '陸著作挽歌 三', '陸著作挽歌 三', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["劍水千人石，荆江萬里流。","英英有君子，才德滿中州。","明道俟良佐，惟賢初薄遊。","生涯一朝盡，寂寞夜臺幽。"]', '["劍水千人石，荆江万里流。","英英有君子，才德满中州。","明道俟良佐，惟賢初薄游。","生涯一朝尽，寂寞夜台幽。"]', '诗', 'shi', '', NULL, '陸著作挽歌 三 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca396722-5b4c-4b44-bb09-1a81beac7286', '陸著作挽歌 四', '陸著作挽歌 四', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["金堂策令名，仙掖居清位。","鳴玉朝雙闕，垂纓遊兩地。","朝夕既論思，春秋仍書事。","何言魯聲伯，忽下瓊珠淚。"]', '["金堂策令名，仙掖居清位。","鳴玉朝雙闕，垂纓游兩地。","朝夕既論思，春秋仍书事。","何言魯声伯，忽下瓊珠泪。"]', '诗', 'shi', '', NULL, '陸著作挽歌 四 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b3fe4cc-76d6-4f91-bab1-2e235fdbad16', '陸著作挽歌 五', '陸著作挽歌 五', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["令德棄人世，明朝降寵章。","起居存有位，著作沒爲郎。","寒水落南浦，月華虛北堂。","松門一長想，彷彿見清揚。"]', '["令德棄人世，明朝降寵章。","起居存有位，著作沒爲郎。","寒水落南浦，月华虛北堂。","松门一长想，彷彿见清揚。"]', '诗', 'shi', '', NULL, '陸著作挽歌 五 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cda93da7-799f-4307-a5f8-5338b4c98375', '山居貽裴十二迪', '山居貽裴十二迪', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["落葉滿山砌，蒼煙埋竹扉。","遠懷青冥士，書劒常相依。","霜臥眇茲地，琴言紛已違。","衡陽今萬里，南雁將何歸。","出徑惜松引，入舟憐釣磯。","西林有明月，夜久空微微。"]', '["落葉满山砌，蒼煙埋竹扉。","远懷青冥士，书劒常相依。","霜臥眇茲地，琴言紛已違。","衡陽今万里，南雁將何归。","出徑惜松引，入舟怜釣磯。","西林有明月，夜久空微微。"]', '诗', 'shi', '', NULL, '山居貽裴十二迪 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f55bc09-3baf-4335-acb6-3eb3d1bda0c4', '秦中歲晏馬舍人宅宴集', '秦中歲晏马舍人宅宴集', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["冬暮久無樂，西行至長安。","故人處東第，清夜多新歡。","廣庭竹陰靜，華池月色寒。","知音盡詞客，方見交情難。"]', '["冬暮久無乐，西行至长安。","故人处东第，清夜多新歡。","廣庭竹陰静，华池月色寒。","知音尽词客，方见交情难。"]', '诗', 'shi', '', NULL, '秦中歲晏馬舍人宅宴集 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf380f86-29a3-4088-8ae1-c77568b1d13e', '薦玄德公廟', '薦玄德公廟', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["神道本無已，成化亦自然。","君居寥天上，德在玉華泉。","真遊踐王豫，永日遲雲仙。","表微在營道，明祀將祈年。","靈山俯新邑，松上生彩煙。","豈知穆天子，遠去瑤池邊。"]', '["神道本無已，成化亦自然。","君居寥天上，德在玉华泉。","真游踐王豫，永日遲云仙。","表微在營道，明祀將祈年。","靈山俯新邑，松上生彩煙。","豈知穆天子，远去瑤池邊。"]', '诗', 'shi', '', NULL, '薦玄德公廟 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52c412ea-32e0-41df-9ff1-3dbf6e0415d8', '上長史王公責躬', '上长史王公責躬', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["覆舟無伯夷，覆車無仲尼。","自咎失明義，寧由貝錦詩。","松柏日已堅，桃李日以滋。","顧己獨暗昧，所居成蒺藜。","大賢薦時文，醜婦用蛾眉。","惕惕愧不已，豈敢論其私。","方朔既有言，子建亦有詩。","惻隱及先世，析薪成自悲。","靈鳥酬德輝，黃雀報仁慈。","若公庶伏罪，此事安能遲。"]', '["覆舟無伯夷，覆车無仲尼。","自咎失明義，寧由貝錦诗。","松柏日已堅，桃李日以滋。","顧己独暗昧，所居成蒺藜。","大賢薦时文，醜婦用蛾眉。","惕惕愧不已，豈敢論其私。","方朔既有言，子建亦有诗。","惻隐及先世，析薪成自悲。","靈鸟酬德輝，黄雀報仁慈。","若公庶伏罪，此事安能遲。"]', '诗', 'shi', '', NULL, '上長史王公責躬 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71eb1de4-46ce-451c-ac03-bff775feb664', '至嶽寺即大通大照禪塔上溫上人', '至嶽寺即大通大照禪塔上溫上人', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["秋山下暎宮，宮色宜朝陽。","迢遞在半嶺，參差非一行。","燕息雲滿門，出遊花隱房。","二尊此成道，禪宇遙相望。","鳳鐸天中鳴，巖梯松下長。","山墟響信鼓，蘅薄生蕙香。","起滅一以雪，往來亦誠亡。","悲哉門弟子，要自知心長。"]', '["秋山下暎宮，宮色宜朝陽。","迢遞在半嶺，參差非一行。","燕息云满门，出游花隐房。","二尊此成道，禪宇遙相望。","鳳鐸天中鳴，巖梯松下长。","山墟响信鼓，蘅薄生蕙香。","起滅一以雪，往来亦誠亡。","悲哉门弟子，要自知心长。"]', '诗', 'shi', '', NULL, '至嶽寺即大通大照禪塔上溫上人 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8b646d0-8a7b-4d7e-9bdb-bd5d30646bf3', '終南幽居獻蘇侍郎三首時拜太祝未上 一', '終南幽居獻蘇侍郎三首时拜太祝未上 一', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["暮春天氣和，登嶺望層城。","朝日懸清景，巍峨宮殿明。","聖君常臨朝，達士復懸衡。","道近燕艮足，歸來臥山楹。","靈堦曝仙書，深室煉金英。","春巖松柏秀，晨路鵾雞鳴。","羽化既有言，無然悲不成。"]', '["暮春天氣和，登嶺望層城。","朝日懸清景，巍峨宮殿明。","聖君常臨朝，達士复懸衡。","道近燕艮足，归来臥山楹。","靈堦曝仙书，深室煉金英。","春巖松柏秀，晨路鵾雞鳴。","羽化既有言，無然悲不成。"]', '诗', 'shi', '', NULL, '終南幽居獻蘇侍郎三首時拜太祝未上 一 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df98c532-426e-4342-a35a-915724ff2e06', '終南幽居獻蘇侍郎三首時拜太祝未上 二', '終南幽居獻蘇侍郎三首时拜太祝未上 二', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["中歲尚微道，始知將谷神。","抗策還南山，水木自相親。","深林開一道，青嶂成四鄰。","平明去采薇，日入行刈薪。","雲歸萬壑暗，雪罷千崖春。","始看玄鳥來，已見瑤華新。","寄言搴芳者，無乃後時人。"]', '["中歲尚微道，始知將谷神。","抗策還南山，水木自相親。","深林开一道，青嶂成四鄰。","平明去采薇，日入行刈薪。","云归万壑暗，雪罷千崖春。","始看玄鸟来，已见瑤华新。","寄言搴芳者，無乃後时人。"]', '诗', 'shi', '', NULL, '終南幽居獻蘇侍郎三首時拜太祝未上 二 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d7cfedc-35ae-4cfb-9768-70571345db5c', '終南幽居獻蘇侍郎三首時拜太祝未上 三', '終南幽居獻蘇侍郎三首时拜太祝未上 三', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["卜築青巖裏，雲蘿四垂陰。","虛室若無人，喬木自成林。","時有清風至，側聞樵採音。","鳳皇鳴南岡，望望隔層岑。","既言山路遠，復道溪流深。","偓佺空中遊，虯龍水間吟。","何當見輕翼，爲我達遠心。"]', '["卜築青巖裏，云蘿四垂陰。","虛室若無人，喬木自成林。","时有清风至，側闻樵採音。","鳳皇鳴南岡，望望隔層岑。","既言山路远，复道溪流深。","偓佺空中游，虯龙水间吟。","何當见轻翼，爲我達远心。"]', '诗', 'shi', '', NULL, '終南幽居獻蘇侍郎三首時拜太祝未上 三 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d26ecc0e-2a13-45ba-8bf6-e8b333afcd0e', '題應聖觀', '題應聖观', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["空中望小山，山下見餘雪。","皎皎河漢女，在茲養真骨。","登門駭天書，啓籥問仙訣。","池光搖水霧，燈色連松月。","合甎起花臺，折草成玉節。","天雞弄白羽，王母垂玄髮。","北有上年宮，一路在雲霓。","上心方嚮道，時復朝金闕。"]', '["空中望小山，山下见餘雪。","皎皎河漢女，在茲養真骨。","登门駭天书，啓籥问仙訣。","池光搖水霧，灯色連松月。","合甎起花台，折草成玉節。","天雞弄白羽，王母垂玄髮。","北有上年宮，一路在云霓。","上心方嚮道，时复朝金闕。"]', '诗', 'shi', '', NULL, '題應聖觀 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08c5e20f-2f21-4f62-8e7f-0d1c4238606d', '至閑居精舍呈正上人', '至闲居精舍呈正上人', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["太室三招提，其趣皆不同。","不同非一趣，況是天遊宮。","雙嶺前夾門，閣道復橫空。","寶坊若花積，宛轉不可窮。","流泉自成池，清松信饒風。","秋晏景氣逈，皛明丹素功。","將近隱者鄰，遠與西山通。","大師假惠照，念以息微躬。"]', '["太室三招提，其趣皆不同。","不同非一趣，況是天游宮。","雙嶺前夾门，閣道复橫空。","寶坊若花積，宛轉不可窮。","流泉自成池，清松信饒风。","秋晏景氣逈，皛明丹素功。","將近隐者鄰，远與西山通。","大師假惠照，念以息微躬。"]', '诗', 'shi', '', NULL, '至閑居精舍呈正上人 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5481f438-f97a-496f-b2aa-33627742a098', '酬綦毋校書夢耶溪見贈之作', '酬綦毋校书梦耶溪见贈之作', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["校文在仙掖，每有滄洲心。","況以北窗下，夢遊清溪陰。","春看湖水漫，夜入迴塘深。","往往纜垂葛，出舟望前林。","山人松下飯，釣客蘆中吟。","小隱何足貴，長年固可尋。","還車首東道，惠言若黃金。","以我采薇意，傳之天姥岑。"]', '["校文在仙掖，每有滄洲心。","況以北窗下，梦游清溪陰。","春看湖水漫，夜入迴塘深。","往往纜垂葛，出舟望前林。","山人松下飯，釣客蘆中吟。","小隐何足貴，长年固可尋。","還车首东道，惠言若黄金。","以我采薇意，傳之天姥岑。"]', '诗', 'shi', '', NULL, '酬綦毋校書夢耶溪見贈之作 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('090bbd6f-73ea-4461-87d1-ff763bb36a09', '田家即事', '田家即事', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["蒲葉日已長，杏花日已滋。","老農要看此，貴不違天時。","迎晨起飯牛，雙駕耕東菑。","蚯蚓土中出，田烏隨我飛。","羣合亂啄噪，嗷嗷如道飢。","我心多惻隱，顧此兩傷悲。","撥食與田烏，日暮空筐歸。","親戚更相誚，我心終不移。"]', '["蒲葉日已长，杏花日已滋。","老農要看此，貴不違天时。","迎晨起飯牛，雙駕耕东菑。","蚯蚓土中出，田烏隨我飞。","羣合亂啄噪，嗷嗷如道飢。","我心多惻隐，顧此兩傷悲。","撥食與田烏，日暮空筐归。","親戚更相誚，我心終不移。"]', '诗', 'shi', '', NULL, '田家即事 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd3b61f9-7467-4d6f-b3f8-42324c85822e', '同王十三維偶然作十首 一', '同王十三維偶然作十首 一', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["仲夏日中時，草木看欲燋。","田家惜工力，把鋤來東臯。","顧望浮雲陰，往往誤傷苗。","歸來悲困極，兄嫂共相譊。","無錢可沽酒，何以解劬勞？","夜深星漢明，庭宇虛寥寥。","高柳三五株，可以獨逍遙。"]', '["仲夏日中时，草木看欲燋。","田家惜工力，把鋤来东臯。","顧望浮云陰，往往誤傷苗。","归来悲困極，兄嫂共相譊。","無錢可沽酒，何以解劬勞？","夜深星漢明，庭宇虛寥寥。","高柳三五株，可以独逍遙。"]', '诗', 'shi', '', NULL, '同王十三維偶然作十首 一 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0d480e9-f100-4ebe-bb05-0de13d73113b', '同王十三維偶然作十首 二', '同王十三維偶然作十首 二', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["北山種松柏，南山種蒺藜。","出入雖同趣，所向各有宜。","孔丘貴仁義，老氏好無爲。","我心若虛空，此道將安施。","暫過伊闕間，晼晚三伏時。","高閣入雲中，芙蓉滿清池。","要自非我室，還望南山陲。"]', '["北山種松柏，南山種蒺藜。","出入雖同趣，所向各有宜。","孔丘貴仁義，老氏好無爲。","我心若虛空，此道將安施。","暫過伊闕间，晼晚三伏时。","高閣入云中，芙蓉满清池。","要自非我室，還望南山陲。"]', '诗', 'shi', '', NULL, '同王十三維偶然作十首 二 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb811375-9dfb-4b56-ad3c-2fa584180ac4', '同王十三維偶然作十首 三', '同王十三維偶然作十首 三', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["野老本貧賤，冒暑鋤瓜田。","一畦未及終，樹下高枕眠。","荷蓧者誰子，皤皤來息肩。","不復問鄉墟，相見但依然。","腹中無一物，高話羲皇年。","落日臨層隅，逍遙望晴川。","使婦提蠶筐，呼兒榜漁船。","悠悠泛綠水，去摘浦中蓮。","蓮花豔且美，使我不能還。"]', '["野老本貧賤，冒暑鋤瓜田。","一畦未及終，樹下高枕眠。","荷蓧者誰子，皤皤来息肩。","不复问乡墟，相见但依然。","腹中無一物，高話羲皇年。","落日臨層隅，逍遙望晴川。","使婦提蠶筐，呼兒榜漁船。","悠悠泛綠水，去摘浦中蓮。","蓮花豔且美，使我不能還。"]', '诗', 'shi', '', NULL, '同王十三維偶然作十首 三 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d233e41-411e-4e28-b7bd-302fbee385e7', '同王十三維偶然作十首 四', '同王十三維偶然作十首 四', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["浮雲在虛空，隨風復卷舒。","我心方處順，動作何憂虞。","但言嬰世網，不復得間居。","迢遞別東國，超遙來西都。","見人乃恭敬，曾不問賢愚。","雖若不能言，中心亦難誣。","故鄉滿親戚，道遠情日疎。","偶欲陳此意，復無南飛鳧。"]', '["浮云在虛空，隨风复卷舒。","我心方处順，动作何憂虞。","但言嬰世網，不复得间居。","迢遞別东国，超遙来西都。","见人乃恭敬，曾不问賢愚。","雖若不能言，中心亦难誣。","故乡满親戚，道远情日疎。","偶欲陳此意，复無南飞鳧。"]', '诗', 'shi', '', NULL, '同王十三維偶然作十首 四 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c20c3f6-8146-4946-ae6f-8d7596196165', '同王十三維偶然作十首 五', '同王十三維偶然作十首 五', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["草木花葉生，相與命爲春。","當非草木意，信是故時人。","靜念惻羣物，何由知至真。","狂歌問夫子，夫子莫能陳。","鳳皇飛且鳴，容裔下天津。","清淨無言語，茲焉庶可親。"]', '["草木花葉生，相與命爲春。","當非草木意，信是故时人。","静念惻羣物，何由知至真。","狂歌问夫子，夫子莫能陳。","鳳皇飞且鳴，容裔下天津。","清淨無言語，茲焉庶可親。"]', '诗', 'shi', '', NULL, '同王十三維偶然作十首 五 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65401677-a0e6-4d31-932f-eb958779a2f0', '同王十三維偶然作十首 六', '同王十三維偶然作十首 六', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["黃河流向東，弱水流向西。","趨舍各有異，造化安能齊。","妾本邯鄲女，生長在叢臺。","既聞容見寵，復想玄爲妻。","刻畫尚風流，幸會君招攜。","逶迤歌舞座，婉孌芙蓉閨。","日月方向除，恩愛忽焉暌。","棄置誰復道，但悲生不諧。","羨彼匹婦意，偕老常同棲。"]', '["黄河流向东，弱水流向西。","趨舍各有異，造化安能齊。","妾本邯鄲女，生长在叢台。","既闻容见寵，复想玄爲妻。","刻畫尚风流，幸會君招携。","逶迤歌舞座，婉孌芙蓉閨。","日月方向除，恩愛忽焉暌。","棄置誰复道，但悲生不諧。","羨彼匹婦意，偕老常同棲。"]', '诗', 'shi', '', NULL, '同王十三維偶然作十首 六 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e93a8da2-85de-45dc-bacc-8f1ac591eba3', '同王十三維偶然作十首 七', '同王十三維偶然作十首 七', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["日暮登春山，山鮮雲復輕。","遠近看春色，踟躕新月明。","仙人浮丘公，對月時吹笙。","丹鳥飛熠熠，蒼蠅亂營營。","羣動汩吾真，訛言傷我情。","安得如子晉，與之遊太清。"]', '["日暮登春山，山鲜云复轻。","远近看春色，踟躕新月明。","仙人浮丘公，对月时吹笙。","丹鸟飞熠熠，蒼蠅亂營營。","羣动汩吾真，訛言傷我情。","安得如子晉，與之游太清。"]', '诗', 'shi', '', NULL, '同王十三維偶然作十首 七 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f558ee81-6086-4c77-beea-594e062259a7', '同王十三維偶然作十首 八', '同王十三維偶然作十首 八', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["耽耽銅鞮宮，遙望長數里。","賓客無多少，出入皆珠履。","樸儒亦何爲，辛苦讀舊史。","不道無家舍，效他養妻子。","冽冽玄冬暮，衣裳無準擬。","偶然著道書，神人養生理。","公卿時見賞，賜賚難具紀。","莫問身後事，且論朝夕是。"]', '["耽耽銅鞮宮，遙望长數里。","賓客無多少，出入皆珠履。","樸儒亦何爲，辛苦读旧史。","不道無家舍，效他養妻子。","冽冽玄冬暮，衣裳無準擬。","偶然著道书，神人養生理。","公卿时见賞，賜賚难具紀。","莫问身後事，且論朝夕是。"]', '诗', 'shi', '', NULL, '同王十三維偶然作十首 八 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f310916a-38d5-4493-a022-e8332a163322', '同王十三維偶然作十首 九', '同王十三維偶然作十首 九', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["空山暮雨來，衆鳥竟棲息。","斯須照夕陽，雙雙復撫翼。","我念天時好，東田有稼穡。","浮雲蔽川原，新流集溝洫。","裴回顧衡宇，僮僕邀我食。","臥覽牀頭書，睡看機中織。","想見明膏煎，中夜起唧唧。"]', '["空山暮雨来，衆鸟竟棲息。","斯須照夕陽，雙雙复撫翼。","我念天时好，东田有稼穡。","浮云蔽川原，新流集溝洫。","裴回顧衡宇，僮僕邀我食。","臥覽牀头书，睡看機中织。","想见明膏煎，中夜起唧唧。"]', '诗', 'shi', '', NULL, '同王十三維偶然作十首 九 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('165f3bc8-57e6-4046-88a2-f0325b7081c7', '同王十三維偶然作十首 十', '同王十三維偶然作十首 十', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["四鄰競豐屋，我獨好卑室。","窈窕高臺中，時聞撫新瑟。","狂飆動地起，拔木乃非一。","相顧始知悲，中心憂且慄。","蚩蚩命子弟，恨不居高秩。","日入賓從歸，清晨冠蓋出。","中庭有奇樹，榮早衰復疾。","此道猶不知，微言安可述。"]', '["四鄰競豐屋，我独好卑室。","窈窕高台中，时闻撫新瑟。","狂飆动地起，拔木乃非一。","相顧始知悲，中心憂且慄。","蚩蚩命子弟，恨不居高秩。","日入賓從归，清晨冠蓋出。","中庭有奇樹，榮早衰复疾。","此道猶不知，微言安可述。"]', '诗', 'shi', '', NULL, '同王十三維偶然作十首 十 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2daf737-459a-485c-b970-96d7ddc460e8', '昇天行貽盧六健', '昇天行貽盧六健', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["真人居閬風，時奏清商音。","聽者即王母，泠泠和瑟琴。","坐對三花枝，行隨五雲陰。","天長崑崙小，日久蓬萊深。","上由玉華宮，下視首陽岑。","神州亦清淨，要自有浮沈。","惻惻苦哉行，呱呱遊子吟。","廬山逢若士，思欲化黃金。","雨雪沒太山，誰能無歸心。","逍遙在雲漢，可以來相尋。"]', '["真人居閬风，时奏清商音。","听者即王母，泠泠和瑟琴。","坐对三花枝，行隨五云陰。","天长崑崙小，日久蓬萊深。","上由玉华宮，下視首陽岑。","神州亦清淨，要自有浮沈。","惻惻苦哉行，呱呱游子吟。","廬山逢若士，思欲化黄金。","雨雪沒太山，誰能無归心。","逍遙在云漢，可以来相尋。"]', '诗', 'shi', '', NULL, '昇天行貽盧六健 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1f7e0de-a0ed-49e7-9f58-e29273d52c87', '田家雜興八首 一', '田家杂兴八首 一', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["春至鶬鶊鳴，薄言向田墅。","不能自力作，黽勉娶鄰女。","既念生子孫，方思廣田圃。","閑時相顧笑，喜悅好禾黍。","夜夜登嘯臺，南望洞庭渚。","百草被霜露，秋山響砧杵。","却羨故年時，中情無所取。"]', '["春至鶬鶊鳴，薄言向田墅。","不能自力作，黽勉娶鄰女。","既念生子孫，方思廣田圃。","闲时相顧笑，喜悅好禾黍。","夜夜登嘯台，南望洞庭渚。","百草被霜露，秋山响砧杵。","却羨故年时，中情無所取。"]', '诗', 'shi', '', NULL, '田家雜興八首 一 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('459aa485-e005-4fce-8ce2-98dc25417d9d', '田家雜興八首 二', '田家杂兴八首 二', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["衆人恥貧賤，相與尚膏腴。","我情既浩蕩，所樂在畋漁。","山澤時晦暝，歸家蹔閑居。","滿園植葵藿，繞屋樹桑榆。","禽雀知我閑，翔集依我廬。","所願在優游，州縣莫相呼。","日與南山老，兀然傾一壺。"]', '["衆人恥貧賤，相與尚膏腴。","我情既浩蕩，所乐在畋漁。","山澤时晦暝，归家蹔闲居。","满园植葵藿，繞屋樹桑榆。","禽雀知我闲，翔集依我廬。","所願在優游，州縣莫相呼。","日與南山老，兀然傾一壺。"]', '诗', 'shi', '', NULL, '田家雜興八首 二 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88e3e2c9-c6b3-4413-9fff-43c222118164', '田家雜興八首 三', '田家杂兴八首 三', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["逍遙阡陌上，遠近無相識。","落日照秋山，千巖同一色。","網罟繞深莽，鷹鸇始輕翼。","獵馬既如風，奔獸莫敢息。","駐旗滄海上，犒士吳宮側。","楚國有夫人，性情本貞直。","鮮禽徒自致，終歲竟不食。"]', '["逍遙阡陌上，远近無相識。","落日照秋山，千巖同一色。","網罟繞深莽，鷹鸇始轻翼。","獵马既如风，奔獸莫敢息。","駐旗滄海上，犒士吳宮側。","楚国有夫人，性情本貞直。","鲜禽徒自致，終歲竟不食。"]', '诗', 'shi', '', NULL, '田家雜興八首 三 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6585b742-5745-45dc-a4e3-3df3ac3efbf4', '田家雜興八首 四', '田家杂兴八首 四', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["田家趨壠畝，當晝掩虛關。","鄰里無煙火，兒童共幽閑。","桔槔懸空圃，雞犬滿桑間。","時來農事隙，採藥遊名山。","但言所採多，不念路險艱。","人生如蜉蝣，一往不可攀。","君看西王母，千載美容顏。"]', '["田家趨壠畝，當晝掩虛关。","鄰里無煙火，兒童共幽闲。","桔槔懸空圃，雞犬满桑间。","时来農事隙，採藥游名山。","但言所採多，不念路險艱。","人生如蜉蝣，一往不可攀。","君看西王母，千載美容顏。"]', '诗', 'shi', '', NULL, '田家雜興八首 四 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd025c4a-1535-49bc-934b-30e1a9e5dbd8', '田家雜興八首 五', '田家杂兴八首 五', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["平生養情性，不復計憂樂。","去家行賣畚，留滯南陽郭。","秋至黍苗黃，無人可刈獲。","稚子朝未飯，把竿逐鳥雀。","忽見梁將軍，乘車出宛洛。","意氣軼道路，光輝滿墟落。","安知負薪者，咥咥笑輕薄。"]', '["平生養情性，不复計憂乐。","去家行賣畚，留滯南陽郭。","秋至黍苗黄，無人可刈獲。","稚子朝未飯，把竿逐鸟雀。","忽见梁將軍，乘车出宛洛。","意氣軼道路，光輝满墟落。","安知負薪者，咥咥笑轻薄。"]', '诗', 'shi', '', NULL, '田家雜興八首 五 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5df45fd4-9419-476d-88ef-28718330e3b5', '田家雜興八首 六', '田家杂兴八首 六', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["楚山有高士，梁國有遺老。","築室既相鄰，向田復同道。","糗糒常共飯，兒孫每更抱。","忘此耕耨勞，媿彼風雨好。","蟪蛄鳴空澤，鶗鴂傷秋草。","日夕寒風來，衣裳苦不早。"]', '["楚山有高士，梁国有遺老。","築室既相鄰，向田复同道。","糗糒常共飯，兒孫每更抱。","忘此耕耨勞，媿彼风雨好。","蟪蛄鳴空澤，鶗鴂傷秋草。","日夕寒风来，衣裳苦不早。"]', '诗', 'shi', '', NULL, '田家雜興八首 六 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9702a6a1-f1c5-4f0a-a8c4-e878c4a26bd6', '田家雜興八首 七', '田家杂兴八首 七', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["梧桐蔭我門，薜荔網我屋。","迢迢兩夫婦，朝出暮還宿。","稼穡既自種，牛羊還自牧。","日旰懶耕鋤，登高望川陸。","空山足禽獸，墟落多喬木。","白馬誰家兒，聯翩相馳逐。"]', '["梧桐蔭我门，薜荔網我屋。","迢迢兩夫婦，朝出暮還宿。","稼穡既自種，牛羊還自牧。","日旰懶耕鋤，登高望川陸。","空山足禽獸，墟落多喬木。","白马誰家兒，聯翩相驰逐。"]', '诗', 'shi', '', NULL, '田家雜興八首 七 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa586f05-a04e-4f05-aed5-4ccb9138286a', '田家雜興八首 八', '田家杂兴八首 八', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["種桑百餘樹，種黍三十畝。","衣食既有餘，時時會親友。","夏來菰米飯，秋至菊花酒。","孺人喜逢迎，稚子解趨走。","日暮閑園裏，團團蔭榆柳。","酩酊乘夜歸，涼風吹戶牖。","清淺望河漢，低昂看北斗。","數甕猶未開，明朝能飲否。"]', '["種桑百餘樹，種黍三十畝。","衣食既有餘，时时會親友。","夏来菰米飯，秋至菊花酒。","孺人喜逢迎，稚子解趨走。","日暮闲园裏，團團蔭榆柳。","酩酊乘夜归，涼风吹戶牖。","清淺望河漢，低昂看北斗。","數甕猶未开，明朝能饮否。"]', '诗', 'shi', '', NULL, '田家雜興八首 八 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87ba9e30-c02a-4744-9b2d-e909dc327f76', '題辨覺精舍', '題辨覺精舍', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["朝隨秋雲陰，乃至青松林。","花閣空中遠，方池巖下深。","竹風亂天語，溪響成龍吟。","試問真君子，遊山非世心。"]', '["朝隨秋云陰，乃至青松林。","花閣空中远，方池巖下深。","竹风亂天語，溪响成龙吟。","試问真君子，游山非世心。"]', '诗', 'shi', '', NULL, '題辨覺精舍 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ace56877-719a-48dc-ae06-118d4efc5847', '題慎言法師故房', '題慎言法師故房', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["精廬不住子，自有無生鄉。","過客知何道，裴回雁子堂。","浮雲歸故嶺，落月還西方。","日夕虛空裏，時時聞異香。"]', '["精廬不住子，自有無生乡。","過客知何道，裴回雁子堂。","浮云归故嶺，落月還西方。","日夕虛空裏，时时闻異香。"]', '诗', 'shi', '', NULL, '題慎言法師故房 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('964a27c9-2542-4bcb-9709-13879feab772', '石甕寺', '石甕寺', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["遙山起真宇，西向盡花林。","下見宮殿小，上看廊廡深。","苑花落池水，天語聞松音。","君子又知我，焚香期化心。"]', '["遙山起真宇，西向尽花林。","下见宮殿小，上看廊廡深。","苑花落池水，天語闻松音。","君子又知我，焚香期化心。"]', '诗', 'shi', '', NULL, '石甕寺 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('253ce3b8-e3a2-4c94-85b1-d9901a7a69f9', '題崔山人別業', '題崔山人別業', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["南陽隱居者，築室丹溪源。","溪冷懼秋[晏]，室寒欣景暾。","山雞鳴菌閣，水霧入衡門。","東嶺或舒嘯，北窗時討論。","封君渭陽竹，逸士漢陰園。","何必崆峒上，獨爲堯所尊。"]', '["南陽隐居者，築室丹溪源。","溪冷懼秋[晏]，室寒欣景暾。","山雞鳴菌閣，水霧入衡门。","东嶺或舒嘯，北窗时討論。","封君渭陽竹，逸士漢陰园。","何必崆峒上，独爲堯所尊。"]', '诗', 'shi', '', NULL, '題崔山人別業 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3026c473-d37c-4051-af18-ef705b588556', '行次田家澳梁作', '行次田家澳梁作', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["田家俯長道，邀我避炎氛。","當暑日方晝，高天無片雲。","桑間禾黍氣，柳下牛羊羣。","野雀棲空屋，晨昏不復聞。","前登澳梁坂，極望溫泉分。","逆旅方三舍，西山猶未曛。"]', '["田家俯长道，邀我避炎氛。","當暑日方晝，高天無片云。","桑间禾黍氣，柳下牛羊羣。","野雀棲空屋，晨昏不复闻。","前登澳梁坂，極望溫泉分。","逆旅方三舍，西山猶未曛。"]', '诗', 'shi', '', NULL, '行次田家澳梁作 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba8dac79-354e-4719-86e3-b38da53c5ec0', '昭聖觀', '昭聖观', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["主家隱溪口，微路入花源。","數日朝青閣，彩雲猶在門。","雙樓夾一殿，玉女侍玄元。","扶橑盡蟠木，步櫩多畫繙。","新松引天籟，小柏繞山樊。","坐弄竹陰遠，行隨溪水喧。","石池辨春色，林獸知人言。","未逐鳳皇去，真宮在此原。"]', '["主家隐溪口，微路入花源。","數日朝青閣，彩云猶在门。","雙楼夾一殿，玉女侍玄元。","扶橑尽蟠木，步櫩多畫繙。","新松引天籟，小柏繞山樊。","坐弄竹陰远，行隨溪水喧。","石池辨春色，林獸知人言。","未逐鳳皇去，真宮在此原。"]', '诗', 'shi', '', NULL, '昭聖觀 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47d5f864-fb65-4a22-9141-1d8db778dd6a', '題辛道士房', '題辛道士房', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["全神不言命，所尚道家流。","迨此遠南楚，遂令思北遊。","先生秀衡嶽，玉立居玄丘。","門帶江山靜，房隨瑤草幽。","逍遙三花發，罔象五雲浮。","自有太清紀，曾垂華髮憂。","大年方橐籥，小智即蜉蝣。","七日赤龍至，莫令余獨留。"]', '["全神不言命，所尚道家流。","迨此远南楚，遂令思北游。","先生秀衡嶽，玉立居玄丘。","门带江山静，房隨瑤草幽。","逍遙三花發，罔象五云浮。","自有太清紀，曾垂华髮憂。","大年方橐籥，小智即蜉蝣。","七日赤龙至，莫令余独留。"]', '诗', 'shi', '', NULL, '題辛道士房 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8aa34b2b-7216-41a4-8453-892834425b91', '登秦嶺作時陷賊歸國', '登秦嶺作时陷賊归国', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["朝出猛獸林，躨跜登高峰。","僮僕履雲霧，隨我行太空。","羲和舒靈暉，倏忽西極通。","迴首望涇渭，隱隱如長虹。","九逵合蒼蕪，五陵遙瞳矇。","鹿遊大明殿，霧濕華清宮。","網羅蠛蠓時，顧齒熊羆鋒。","失途走江漢，不能有其功。","氣逐招遙星，魂隨閶闔風。","惟言宇宙清，復使車書同。","林木被繁霜，合沓連山紅。","鵬鶚勵羽翼，俯視荆棘叢。","誓將食鶬鴞，然後歸崆峒。"]', '["朝出猛獸林，躨跜登高峰。","僮僕履云霧，隨我行太空。","羲和舒靈暉，倏忽西極通。","迴首望涇渭，隐隐如长虹。","九逵合蒼蕪，五陵遙瞳矇。","鹿游大明殿，霧濕华清宮。","網羅蠛蠓时，顧齒熊羆鋒。","失途走江漢，不能有其功。","氣逐招遙星，魂隨閶闔风。","惟言宇宙清，复使车书同。","林木被繁霜，合沓連山紅。","鵬鶚勵羽翼，俯視荆棘叢。","誓將食鶬鴞，然後归崆峒。"]', '诗', 'shi', '', NULL, '登秦嶺作時陷賊歸國 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c0107ff-92eb-4f0b-abda-35be6cc580f4', '晦日任橋池亭', '晦日任橋池亭', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["溫泉作天邑，直北開新洲。","未有菰蒲生，即聞鳧雁遊。","六亭在高岸，數島居中流。","晦日望清波，相與期泛游。","西道苦轉轂，北隄疲行舟。","清泠水木陰，纔可適我憂。"]', '["溫泉作天邑，直北开新洲。","未有菰蒲生，即闻鳧雁游。","六亭在高岸，數島居中流。","晦日望清波，相與期泛游。","西道苦轉轂，北隄疲行舟。","清泠水木陰，纔可適我憂。"]', '诗', 'shi', '', NULL, '晦日任橋池亭 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14c40953-f8d5-49cc-850d-1710256dd7e7', '望幸亭', '望幸亭', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["五年一巡狩，西幸過東畿。","周國易居守，周人多怨思。","君王敷惠政，程作貴從時。","大廈非一木，沈沈臨九逵。","慶雲宿飛棟，嘉樹羅青墀。","疎屏宜朝享，方塘堪水嬉。","雲中仰華蓋，桁下望春旗。","天意知如此，星言歸洛師。"]', '["五年一巡狩，西幸過东畿。","周国易居守，周人多怨思。","君王敷惠政，程作貴從时。","大廈非一木，沈沈臨九逵。","慶云宿飞棟，嘉樹羅青墀。","疎屏宜朝享，方塘堪水嬉。","云中仰华蓋，桁下望春旗。","天意知如此，星言归洛師。"]', '诗', 'shi', '', NULL, '望幸亭 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04b32c17-108e-4d4f-b347-07b2017cb0c8', '哥舒大夫頌德', '哥舒大夫頌德', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["天紀啓真命，君生臣亦生。","乃知赤帝子，復有蒼龍精。","神武建皇極，文昌開將星。","超超渭濱器，落落山西名。","畫閫入受脤，鑿門出扞城。","戎人昧正朔，我有軒轅兵。","隴路起豐鎬，關雲隨斾旌。","河湟訓兵甲，義勇方橫行。","韓魏多銳士，蹶張在幕庭。","大非四決軋，石堡高崢嶸。","攻伐若振槁，孰云非神明。","嘉謀即天意，驟勝由師貞。","枯草被西陸，烈風昏太清。","戢戈旄頭落，牧馬崑崙平。","賓從儼冠蓋，封山紀天聲。","來朝芙蓉闕，鳴玉飄華纓。","直道濟時憲，天邦遂輕刑。","抗書報知己，松柏亦以榮。","嘉命列上第，德輝照天京。","在車持簡墨，粲粲皆詞英。","顧我搶榆者，莫能翔青冥。","遊燕非騏驥，躑躅思長鳴。"]', '["天紀啓真命，君生臣亦生。","乃知赤帝子，复有蒼龙精。","神武建皇極，文昌开將星。","超超渭濱器，落落山西名。","畫閫入受脤，鑿门出扞城。","戎人昧正朔，我有軒轅兵。","隴路起豐鎬，关云隨斾旌。","河湟訓兵甲，義勇方橫行。","韓魏多銳士，蹶張在幕庭。","大非四決軋，石堡高崢嶸。","攻伐若振槁，孰云非神明。","嘉謀即天意，驟勝由師貞。","枯草被西陸，烈风昏太清。","戢戈旄头落，牧马崑崙平。","賓從儼冠蓋，封山紀天声。","来朝芙蓉闕，鳴玉飄华纓。","直道濟时憲，天邦遂轻刑。","抗书報知己，松柏亦以榮。","嘉命列上第，德輝照天京。","在车持簡墨，粲粲皆词英。","顧我搶榆者，莫能翔青冥。","游燕非騏驥，躑躅思长鳴。"]', '诗', 'shi', '', NULL, '哥舒大夫頌德 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18f03b07-b9da-4191-96f7-506e48b4426c', '安宜園林獻高使君', '安宜园林獻高使君', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["直道已三出，幸從江上迴。","新居茅茨逈，起見秋雲開。","十里次舟楫，二橋交往來。","楚言滿鄰里，鴈呌喧池臺。","魚鱉樂仁政，浮沈亦至哉。","小山宜大隱，要自望蓬萊。"]', '["直道已三出，幸從江上迴。","新居茅茨逈，起见秋云开。","十里次舟楫，二橋交往来。","楚言满鄰里，鴈呌喧池台。","鱼鱉乐仁政，浮沈亦至哉。","小山宜大隐，要自望蓬萊。"]', '诗', 'shi', '', NULL, '安宜園林獻高使君 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('399c7e64-bbbc-49b6-8e2c-fbcd948c7702', '', '', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["伊昔好觀國，自鄉西入秦。","往復萬餘里，相逢皆衆人。","大君幸東嶽，世哲扈時巡。","予亦從此去，閑居清洛濱。","稍稍寒木直，彩彩陽華新。","迭宕孔文舉，風流石季倫。","妙年一相得，白首定相親。","重此虛賓館，歡言冬及春。","哲兄盛文史，出入馳高軌。","令德本同人，深心重知己。","絳衣朝聖主，紗帳延才子。","伯淮與季江，清濬各孤峙。","羣芳趨汎愛，萬物通情理。","而我信空虛，提攜過杞梓。","夫君美聲德，直道期終始。","孰謂忽離居，優游鄭東里。","東里近王城，山連路亦平。","何言相去遠，閑言獨淒清。","萬里鴻鴈度，四鄰砧杵鳴。","其如久離別，重以霜風驚。"]', '["伊昔好观国，自乡西入秦。","往复万餘里，相逢皆衆人。","大君幸东嶽，世哲扈时巡。","予亦從此去，闲居清洛濱。","稍稍寒木直，彩彩陽华新。","迭宕孔文舉，风流石季倫。","妙年一相得，白首定相親。","重此虛賓館，歡言冬及春。","哲兄盛文史，出入驰高軌。","令德本同人，深心重知己。","絳衣朝聖主，紗帳延才子。","伯淮與季江，清濬各孤峙。","羣芳趨汎愛，万物通情理。","而我信空虛，提携過杞梓。","夫君美声德，直道期終始。","孰謂忽離居，優游鄭东里。","东里近王城，山連路亦平。","何言相去远，闲言独淒清。","万里鴻鴈度，四鄰砧杵鳴。","其如久離別，重以霜风驚。"]', '诗', 'shi', '', NULL, ' 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('faf8ce54-5add-41a6-b5f8-471bed171906', '河中望鳥灘作貽呂四郎中', '河中望鸟灘作貽呂四郎中', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["河流有深曲，舟子莫能知。","弭棹臨沙嶼，微吟西日馳。","平明春色霽，兩岸好風吹。","去去川途盡，悠悠親友離。","漢宮成羽翼，伊水弄參差。","爲惜淮南子，如何攀桂枝。"]', '["河流有深曲，舟子莫能知。","弭棹臨沙嶼，微吟西日驰。","平明春色霽，兩岸好风吹。","去去川途尽，悠悠親友離。","漢宮成羽翼，伊水弄參差。","爲惜淮南子，如何攀桂枝。"]', '诗', 'shi', '', NULL, '河中望鳥灘作貽呂四郎中 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0976ddc-93c3-4780-97e6-82f14a17455b', '秦中初霽獻給事二首 一', '秦中初霽獻給事二首 一', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["渭水收暮雨，處處多新澤。","宮苑傍山明，雲林帶天碧。","君子聳高駕，英聲邈今昔。","鏘珮出中臺，彯纓入仙掖。","夙心幸清鑒，晚志欣良覿。","鳴盜非足徵，願言同下客。"]', '["渭水收暮雨，处处多新澤。","宮苑傍山明，云林带天碧。","君子聳高駕，英声邈今昔。","鏘珮出中台，彯纓入仙掖。","夙心幸清鑒，晚志欣良覿。","鳴盜非足徵，願言同下客。"]', '诗', 'shi', '', NULL, '秦中初霽獻給事二首 一 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d26181f5-dde5-471b-ac85-d333b2a51461', '秦中初霽獻給事二首 二', '秦中初霽獻給事二首 二', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["南國久爲思，西都嘗作賓。","雲開天地色，日照山河春。","善聽在知己，揚光唯達人。","妙年弄柔翰，弱冠偶良晨。","擢第文昌閣，還家滄海濱。","寸心何所望，東掖有賢臣。"]', '["南国久爲思，西都嘗作賓。","云开天地色，日照山河春。","善听在知己，揚光唯達人。","妙年弄柔翰，弱冠偶良晨。","擢第文昌閣，還家滄海濱。","寸心何所望，东掖有賢臣。"]', '诗', 'shi', '', NULL, '秦中初霽獻給事二首 二 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ac969fb-ba17-4247-a7d8-d169e86d7d2e', '晚次東亭獻鄭州宋使君文', '晚次东亭獻鄭州宋使君文', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["自初賓上國，乃到鄒人鄉。","曾點與曾子，俱升闕里堂。","武皇恢大略，逸翮思寥廓。","三居清憲臺，兩拜文昌閣。","爲道既貞信，處名猶謇諤。","鐵柱勵風威，錦軸含光輝。","夜聞持簡立，朝看伏奏歸。","洞門清珮響，廣路玉珂飛。","驤首入丹掖，摶空趨太微。","絲綸逢聖主，出入飄華組。","愔愔宿帝梧，侃侃居文府。","海內語三獨，朝端謀六戶。","善計在弘羊，清嚴歸仲舉。","侍郎跨方朔，中丞蔑周處。","天眷擇循良，惟賢降寵章。","分符指聊攝，爲政本農桑。","籍籍歌五袴，祁祁頌千箱。","隨車微雨灑，逐扇清風颺。","既以遷列國，復茲鄰帝鄉。","褰帷乃仍舊，坐嘯非更張。","居敬物無擾，履端人自康。","薄遊出京邑，引領東南望。","林晚鳥雀噪，田秋稼穡黃。","成臯天地險，廣武征戰場。","道喪苦兵賦，時來開井疆。","霏霏渠門色，晻晻制巖光。","徒念京索近，猶悲溱洧長。","大明潛照耀，淑慝自昭彰。","昔歲幸西土，今茲歸洛陽。","同焉知鄭伯，當輔我周王。"]', '["自初賓上国，乃到鄒人乡。","曾点與曾子，俱升闕里堂。","武皇恢大略，逸翮思寥廓。","三居清憲台，兩拜文昌閣。","爲道既貞信，处名猶謇諤。","鐵柱勵风威，錦軸含光輝。","夜闻持簡立，朝看伏奏归。","洞门清珮响，廣路玉珂飞。","驤首入丹掖，摶空趨太微。","絲綸逢聖主，出入飄华組。","愔愔宿帝梧，侃侃居文府。","海內語三独，朝端謀六戶。","善計在弘羊，清嚴归仲舉。","侍郎跨方朔，中丞蔑周处。","天眷擇循良，惟賢降寵章。","分符指聊攝，爲政本農桑。","籍籍歌五袴，祁祁頌千箱。","隨车微雨灑，逐扇清风颺。","既以遷列国，复茲鄰帝乡。","褰帷乃仍旧，坐嘯非更張。","居敬物無擾，履端人自康。","薄游出京邑，引領东南望。","林晚鸟雀噪，田秋稼穡黄。","成臯天地險，廣武征戰場。","道喪苦兵賦，时来开井疆。","霏霏渠门色，晻晻制巖光。","徒念京索近，猶悲溱洧长。","大明潛照耀，淑慝自昭彰。","昔歲幸西土，今茲归洛陽。","同焉知鄭伯，當輔我周王。"]', '诗', 'shi', '', NULL, '晚次東亭獻鄭州宋使君文 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e60e06f-4062-4c72-bddb-0d151a79d9d2', '秋次霸亭寄申大', '秋次霸亭寄申大', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["橘柚植寒陵，芙蓉蔕脩坂。","無言不得意，得意何由展。","況我行且徒，而君往猶蹇。","既傷人事近，復言天道遠。","薄暮入空亭，中夜不能飯。","南聽鴻雁盡，西見招搖轉。","千門漢主宮，百里周王苑。","杲杲初景出，油油鮮雲卷。","會朝幸歲正，校獵從新獮。","念君久京國，雙涕如露泫。","無人薦子雲，太息竟誰辨。"]', '["橘柚植寒陵，芙蓉蔕脩坂。","無言不得意，得意何由展。","況我行且徒，而君往猶蹇。","既傷人事近，复言天道远。","薄暮入空亭，中夜不能飯。","南听鴻雁尽，西见招搖轉。","千门漢主宮，百里周王苑。","杲杲初景出，油油鲜云卷。","會朝幸歲正，校獵從新獮。","念君久京国，雙涕如露泫。","無人薦子云，太息竟誰辨。"]', '诗', 'shi', '', NULL, '秋次霸亭寄申大 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb81e391-0ffb-4754-abdc-f7440fea887e', '舟中別武金壇', '舟中別武金壇', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["曰予輕皎潔，坦率賓混元。","忽乃異羣萃，高歌信陵門。","信陵好賓客，清夜開華軒。","月光麗池閣，野氣浮林園。","偶坐爛明星，歸志潛崩奔。","漾舟清潭裏，慰我別離魂。","落日下西山，左右慘無言。","蕭條風雨散，窅靄江湖昏。","秋荷尚幽鬱，暮鳥復翩翻。","紙筆亦何爲，寫我心中冤。"]', '["曰予轻皎潔，坦率賓混元。","忽乃異羣萃，高歌信陵门。","信陵好賓客，清夜开华軒。","月光丽池閣，野氣浮林园。","偶坐爛明星，归志潛崩奔。","漾舟清潭裏，慰我別離魂。","落日下西山，左右慘無言。","蕭條风雨散，窅靄江湖昏。","秋荷尚幽鬱，暮鸟复翩翻。","紙笔亦何爲，寫我心中冤。"]', '诗', 'shi', '', NULL, '舟中別武金壇 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9875f97a-9765-4529-bd9a-1a6b1243ede8', '鞏城東莊道中作', '鞏城东莊道中作', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["北陵散寒鳥，西山照初日。","婉孌晉陽京，踟躕野人室。","南軒草間去，後乘林中出。","靄靄長路暖，遲遲狹路歸。","蜉蝣時蔽月，枳棘復傷衣。","城上東風起，河邊早雁飛。","夏王紀冬令，殷人乃正月。","涯口度新雲，山陰留故雪。","幸逢耆耋話，餘待親隣別。","總轡出叢薄，歇鞍登峻隅。","春源既蕩漭，伏戰亦睢盱。","未獲遵平道，徒言信薄夫。"]', '["北陵散寒鸟，西山照初日。","婉孌晉陽京，踟躕野人室。","南軒草间去，後乘林中出。","靄靄长路暖，遲遲狹路归。","蜉蝣时蔽月，枳棘复傷衣。","城上东风起，河邊早雁飞。","夏王紀冬令，殷人乃正月。","涯口度新云，山陰留故雪。","幸逢耆耋話，餘待親隣別。","總轡出叢薄，歇鞍登峻隅。","春源既蕩漭，伏戰亦睢盱。","未獲遵平道，徒言信薄夫。"]', '诗', 'shi', '', NULL, '鞏城東莊道中作 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5483dafa-09b1-4349-9719-b50f785b5916', '赴馮翊作', '赴馮翊作', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["本自江海人，且無寥廓志。","大明耀天宇，靄靄風雨被。","迢遞別荆吳，飄颻涉沂泗。","廣川俟舟檝，峻坂傷騏驥。","蹭蹬失歸道，崎嶇從下位。","西出太華陰，北走少梁地。","葱蘢墟落色，泱漭關河氣。","恥從俠烈遊，甘爲刀筆吏。","寶劒茱萸匣，豈忘知音貴。","大道且泛然，沈浮未云異。"]', '["本自江海人，且無寥廓志。","大明耀天宇，靄靄风雨被。","迢遞別荆吳，飄颻涉沂泗。","廣川俟舟檝，峻坂傷騏驥。","蹭蹬失归道，崎嶇從下位。","西出太华陰，北走少梁地。","葱蘢墟落色，泱漭关河氣。","恥從俠烈游，甘爲刀笔吏。","寶劒茱萸匣，豈忘知音貴。","大道且泛然，沈浮未云異。"]', '诗', 'shi', '', NULL, '赴馮翊作 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f75eac14-cd7a-49d2-b9ea-f9f3b29466fd', '晚霽中園喜赦作', '晚霽中园喜赦作', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["五月黃梅時，陰氣蔽遠邇。","濃雲連晦朔，菰菜生隣里。","落日燒霞明，農夫知雨止。","幾悲衽席濕，長歎垣牆毀。","曭朗天宇開，家族躍以喜。","渙汗發大號，坤元更資始。","散衣出中園，小徑尚滑履。","池光搖萬象，倏忽滅復起。","嘉樹如我心，欣欣豈云已。"]', '["五月黄梅时，陰氣蔽远邇。","濃云連晦朔，菰菜生隣里。","落日燒霞明，農夫知雨止。","幾悲衽席濕，长歎垣牆毀。","曭朗天宇开，家族躍以喜。","渙汗發大號，坤元更資始。","散衣出中园，小徑尚滑履。","池光搖万象，倏忽滅复起。","嘉樹如我心，欣欣豈云已。"]', '诗', 'shi', '', NULL, '晚霽中園喜赦作 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('505ef721-ace4-41b5-852c-07bbb6f7971a', '觀范陽遞俘', '观范陽遞俘', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["北河旄星隕，鬼方獮林胡。","羣師舞弓矢，電發歸燕墟。","皇皇軒轅君，贊贊臯陶謨。","方思壯軍實，遠近遞生俘。","車馬踐大逵，合沓成深渠。","牧人過橐駞，校正引騊駼。","烈風朝送寒，雲雪靄天隅。","草木同一色，誰能辨榮枯。","四履封元戎，百金酬勇夫。","大邦武功爵，固與炎皇殊。"]', '["北河旄星隕，鬼方獮林胡。","羣師舞弓矢，電發归燕墟。","皇皇軒轅君，贊贊臯陶謨。","方思壯軍實，远近遞生俘。","车马踐大逵，合沓成深渠。","牧人過橐駞，校正引騊駼。","烈风朝送寒，云雪靄天隅。","草木同一色，誰能辨榮枯。","四履封元戎，百金酬勇夫。","大邦武功爵，固與炎皇殊。"]', '诗', 'shi', '', NULL, '觀范陽遞俘 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bab79fe6-65bb-4ff6-a1ea-08cf632d5555', '次天元十載華陰發兵作時有郎官點發', '次天元十載华陰發兵作时有郎官点發', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["鬼方生獫狁，時寇盧龍營。","帝念霍嫖姚，詔發咸林兵。","天星下文閣，簡師臨我城。","三陌觀勇夫，五餌謀長纓。","雷野大車發，震雲靈鼓鳴。","太華色莽蒼，清渭風交橫。","胡馬悲雨雪，詩人歌斾旌。","閼氏爲女奴，單于作邊氓。","神皇麒麟閣，大將不書名。"]', '["鬼方生獫狁，时寇盧龙營。","帝念霍嫖姚，詔發咸林兵。","天星下文閣，簡師臨我城。","三陌观勇夫，五餌謀长纓。","雷野大车發，震云靈鼓鳴。","太华色莽蒼，清渭风交橫。","胡马悲雨雪，诗人歌斾旌。","閼氏爲女奴，單于作邊氓。","神皇麒麟閣，大將不书名。"]', '诗', 'shi', '', NULL, '次天元十載華陰發兵作時有郎官點發 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1b346e9-fed6-4c8a-9cd8-5aba1440c90a', '送丘健至州敕放作時任下邽縣', '送丘健至州敕放作时任下邽縣', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["太史登觀臺，天街耀旄頭。","大君忽霆震，詔爵冠軍侯。","南必梁孫源，西將圉崑丘。","河隴徵擊卒，虎符到我州。","朝集咸林城，師言亂啁啾。","殺氣變木德，凜凜如高秋。","元戎啓神皇，廟堂發嘉謀。","息兵業稼穡，歸馬復休牛。","和風開陰雪，大耀中天流。","歡聲殷河嶽，涵盪非煙浮。","邦牧新下車，德禮彼甿謳。","乾坤日交泰，吾亦遂優游。"]', '["太史登观台，天街耀旄头。","大君忽霆震，詔爵冠軍侯。","南必梁孫源，西將圉崑丘。","河隴徵擊卒，虎符到我州。","朝集咸林城，師言亂啁啾。","殺氣变木德，凜凜如高秋。","元戎啓神皇，廟堂發嘉謀。","息兵業稼穡，归马复休牛。","和风开陰雪，大耀中天流。","歡声殷河嶽，涵盪非煙浮。","邦牧新下车，德禮彼甿謳。","乾坤日交泰，吾亦遂優游。"]', '诗', 'shi', '', NULL, '送丘健至州敕放作時任下邽縣 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0205f595-4a09-4565-b078-f76d010f28d9', '登商丘', '登商丘', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["河水日夜流，客心多殷憂。","維梢歷宋國，結纜登商丘。","漢皇封子弟，周室命諸侯。","搖搖世祀怨，傷古復兼秋。","鳴鴻念極浦，征旅慕前儔。","太息梁王苑，時非牧馬遊。"]', '["河水日夜流，客心多殷憂。","維梢歷宋国，結纜登商丘。","漢皇封子弟，周室命諸侯。","搖搖世祀怨，傷古复兼秋。","鳴鴻念極浦，征旅慕前儔。","太息梁王苑，时非牧马游。"]', '诗', 'shi', '', NULL, '登商丘 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f2b7fba-a42e-465c-a238-8ae1af4a274a', '羣鴉詠', '羣鴉詠', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["新宮驪山陰，龍衮時出豫。","朝陽照羽儀，清吹肅逵路。","羣鴉隨天車，夜滿新豐樹。","所思在腐餘，不復憂霜露。","河低宮閣深，燈影鼓鐘曙。","繽紛集寒枝，矯翼時相顧。","冢宰收琳琅，侍臣盡鴛鷺。","高舉摩太清，永絕矰繳懼。","茲禽亦翱翔，不以微小故。"]', '["新宮驪山陰，龙衮时出豫。","朝陽照羽儀，清吹肅逵路。","羣鴉隨天车，夜满新豐樹。","所思在腐餘，不复憂霜露。","河低宮閣深，灯影鼓鐘曙。","繽紛集寒枝，矯翼时相顧。","冢宰收琳琅，侍臣尽鴛鷺。","高舉摩太清，永絕矰繳懼。","茲禽亦翱翔，不以微小故。"]', '诗', 'shi', '', NULL, '羣鴉詠 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f902d2ee-a480-4520-84cd-ce523ed5619e', '尚書省受誓誡貽太廟裴丞', '尚书省受誓誡貽太廟裴丞', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["皇家有恆憲，齋祭崇明祀。","嚴車伊洛間，受誓文昌裏。","沈沈雲閣見，稍稍城烏起。","曙色照衣冠，虛庭鳴劒履。","裴回念私覿，悵望臨清汜。","點翰欲何言，相思從此始。"]', '["皇家有恆憲，斋祭崇明祀。","嚴车伊洛间，受誓文昌裏。","沈沈云閣见，稍稍城烏起。","曙色照衣冠，虛庭鳴劒履。","裴回念私覿，悵望臨清汜。","点翰欲何言，相思從此始。"]', '诗', 'shi', '', NULL, '尚書省受誓誡貽太廟裴丞 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a977d1b2-a874-43f4-b6db-9c2850647219', '夏日尋藍田唐丞登高宴集', '夏日尋藍田唐丞登高宴集', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["東望春明門，駕言聊出遊。","南行小徑盡，綠竹臨清流。","君出罷六安，居此澹忘憂。","園林與城市，閭里隨人幽。","披顏闢衡闈，置酒登崇丘。","山河臨咫尺，宇宙窮寸眸。","是時春載陽，佳氣滿皇州。","宮殿碧雲裏，鴛鴦初命儔。","良辰方在茲，志士安得休。","成名苟有地，何必東陵侯。"]', '["东望春明门，駕言聊出游。","南行小徑尽，綠竹臨清流。","君出罷六安，居此澹忘憂。","园林與城市，閭里隨人幽。","披顏闢衡闈，置酒登崇丘。","山河臨咫尺，宇宙窮寸眸。","是时春載陽，佳氣满皇州。","宮殿碧云裏，鴛鴦初命儔。","良辰方在茲，志士安得休。","成名苟有地，何必东陵侯。"]', '诗', 'shi', '', NULL, '夏日尋藍田唐丞登高宴集 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9203a594-a988-4f2e-a870-da54a4071852', '田家即事答崔二東臯作四首 一', '田家即事答崔二东臯作四首 一', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["玄鳥雙雙飛，杏林初發花。","喣媮命僮僕，可以樹桑麻。","清旦理犂鋤，日入未還家。"]', '["玄鸟雙雙飞，杏林初發花。","喣媮命僮僕，可以樹桑麻。","清旦理犂鋤，日入未還家。"]', '诗', 'shi', '', NULL, '田家即事答崔二東臯作四首 一 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfecc769-7b16-4174-8bca-8c5ef1d504a4', '田家即事答崔二東臯作四首 二', '田家即事答崔二东臯作四首 二', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["有客山中至，言傳故人訊。","蕩漾敷遠情，飄颻吐清韻。","猗歟春臯上，無乃成秋興。"]', '["有客山中至，言傳故人訊。","蕩漾敷远情，飄颻吐清韻。","猗歟春臯上，無乃成秋兴。"]', '诗', 'shi', '', NULL, '田家即事答崔二東臯作四首 二 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7ac5454-1f7d-4a40-ad7d-5c4ba301aebe', '田家即事答崔二東臯作四首 三', '田家即事答崔二东臯作四首 三', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["念別求須臾，忽至嚶鳴時。","菜田燒故草，初樹養新枝。","所寓非幽深，夢寐相追隨。"]', '["念別求須臾，忽至嚶鳴时。","菜田燒故草，初樹養新枝。","所寓非幽深，梦寐相追隨。"]', '诗', 'shi', '', NULL, '田家即事答崔二東臯作四首 三 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4d20c8b-0fa9-4bf2-b419-a5d7cc7e1fb7', '田家即事答崔二東臯作四首 四', '田家即事答崔二东臯作四首 四', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["依依親隴畝，寂寂無隣里。","不聞雞犬音，日見和風起。","賴君遺掞藻，憂來散能弭。"]', '["依依親隴畝，寂寂無隣里。","不闻雞犬音，日见和风起。","賴君遺掞藻，憂来散能弭。"]', '诗', 'shi', '', NULL, '田家即事答崔二東臯作四首 四 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ad23a83-95f4-4e06-8db2-b36c6844a1e2', '敬酬陳掾親家翁秋夜有贈', '敬酬陳掾親家翁秋夜有贈', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["大姬配胡公，位乃三恪賓。","盛德百代祀，斯言良不泯。","敬仲爲齊卿，當國名益震。","仲舉登宰輔，太丘榮縉紳。","武皇受瑤圖，爵士封其新。","繁祉既驟集，裔孫生賢臣。","特達踰珪璋，節操方松筠。","雲漢一矯翼，天池三振鱗。","曳裾朝赤墀，酌醴侍紫宸。","大君錫車馬，時復過平津。","言則廣台階，道亦資天均。","清秋忽高興，震藻若有神。","曜曜趨宮廷，洸洸邁徐陳。","鎬京既賜第，門巷交朱輪。","方將襲伊臯，永以崇夏殷。","宗黨無遠近，敬恭依仁人。","雪盡宇宙暄，雁歸滄海春。","沈吟白華頌，帝闥降絲綸。","驛騎及蕪城，相逢在郊鄄。","別離曠南北，譴謫罹苦辛。","晝遊還荆吳，迷方客咸秦。","惟賢惠重義，男女期嘉姻。","梧桐生朝陽，鶗鴂鳴蕭晨。","豈不畏時暮，坎壈無與鄰。","中夜涼風來，顧我闕音塵。","瓊瑤不遐棄，寤寐如日新。"]', '["大姬配胡公，位乃三恪賓。","盛德百代祀，斯言良不泯。","敬仲爲齊卿，當国名益震。","仲舉登宰輔，太丘榮縉紳。","武皇受瑤圖，爵士封其新。","繁祉既驟集，裔孫生賢臣。","特達踰珪璋，節操方松筠。","云漢一矯翼，天池三振鱗。","曳裾朝赤墀，酌醴侍紫宸。","大君錫车马，时复過平津。","言則廣台階，道亦資天均。","清秋忽高兴，震藻若有神。","曜曜趨宮廷，洸洸邁徐陳。","鎬京既賜第，门巷交朱輪。","方將襲伊臯，永以崇夏殷。","宗黨無远近，敬恭依仁人。","雪尽宇宙暄，雁归滄海春。","沈吟白华頌，帝闥降絲綸。","驛騎及蕪城，相逢在郊鄄。","別離曠南北，譴謫罹苦辛。","晝游還荆吳，迷方客咸秦。","惟賢惠重義，男女期嘉姻。","梧桐生朝陽，鶗鴂鳴蕭晨。","豈不畏时暮，坎壈無與鄰。","中夜涼风来，顧我闕音塵。","瓊瑤不遐棄，寤寐如日新。"]', '诗', 'shi', '', NULL, '敬酬陳掾親家翁秋夜有贈 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad5e3d68-fb99-48d2-8fd1-dadc54b78589', '蘇十三瞻登玉泉寺峰入寺中見贈作', '蘇十三瞻登玉泉寺峰入寺中见贈作', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["慶門疊華組，盛列鍾英彥。","貞信發天姿，文明叶邦選。","爲情貴深遠，作德齊隱見。","別業在春山，懷歸出芳甸。","逖聽多時友，招邀及浮賤。","朝沿霸水窮，暮矚藍田徧。","百花照阡陌，萬木森鄉縣。","澗淨綠蘿深，巖暄新鳥轉。","依然造華薄，豁爾開靈院。","淹留火禁辰，愉樂弦歌宴。","肅肅列樽俎，鏘鏘引纓弁。","天籟激微風，陽光轢奔箭。","以茲小人腹，不勝君子饌。","是日既低迷，中宵方眄眩。","枕上思獨往，胸中理交戰。","碧雲暗雨來，舊原芳色變。","歡然自此絕，心賞何由見。","鴻濛已笑雲，列缺仍揮電。","忽與去人遠，俄逢歸者便。","想像玉泉宮，依稀明月殿。","峰巒如登陟，水木以遊衍。","息心幸自忘，點翰仍留眷。","恨無荆文璧，以答丹青絢。"]', '["慶门叠华組，盛列鍾英彥。","貞信發天姿，文明叶邦選。","爲情貴深远，作德齊隐见。","別業在春山，懷归出芳甸。","逖听多时友，招邀及浮賤。","朝沿霸水窮，暮矚藍田徧。","百花照阡陌，万木森乡縣。","澗淨綠蘿深，巖暄新鸟轉。","依然造华薄，豁爾开靈院。","淹留火禁辰，愉乐弦歌宴。","肅肅列樽俎，鏘鏘引纓弁。","天籟激微风，陽光轢奔箭。","以茲小人腹，不勝君子饌。","是日既低迷，中宵方眄眩。","枕上思独往，胸中理交戰。","碧云暗雨来，旧原芳色变。","歡然自此絕，心賞何由见。","鴻濛已笑云，列缺仍揮電。","忽與去人远，俄逢归者便。","想像玉泉宮，依稀明月殿。","峰巒如登陟，水木以游衍。","息心幸自忘，点翰仍留眷。","恨無荆文璧，以答丹青絢。"]', '诗', 'shi', '', NULL, '蘇十三瞻登玉泉寺峰入寺中見贈作 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cb78293-4fd2-4b86-9433-de4e0420c275', '酬李處士山中見贈', '酬李处士山中见贈', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["厥初遊太學，相與極周旋。","含采共朝暮，知言同古先。","孟陽題劒閣，子雲獻甘泉。","斯須曠千里，婉娩將十年。","今來豔陽月，好鳥鳴翩翩。","同聲既求友，不肖亦懷賢。","引領遲芳信，果枉瑤華篇。","成頌非其德，高文徒自妍。","聲塵邈超越，比興起孤絕。","始信郢中人，乃能歌白雪。","跂予北堂夜，搖筆酬明哲。","綠竹動清風，層軒靜華月。","想像南山下，恬然謝朝列。","猶恐鶗鴂鳴，坐看芳草歇。","邀以青松色，同之白華潔。","永願登龍門，相將持此節。"]', '["厥初游太学，相與極周旋。","含采共朝暮，知言同古先。","孟陽題劒閣，子云獻甘泉。","斯須曠千里，婉娩將十年。","今来豔陽月，好鸟鳴翩翩。","同声既求友，不肖亦懷賢。","引領遲芳信，果枉瑤华篇。","成頌非其德，高文徒自妍。","声塵邈超越，比兴起孤絕。","始信郢中人，乃能歌白雪。","跂予北堂夜，搖笔酬明哲。","綠竹动清风，層軒静华月。","想像南山下，恬然謝朝列。","猶恐鶗鴂鳴，坐看芳草歇。","邀以青松色，同之白华潔。","永願登龙门，相將持此節。"]', '诗', 'shi', '', NULL, '酬李處士山中見贈 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db3780c5-9cb8-4eee-9eb5-e934cc17cbe6', '同諸公秋日遊昆明池思古', '同諸公秋日游昆明池思古', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["僕人理車騎，西出金光逵。","蒼蒼白帝郊，我將遊靈池。","太陰連晦朔，雨與天根違。","淒風披田原，橫汙益山陂。","農畯盡顛沛，顧望稼穡悲。","皇靈惻羣甿，神政張天維。","坤紀戮屏翳，元綱扶逶迤。","迴塘清滄流，大曜懸金暉。","秋色浮渾沌，清光隨漣漪。","豫章盡莓苔，柳杞成枯枝。","驟聞漢天子，征彼西南夷。","伐棘開洪淵，秉旄訓我師。","震雲靈鼉鼓，照水蛟龍旂。","銳士千萬人，猛氣如熊羆。","刑罰一以正，干戈自有儀。","坐作河漢傾，進退樓船飛。","羽發鴻鴈落，檜動芙蓉披。","峨峨三雲宮，肅肅振旅歸。","惡德忽小醜，器用窮地貲。","上兵貴伐謀，此道不能爲。","吁哉蒸人苦，始曰征伐非。","穆穆軒轅朝，耀德守方陲。","君臣日安閑，遠近無怨思。","石鯨既蹭蹬，女牛亦流離。","獱獺遊渚隅，葭蘆生漘湄。","坎埳四十里，填淤今已微。","江伯方翱翔，天吳亟往來。","桑榆慘無色，佇立暮霏霏。","老幼樵木還，賓從迴鞿羈。","帝夢鮮魚索，明月當報時。"]', '["僕人理车騎，西出金光逵。","蒼蒼白帝郊，我將游靈池。","太陰連晦朔，雨與天根違。","淒风披田原，橫汙益山陂。","農畯尽顛沛，顧望稼穡悲。","皇靈惻羣甿，神政張天維。","坤紀戮屏翳，元綱扶逶迤。","迴塘清滄流，大曜懸金暉。","秋色浮渾沌，清光隨漣漪。","豫章尽莓苔，柳杞成枯枝。","驟闻漢天子，征彼西南夷。","伐棘开洪淵，秉旄訓我師。","震云靈鼉鼓，照水蛟龙旂。","銳士千万人，猛氣如熊羆。","刑罰一以正，干戈自有儀。","坐作河漢傾，進退楼船飞。","羽發鴻鴈落，檜动芙蓉披。","峨峨三云宮，肅肅振旅归。","惡德忽小醜，器用窮地貲。","上兵貴伐謀，此道不能爲。","吁哉蒸人苦，始曰征伐非。","穆穆軒轅朝，耀德守方陲。","君臣日安闲，远近無怨思。","石鯨既蹭蹬，女牛亦流離。","獱獺游渚隅，葭蘆生漘湄。","坎埳四十里，填淤今已微。","江伯方翱翔，天吳亟往来。","桑榆慘無色，佇立暮霏霏。","老幼樵木還，賓從迴鞿羈。","帝梦鲜鱼索，明月當報时。"]', '诗', 'shi', '', NULL, '同諸公秋日遊昆明池思古 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb2e729e-893d-47ab-b48d-c417fd2ccd16', '同諸公登慈恩寺塔', '同諸公登慈恩寺塔', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["金祠起真宇，直上青雲垂。","地靜我亦閑，登之秋清時。","蒼蕪宜春苑，片碧昆明池。","誰道天漢高，逍遙方在茲。","虛形賓太極，攜手行翠微。","雷雨傍杳冥，鬼神中躨跜。","靈變在倏忽，莫能窮天涯。","冠上閶闔開，履下鴻雁飛。","宮室低邐迤，羣山小參差。","俯仰宇宙空，庶隨了義歸。","崱屴非大廈，久居亦以危。"]', '["金祠起真宇，直上青云垂。","地静我亦闲，登之秋清时。","蒼蕪宜春苑，片碧昆明池。","誰道天漢高，逍遙方在茲。","虛形賓太極，携手行翠微。","雷雨傍杳冥，鬼神中躨跜。","靈变在倏忽，莫能窮天涯。","冠上閶闔开，履下鴻雁飞。","宮室低邐迤，羣山小參差。","俯仰宇宙空，庶隨了義归。","崱屴非大廈，久居亦以危。"]', '诗', 'shi', '', NULL, '同諸公登慈恩寺塔 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c533f5cd-a633-4e8a-a9b9-e79a4b7a8a4b', '同諸公秋霽曲江俯見南山', '同諸公秋霽曲江俯见南山', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["天靜終南高，俯暎江水明。","有若蓬萊下，淺深見澄瀛。","羣峰懸中流，石壁如瑤瓊。","魚龍隱蒼翠，鳥獸遊清泠。","菰蒲林下秋，薜荔波中輕。","山戛浴蘭阯，水若居雲屏。","嵐氣浮渚宮，孤光隨曜靈。","陰陰豫章館，宛宛百花亭。","大君及羣臣，[宴]樂方嚶鳴。","吾黨二三子，蕭辰怡性情。","逍遙滄洲時，乃在長安城。"]', '["天静終南高，俯暎江水明。","有若蓬萊下，淺深见澄瀛。","羣峰懸中流，石壁如瑤瓊。","鱼龙隐蒼翠，鸟獸游清泠。","菰蒲林下秋，薜荔波中轻。","山戛浴蘭阯，水若居云屏。","嵐氣浮渚宮，孤光隨曜靈。","陰陰豫章館，宛宛百花亭。","大君及羣臣，[宴]乐方嚶鳴。","吾黨二三子，蕭辰怡性情。","逍遙滄洲时，乃在长安城。"]', '诗', 'shi', '', NULL, '同諸公秋霽曲江俯見南山 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc0ffb23-73ca-4334-8999-cf98a30db468', '同諸公送李雲南伐蠻', '同諸公送李云南伐蠻', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["昆明濱滇池，蠢爾敢逆常。","天星耀鈇鑕，弔彼西南方。","冢宰統元戎，太守齒軍行。","囊括千萬里，矢謨在廟堂。","耀耀金虎符，一息到炎荒。","蒐兵自交趾，茇舍出瀘陽。","羣山高嶄巖，凌越如鳥翔。","封豕驟跧伏，巨象遙披攘。","迴溪深天淵，揭厲踰舟梁。","玄武掃孤蜮，蛟龍除方良。","雷霆隨神兵，硼磕動穹蒼。","斬伐若草木，繫縲同犬羊。","餘醜隱弭河，啁啾亂行藏。","君子惡薄險，王師恥重傷。","廣車設罝梁，太白收光芒。","邊吏靜縣道，新書行紀綱。","劒關掉鞅歸，武弁朝建章。","龍樓加命服，獬豸擁秋霜。","邦人頌靈旗，側聽何洋洋。","京觀在七德，休哉我神皇。"]', '["昆明濱滇池，蠢爾敢逆常。","天星耀鈇鑕，弔彼西南方。","冢宰統元戎，太守齒軍行。","囊括千万里，矢謨在廟堂。","耀耀金虎符，一息到炎荒。","蒐兵自交趾，茇舍出瀘陽。","羣山高嶄巖，凌越如鸟翔。","封豕驟跧伏，巨象遙披攘。","迴溪深天淵，揭厲踰舟梁。","玄武掃孤蜮，蛟龙除方良。","雷霆隨神兵，硼磕动穹蒼。","斬伐若草木，繫縲同犬羊。","餘醜隐弭河，啁啾亂行藏。","君子惡薄險，王師恥重傷。","廣车設罝梁，太白收光芒。","邊吏静縣道，新书行紀綱。","劒关掉鞅归，武弁朝建章。","龙楼加命服，獬豸擁秋霜。","邦人頌靈旗，側听何洋洋。","京观在七德，休哉我神皇。"]', '诗', 'shi', '', NULL, '同諸公送李雲南伐蠻 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a4aa673-4ff1-4b81-aa94-3a125b8cfbac', '奉和韋判官獻侍郎叔除河東採訪使', '奉和韋判官獻侍郎叔除河东採訪使', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["天卿小冢宰，道大名亦大。","醜正在權臣，建旟千里外。","楚山俯江漢，汴水連譙沛。","兩持方伯珪，再轉諸侯蓋。","恬淡輕黜陟，優游邈千載。","乾象變台衡，羣賢盡交泰。","聿徠股肱郡，河嶽即襟帶。","盛德滋冀方，仁風清汾澮。","四封盡高足，相府軺車最。","超超青雲器，婉婉竹林會。","賤士敢知言，成頌文明代。","燕雀依大廈，期之保貞悔。"]', '["天卿小冢宰，道大名亦大。","醜正在權臣，建旟千里外。","楚山俯江漢，汴水連譙沛。","兩持方伯珪，再轉諸侯蓋。","恬淡轻黜陟，優游邈千載。","乾象变台衡，羣賢尽交泰。","聿徠股肱郡，河嶽即襟带。","盛德滋冀方，仁风清汾澮。","四封尽高足，相府軺车最。","超超青云器，婉婉竹林會。","賤士敢知言，成頌文明代。","燕雀依大廈，期之保貞悔。"]', '诗', 'shi', '', NULL, '奉和韋判官獻侍郎叔除河東採訪使 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('448cc553-053e-44d3-b333-834d477a27c7', '同王十三維哭殷遙', '同王十三維哭殷遙', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["生理無不盡，念君在中年。","遊道雖未深，舉世莫能賢。","筮仕苦貧賤，爲客少田園。","膏腴不可求，乃在許西偏。","四鄰盡桑柘，咫尺開牆垣。","內艱未及虞，形影隨化遷。","茅茨俯苫蓋，雙殯兩楹間。","時聞孤女號，逈出陌與阡。","慈烏亂飛鳴，猛獸亦以跧。","故人王夫子，靜念無生篇。","哀樂久已絕，聞之將泫然。","太陽蔽空虛，雨雪浮蒼山。","迢遰親靈櫬，顧予悲絕絃。","處順與安時，及此乃空言。"]', '["生理無不尽，念君在中年。","游道雖未深，舉世莫能賢。","筮仕苦貧賤，爲客少田园。","膏腴不可求，乃在許西偏。","四鄰尽桑柘，咫尺开牆垣。","內艱未及虞，形影隨化遷。","茅茨俯苫蓋，雙殯兩楹间。","时闻孤女號，逈出陌與阡。","慈烏亂飞鳴，猛獸亦以跧。","故人王夫子，静念無生篇。","哀乐久已絕，闻之將泫然。","太陽蔽空虛，雨雪浮蒼山。","迢遰親靈櫬，顧予悲絕絃。","处順與安时，及此乃空言。"]', '诗', 'shi', '', NULL, '同王十三維哭殷遙 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1758512b-5438-4b83-8374-84d477f0c53a', '貽丁主簿仙芝別', '貽丁主簿仙芝別', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["赫赫明天子，翹翹羣秀才。","昭昭皇宇廣，隱隱雲門開。","搖曳君初起，聯翩予復來。","茲年不得意，相命遊靈臺。","驊騮多逸氣，琳瑯有清響。","聯行擊水飛，獨影凌虛上。","關河施芳聽，江海徼新賞。","歛袵歸故山，敷言播天壤。","雲峰雖有異，楚越幸相親。","既別復遊處，道深情更殷。","下愚忝聞見，上德猶邅迍。","偃仰東城曲，棲遲依水濱。","脫巾從會府，結綬歸海裔。","親知送河門，邦族迎江澨。","夫子安恬淡，他人悵迢遞。","飛艎既眇然，洲渚徒虧蔽。","人謀固無準，天德諒難知。","高名處下位，逸翮棲卑枝。","去去水中沚，搖搖天一涯。","蓬壺不可見，來泛躍龍池。"]', '["赫赫明天子，翹翹羣秀才。","昭昭皇宇廣，隐隐云门开。","搖曳君初起，聯翩予复来。","茲年不得意，相命游靈台。","驊騮多逸氣，琳瑯有清响。","聯行擊水飞，独影凌虛上。","关河施芳听，江海徼新賞。","歛袵归故山，敷言播天壤。","云峰雖有異，楚越幸相親。","既別复游处，道深情更殷。","下愚忝闻见，上德猶邅迍。","偃仰东城曲，棲遲依水濱。","脫巾從會府，結綬归海裔。","親知送河门，邦族迎江澨。","夫子安恬淡，他人悵迢遞。","飞艎既眇然，洲渚徒虧蔽。","人謀固無準，天德諒难知。","高名处下位，逸翮棲卑枝。","去去水中沚，搖搖天一涯。","蓬壺不可见，来泛躍龙池。"]', '诗', 'shi', '', NULL, '貽丁主簿仙芝別 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9a2fdb6-61b3-4388-9809-7102bec8c90c', '京口送別王四誼', '京口送別王四誼', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["江上楓林秋，江中秋水流。","清晨惜分袂，秋日尚同舟。","落潮洗魚浦，傾荷枕驛樓。","明年菊花熟，洛東泛觴遊。"]', '["江上楓林秋，江中秋水流。","清晨惜分袂，秋日尚同舟。","落潮洗鱼浦，傾荷枕驛楼。","明年菊花熟，洛东泛觴游。"]', '诗', 'shi', '', NULL, '京口送別王四誼 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eda2b426-0a4e-4dba-a88d-2fce136d5ee7', '同房憲部應旋', '同房憲部應旋', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["衡山法王子，慧見息諸苦。","落髮自南州，燕居在西土。","養正不因晦，得中寧患旅。","曠然長虛閒，即理寄行補。","四句了自性，一音亦非取。","橘柚故園枝，隨人植庭戶。","我地少安住，念天時啓處。","憲卿文昌歸，愉悅來晤語。","車騎踐香草，僕人沐花雨。","長風散繁雲，萬里靜天宇。","起滅信易覺，清真知有所。","逍遙高殿陰，六月無炎暑。","微言發新偈，粲粲如懸圃。","直心視惠光，在此大法鼓。"]', '["衡山法王子，慧见息諸苦。","落髮自南州，燕居在西土。","養正不因晦，得中寧患旅。","曠然长虛閒，即理寄行補。","四句了自性，一音亦非取。","橘柚故园枝，隨人植庭戶。","我地少安住，念天时啓处。","憲卿文昌归，愉悅来晤語。","车騎踐香草，僕人沐花雨。","长风散繁云，万里静天宇。","起滅信易覺，清真知有所。","逍遙高殿陰，六月無炎暑。","微言發新偈，粲粲如懸圃。","直心視惠光，在此大法鼓。"]', '诗', 'shi', '', NULL, '同房憲部應旋 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13c6ec5e-dbdb-43e2-9509-27f5c923e808', '奉別長史庾公太守徐公應召', '奉別长史庾公太守徐公應召', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["烈風起江漢，白浪忽如山。","方伯驟勤王，杞人亦憂天。","酆鎬頃霾晦，雲龍召我賢。","車騎北艱苦，艅艎西泝沿。","水靈靜湍瀨，猛獸趨後先。","龍樓開新陽，萬里出雲間。","宇宙既焜耀，崇德濟巨川。","受命在神宗，振兵猶軒轅。","煌煌踰涿鹿，穆穆更坤元。","明王朝太階，遠邇望嘉言。","遊子淡何思，江湖將永年。"]', '["烈风起江漢，白浪忽如山。","方伯驟勤王，杞人亦憂天。","酆鎬頃霾晦，云龙召我賢。","车騎北艱苦，艅艎西泝沿。","水靈静湍瀨，猛獸趨後先。","龙楼开新陽，万里出云间。","宇宙既焜耀，崇德濟巨川。","受命在神宗，振兵猶軒轅。","煌煌踰涿鹿，穆穆更坤元。","明王朝太階，远邇望嘉言。","游子淡何思，江湖將永年。"]', '诗', 'shi', '', NULL, '奉別長史庾公太守徐公應召 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e036fe3-3b59-4b6e-9d72-257c376e5070', '獄中貽姚張薛李鄭柳諸公', '獄中貽姚張薛李鄭柳諸公', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["直道時莫親，起羞見讒口。","輿人是非怪，西子言有咎。","誣善不足悲，失聽一何醜。","大來敢遐望，小往且虛受。","中夜囹圄深，初秋縲紲久。","疎螢出暗草，朔風鳴衰柳。","河漢低在戶，蟏蛸垂向牖。","雁聲遠天末，涼氣生霽後。","負戶愁讀書，劒光忿衝斗。","哀哀害神理，惻惻傷慈母。","妻子垂涕泣，家僮日奔走。","書詞苦人吏，饋食勞交友。","寒服猶未成，繁霜漸將厚。","吉凶問詹尹，倚伏信北叟。","鬼哭知己冤，鳥言誠所誘。","諸公深惠愛，朝夕相左右。","束濕雖欲操，鉤金庶無負。","傷羅念搖翮，踠足思驤首。","瑾瑜頗匿瑕，邦國方含垢。","眷言出深穽，永日常攜手。"]', '["直道时莫親，起羞见讒口。","輿人是非怪，西子言有咎。","誣善不足悲，失听一何醜。","大来敢遐望，小往且虛受。","中夜囹圄深，初秋縲紲久。","疎螢出暗草，朔风鳴衰柳。","河漢低在戶，蟏蛸垂向牖。","雁声远天末，涼氣生霽後。","負戶愁读书，劒光忿衝斗。","哀哀害神理，惻惻傷慈母。","妻子垂涕泣，家僮日奔走。","书词苦人吏，饋食勞交友。","寒服猶未成，繁霜漸將厚。","吉凶问詹尹，倚伏信北叟。","鬼哭知己冤，鸟言誠所誘。","諸公深惠愛，朝夕相左右。","束濕雖欲操，鉤金庶無負。","傷羅念搖翮，踠足思驤首。","瑾瑜頗匿瑕，邦国方含垢。","眷言出深穽，永日常携手。"]', '诗', 'shi', '', NULL, '獄中貽姚張薛李鄭柳諸公 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b389fbca-08fb-4d3e-bf8b-93361f043010', '貽鼓吹李丞時信安王北伐李公王之所器者也', '貽鼓吹李丞时信安王北伐李公王之所器者也', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["北伐昧天造，王師示有征。","轅門統元律，帝室命宗英。","靈威方首事，仗鉞按邊城。","膏雨被春草，黃雲浮太清。","文儒託後乘，武旅趨前旌。","出車發西洛，營軍臨北平。","曰予深固陋，志氣頗縱橫。","嘗思驃騎幕，願逐嫖姚兵。","惟賢美無度，海內依揚聲。","河間舊相許，車騎日逢迎。","折節下謀士，深心論客卿。","忠言雖未列，庶以知君誠。"]', '["北伐昧天造，王師示有征。","轅门統元律，帝室命宗英。","靈威方首事，仗鉞按邊城。","膏雨被春草，黄云浮太清。","文儒託後乘，武旅趨前旌。","出车發西洛，營軍臨北平。","曰予深固陋，志氣頗縱橫。","嘗思驃騎幕，願逐嫖姚兵。","惟賢美無度，海內依揚声。","河间旧相許，车騎日逢迎。","折節下謀士，深心論客卿。","忠言雖未列，庶以知君誠。"]', '诗', 'shi', '', NULL, '貽鼓吹李丞時信安王北伐李公王之所器者也 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5e9dd73-5403-412f-9218-5e3598052aae', '貽王侍御出臺掾丹陽', '貽王侍御出台掾丹陽', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["高高瑯琊臺，臺下生箘簵。","照車十二乘，光彩不足諭。","既當少微星，復隱高山霧。","金丘華陽下，仙伯養晦處。","茅茨對三峰，梧桐開一路。","神溪繞臯陸，樵牧自成趣。","時登青冥遊，若從天江度。","墟里獻薇蕨，羣公致衣縷。","深沈復清淨，偃仰視太素。","猛獸識賓僕，赬霞知早暮。","峨峨雲龍開，忽有方伯遇。","達人無不可，壯志且馳騖。","融泄長雞鳴，繽紛大鵬翥。","赤墀高崱屴，一見如三顧。","禮服正邦祀，刑冠肅王度。","三辰明昭代，光啓玄元祚。","章臺收杞梓，太液滿鵷鷺。","豐澤耀純仁，八方晏黔庶。","沈沈閶闔起，殷殷蓬萊曙。","旌戟儼成行，雞人傳發煦。","翔翼一如鶚，百辟莫不懼。","清廟奉烝嘗，靈山扈鑾輅。","天街時蹴鞠，直指讌梐枑。","四月純陽初，雷雨始奮豫。","逆星孛皇極，鈇鑕靜天步。","酆鎬舒曜靈，干戈藏武庫。","析㯕增廣運，直道有好惡。","廻跡清憲臺，傳騎東南去。","列城異疇昔，近餞寡徒御。","纏綿西關道，婉孌新豐樹。","伊洛不敢息，淮河任沿泝。","鄉亭茱萸津，先後非疏附。","炎時方怵惕，有若踐霜露。","惆悵長岑長，寂寞梁王傅。","紛吾家延州，結友在童孺。","岑陽沐天德，邦邑持民務。","躑躅望朝陰，如何復淪誤。","牙曠三千里，擊轅非所慕。","秋濤聯滄溟，舟檝湊北固。","江汜日綿眇，朝夕空寐寤。","中洞松栝新，東臯阡陌故。","餘輝方焜耀，可以歡邑聚。","南華在濠上，誰辯魏王瓠。","登陟芙蓉樓，爲我時一賦。"]', '["高高瑯琊台，台下生箘簵。","照车十二乘，光彩不足諭。","既當少微星，复隐高山霧。","金丘华陽下，仙伯養晦处。","茅茨对三峰，梧桐开一路。","神溪繞臯陸，樵牧自成趣。","时登青冥游，若從天江度。","墟里獻薇蕨，羣公致衣縷。","深沈复清淨，偃仰視太素。","猛獸識賓僕，赬霞知早暮。","峨峨云龙开，忽有方伯遇。","達人無不可，壯志且驰騖。","融泄长雞鳴，繽紛大鵬翥。","赤墀高崱屴，一见如三顧。","禮服正邦祀，刑冠肅王度。","三辰明昭代，光啓玄元祚。","章台收杞梓，太液满鵷鷺。","豐澤耀純仁，八方晏黔庶。","沈沈閶闔起，殷殷蓬萊曙。","旌戟儼成行，雞人傳發煦。","翔翼一如鶚，百辟莫不懼。","清廟奉烝嘗，靈山扈鑾輅。","天街时蹴鞠，直指讌梐枑。","四月純陽初，雷雨始奮豫。","逆星孛皇極，鈇鑕静天步。","酆鎬舒曜靈，干戈藏武庫。","析㯕增廣運，直道有好惡。","廻跡清憲台，傳騎东南去。","列城異疇昔，近餞寡徒御。","纏綿西关道，婉孌新豐樹。","伊洛不敢息，淮河任沿泝。","乡亭茱萸津，先後非疏附。","炎时方怵惕，有若踐霜露。","惆悵长岑长，寂寞梁王傅。","紛吾家延州，結友在童孺。","岑陽沐天德，邦邑持民務。","躑躅望朝陰，如何复淪誤。","牙曠三千里，擊轅非所慕。","秋濤聯滄溟，舟檝湊北固。","江汜日綿眇，朝夕空寐寤。","中洞松栝新，东臯阡陌故。","餘輝方焜耀，可以歡邑聚。","南华在濠上，誰辯魏王瓠。","登陟芙蓉楼，爲我时一賦。"]', '诗', 'shi', '', NULL, '貽王侍御出臺掾丹陽 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8756226-bbac-484b-bfd5-a4cb3950faee', '貽劉高士別', '貽劉高士別', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["夙駕出東城，城傍早霞散。","初日照龍闕，峨峨在天半。","壯哉麗百常，美矣崇兩觀。","俯視趨朝客，簪珮何璀璨。","而我送將歸，裴回霸陵岸。","北雲去吳越，南雁離江漢。","伊昔蹈丘園，翩翩理文翰。","高談閔仲叔，逸氣劉公幹。","每言竹柏貞，嘗輕朝市玩。","山晝猿狖靜，溪曛魚鳥亂。","寧止臥崆峒，直云期汗漫。","聖君既理歷，族士咸炳煥。","矯首來天池，振羽泛漪瀾。","元淑命不達，伯鸞吟可歎。","東去姑蘇臺，乃過陟陽館。","舍轡函關道，浮舟滄海畔。","耳目曠暄涼，懷抱盈悲惋。","沈沈青歲晚，靄靄秋雲換。","自言永遁棲，無復從羈絆。","揮手謝知己，知己莫能讚。"]', '["夙駕出东城，城傍早霞散。","初日照龙闕，峨峨在天半。","壯哉丽百常，美矣崇兩观。","俯視趨朝客，簪珮何璀璨。","而我送將归，裴回霸陵岸。","北云去吳越，南雁離江漢。","伊昔蹈丘园，翩翩理文翰。","高談閔仲叔，逸氣劉公幹。","每言竹柏貞，嘗轻朝市玩。","山晝猿狖静，溪曛鱼鸟亂。","寧止臥崆峒，直云期汗漫。","聖君既理歷，族士咸炳煥。","矯首来天池，振羽泛漪瀾。","元淑命不達，伯鸾吟可歎。","东去姑蘇台，乃過陟陽館。","舍轡函关道，浮舟滄海畔。","耳目曠暄涼，懷抱盈悲惋。","沈沈青歲晚，靄靄秋云換。","自言永遁棲，無复從羈絆。","揮手謝知己，知己莫能讚。"]', '诗', 'shi', '', NULL, '貽劉高士別 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a47d27f-bcc0-4ce1-8b16-a39b5d1c492f', '山中貽崔六琪華', '山中貽崔六琪华', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["恍惚登高嶺，裴回看落日。","遙想仲長園，如親幼安室。","春渚菖蒲登，山中撥穀鳴。","相思不道遠，太息未知情。","意君來此地，時復疎林薄。","中夜掃閑門，迎晨閉菌閣。","屣履清池上，家童奉信歸。","憂隨落花散，目送歸雲飛。","故交在天末，心知復千里。","無人暫往來，獨作中林士。"]', '["恍惚登高嶺，裴回看落日。","遙想仲长园，如親幼安室。","春渚菖蒲登，山中撥穀鳴。","相思不道远，太息未知情。","意君来此地，时复疎林薄。","中夜掃闲门，迎晨閉菌閣。","屣履清池上，家童奉信归。","憂隨落花散，目送归云飞。","故交在天末，心知复千里。","無人暫往来，独作中林士。"]', '诗', 'shi', '', NULL, '山中貽崔六琪華 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('570dc597-4c1f-48e6-80f5-9982e6cf0845', '貽余處士', '貽余处士', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["故園至新浦，遙復未百里。","北望是他邦，紛吾即遊士。","潮來津門啓，罷楫信流水。","客意乃成歡，舟人亦相喜。","遲遲菱荇上，泛泛孤蒲裏。","漸聞商旅喧，猶見鳧鷖起。","市亭忽雲構，方物如山峙。","吳王昔喪元，隋帝又滅祀。","停艫一以眺，太息興亡理。","秋苑故池田，宮門新柳杞。","我行苦炎月，乃及清昊始。","此地日逢迎，終思隱君子。","莫言異舒卷，形音在心耳。"]', '["故园至新浦，遙复未百里。","北望是他邦，紛吾即游士。","潮来津门啓，罷楫信流水。","客意乃成歡，舟人亦相喜。","遲遲菱荇上，泛泛孤蒲裏。","漸闻商旅喧，猶见鳧鷖起。","市亭忽云構，方物如山峙。","吳王昔喪元，隋帝又滅祀。","停艫一以眺，太息兴亡理。","秋苑故池田，宮门新柳杞。","我行苦炎月，乃及清昊始。","此地日逢迎，終思隐君子。","莫言異舒卷，形音在心耳。"]', '诗', 'shi', '', NULL, '貽余處士 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4c90909-17f9-4af5-b6b7-e55cb4c1d322', '劉先生閑居', '劉先生闲居', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["高第後歸道，乃居玉華宮。","逍遙人間世，不異浮丘公。","甘寢何秉羽，出門忽從戎。","方將遊崑崙，又欲小崆峒。","進退既在我，歸來長安中。","焚香東海君，侍坐西山童。","善行無轍迹，吾亦安能窮。","但見神色閑，中心如虛空。","期之比天老，真德輔帝鴻。"]', '["高第後归道，乃居玉华宮。","逍遙人间世，不異浮丘公。","甘寢何秉羽，出门忽從戎。","方將游崑崙，又欲小崆峒。","進退既在我，归来长安中。","焚香东海君，侍坐西山童。","善行無轍迹，吾亦安能窮。","但见神色闲，中心如虛空。","期之比天老，真德輔帝鴻。"]', '诗', 'shi', '', NULL, '劉先生閑居 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc6395dc-1145-45aa-817d-acbe64197d27', '京口題崇上人山亭', '京口題崇上人山亭', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["清旦歷香巖，巖徑紆復直。","花林開宿霧，遊目清霄極。","分明窗戶中，遠近山川色。","金沙童子戲，香飯諸天食。","呌呌海鴻聲，軒軒江燕翼。","寄言清靜者，閭閻徒自踣。"]', '["清旦歷香巖，巖徑紆复直。","花林开宿霧，游目清霄極。","分明窗戶中，远近山川色。","金沙童子戲，香飯諸天食。","呌呌海鴻声，軒軒江燕翼。","寄言清静者，閭閻徒自踣。"]', '诗', 'shi', '', NULL, '京口題崇上人山亭 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fcf85d1-d1ee-48c6-a46d-c3effe3a7936', '朝邑蔡主簿期不會二首 一', '朝邑蔡主簿期不會二首 一', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["下位日趨走，久之賓會疎。","空遲偶詞賦，所媿比園廬。","朝念池上酌，暮逢林下書。","方將固封守，暫欲混畋漁。","衰柳隱長路，秋雲滿太虛。","遙遙望左右，日入未迴車。"]', '["下位日趨走，久之賓會疎。","空遲偶词賦，所媿比园廬。","朝念池上酌，暮逢林下书。","方將固封守，暫欲混畋漁。","衰柳隐长路，秋云满太虛。","遙遙望左右，日入未迴车。"]', '诗', 'shi', '', NULL, '朝邑蔡主簿期不會二首 一 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d55e2c8-f7af-4680-83e1-267084d91bb4', '朝邑蔡主簿期不會二首 二', '朝邑蔡主簿期不會二首 二', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["日入清風至，知君在西偏。","車輿既成列，賓僕復能賢。","迢遞下墟坂，逍遙看井田。","蒼山起暮雨，極浦浮長煙。","服義大如志，交歡數盡年。","寧言十餘里，不見空來還。"]', '["日入清风至，知君在西偏。","车輿既成列，賓僕复能賢。","迢遞下墟坂，逍遙看井田。","蒼山起暮雨，極浦浮长煙。","服義大如志，交歡數尽年。","寧言十餘里，不见空来還。"]', '诗', 'shi', '', NULL, '朝邑蔡主簿期不會二首 二 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae6f9bbc-7df9-4ea6-9167-7f55b9051594', '鞏城南河作寄徐三景暉', '鞏城南河作寄徐三景暉', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["初年雨候遲，鞏洛河流小。","搖搖芳草岸，屢見春山曉。","清露洗雲林，輕波戲魚鳥。","唯言故人遠，不念鄉川眇。","舟檝去瀠廻，湍漵行奔峭。","寄書千里路，莫道南鴻少。"]', '["初年雨候遲，鞏洛河流小。","搖搖芳草岸，屢见春山晓。","清露洗云林，轻波戲鱼鸟。","唯言故人远，不念乡川眇。","舟檝去瀠廻，湍漵行奔峭。","寄书千里路，莫道南鴻少。"]', '诗', 'shi', '', NULL, '鞏城南河作寄徐三景暉 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0078d0d-a976-4a7d-8fa8-d6ad7b8c76d8', '貽閻處士防卜居終南', '貽閻处士防卜居終南', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["春風搖雜樹，言別還江汜。","堅冰生綠潭，又客三千里。","兆夢唯顏色，懸情乃文史。","滌耳貴清言，披歡遲玉趾。","秦城疑舊廬，佇立問焉如。","稚子跪而說，還山將隱居。","竹林既深遠，松宇復清虛。","跡逈事多逸，心安趣有餘。","石門動高韻，草堂新著書。","騫飛久超絕，蹇足空躊躇。","猶有昔時意，望君當照車。","驅車當六國，何以須潛默。","聖主常徵賢，羣公每舉德。","此時方獨往，身志將何欲。","願謝山中人，廻車首歸躅。"]', '["春风搖杂樹，言別還江汜。","堅冰生綠潭，又客三千里。","兆梦唯顏色，懸情乃文史。","滌耳貴清言，披歡遲玉趾。","秦城疑旧廬，佇立问焉如。","稚子跪而说，還山將隐居。","竹林既深远，松宇复清虛。","跡逈事多逸，心安趣有餘。","石门动高韻，草堂新著书。","騫飞久超絕，蹇足空躊躇。","猶有昔时意，望君當照车。","驱车當六国，何以須潛默。","聖主常徵賢，羣公每舉德。","此时方独往，身志將何欲。","願謝山中人，廻车首归躅。"]', '诗', 'shi', '', NULL, '貽閻處士防卜居終南 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8f1f22c-6767-4efe-9c6a-1fe77b0dfbce', '新豐作貽殷四校書', '新豐作貽殷四校书', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["漢皇思舊邑，秦地作新豐。","南出華陽路，西分長樂宮。","安知天地久，不與昔年同。","雞犬暮聲合，城池秋霽空。","紛吾從此去，望極咸陽中。","不見芸香閣，徒思文雅雄。"]', '["漢皇思旧邑，秦地作新豐。","南出华陽路，西分长乐宮。","安知天地久，不與昔年同。","雞犬暮声合，城池秋霽空。","紛吾從此去，望極咸陽中。","不见芸香閣，徒思文雅雄。"]', '诗', 'shi', '', NULL, '新豐作貽殷四校書 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2fbe8a4-8e00-4fe7-80cd-bb832ceed2f6', '華陽作貽祖三詠', '华陽作貽祖三詠', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["朝行敷水上，暮出華山東。","高館宿初靜，長亭秋轉空。","日余久淪汨，重此聞霜風。","淅瀝入溪樹，颼飀驚夕鴻。","[悽]然望伊洛，如見息陽宮。","舊識無高位，新知盡固窮。","夫君獨輕舉，遠近善文雄。","豈念千里駕，崎嶇秦塞中。"]', '["朝行敷水上，暮出华山东。","高館宿初静，长亭秋轉空。","日余久淪汨，重此闻霜风。","淅瀝入溪樹，颼飀驚夕鴻。","[悽]然望伊洛，如见息陽宮。","旧識無高位，新知尽固窮。","夫君独轻舉，远近善文雄。","豈念千里駕，崎嶇秦塞中。"]', '诗', 'shi', '', NULL, '華陽作貽祖三詠 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66e1ba95-9dbd-47a3-97f7-d558ab6975ff', '貽袁三拾遺謫作', '貽袁三拾遺謫作', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["傾蓋洛之濱，依然心事親。","龍門何以峻，曾是好詞人。","珥筆朝文陛，含章諷紫宸。","帝城多壯觀，被服長如春。","天子儉爲德，而能清約身。","公卿盡虛位，天下自趣塵。","如君物望美，令德聲何已。","高帝黜儒生，文皇謫才子。","朝廷非不盛，譴謫良難恃。","路出大江陰，川行碧峰裏。","斯言徒自玷，白玉豈爲滓。","希聲盡衆人，深識唯知己。","知己怨生離，悠悠天一涯。","寸心因夢斷，孤憤爲年移。","花滿芙蓉闕，春深朝夕池。","空令千萬里，長望白雲垂。"]', '["傾蓋洛之濱，依然心事親。","龙门何以峻，曾是好词人。","珥笔朝文陛，含章諷紫宸。","帝城多壯观，被服长如春。","天子儉爲德，而能清約身。","公卿尽虛位，天下自趣塵。","如君物望美，令德声何已。","高帝黜儒生，文皇謫才子。","朝廷非不盛，譴謫良难恃。","路出大江陰，川行碧峰裏。","斯言徒自玷，白玉豈爲滓。","希声尽衆人，深識唯知己。","知己怨生離，悠悠天一涯。","寸心因梦斷，孤憤爲年移。","花满芙蓉闕，春深朝夕池。","空令千万里，长望白云垂。"]', '诗', 'shi', '', NULL, '貽袁三拾遺謫作 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a666243-80aa-467a-9b0e-db9fba806227', '洛中貽朝校書衡朝即日本人也', '洛中貽朝校书衡朝即日本人也', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["萬國朝天中，東隅道最長。","吾生美無度，高駕仕春坊。","出入蓬山裏，逍遙伊水傍。","伯鸞遊太學，中夜一相望。","落日懸高殿，秋風入洞房。","屢言相去遠，不覺生朝光。"]', '["万国朝天中，东隅道最长。","吾生美無度，高駕仕春坊。","出入蓬山裏，逍遙伊水傍。","伯鸾游太学，中夜一相望。","落日懸高殿，秋风入洞房。","屢言相去远，不覺生朝光。"]', '诗', 'shi', '', NULL, '洛中貽朝校書衡朝即日本人也 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49c12afe-6a96-4beb-b6a4-7e12b9837918', '貽崔太祝', '貽崔太祝', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["天都分禮閣，肅肅臨清渠。","春山照前屏，高槐蔭內除。","惟賢尚廩祿，弟去兄來居。","文雅更驤首，風流信有餘。","中年幸從事，乃遇兩吹噓。","何以知君子，交情復淡如。"]', '["天都分禮閣，肅肅臨清渠。","春山照前屏，高槐蔭內除。","惟賢尚廩祿，弟去兄来居。","文雅更驤首，风流信有餘。","中年幸從事，乃遇兩吹噓。","何以知君子，交情复淡如。"]', '诗', 'shi', '', NULL, '貽崔太祝 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9803a22-5c21-4783-b91d-a7fc9beb454d', '貽王處士子文', '貽王处士子文', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["春草生洞渚，春風入上林。","春臯有黃鶴，撫翮未揚音。","王屋嘗嘉遁，伊川復陸沈。","張弦鵾雞弄，閉室蓬蒿深。","避地歌三樂，遊山賦九吟。","大君思左右，無乃化黃金。"]', '["春草生洞渚，春风入上林。","春臯有黄鹤，撫翮未揚音。","王屋嘗嘉遁，伊川复陸沈。","張弦鵾雞弄，閉室蓬蒿深。","避地歌三乐，游山賦九吟。","大君思左右，無乃化黄金。"]', '诗', 'shi', '', NULL, '貽王處士子文 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a08f09f5-e914-471c-bb97-88acc1af1cab', '獻華陰羅丞別', '獻华陰羅丞別', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["華山薄遊者，玄髮當青春。","道德同仙吏，尊卑即丈人。","縣城俯京路，獲見官舍裏。","淹留瓊樹枝，謔浪春泉水。","昔余在天目，總角奉遊從。","寒暑遞來往，今復蓮花峰。","別情無遠近，道別方愁予。","孰想古人言，乃知悲風雨。"]', '["华山薄游者，玄髮當青春。","道德同仙吏，尊卑即丈人。","縣城俯京路，獲见官舍裏。","淹留瓊樹枝，謔浪春泉水。","昔余在天目，總角奉游從。","寒暑遞来往，今复蓮花峰。","別情無远近，道別方愁予。","孰想古人言，乃知悲风雨。"]', '诗', 'shi', '', NULL, '獻華陰羅丞別 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c87cce2c-0e09-4549-af67-5880b488136f', '閑居', '闲居', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["薄遊何所媿，所媿在閑居。","親故不來往，中園時讀書。","步欄滴餘雪，春塘抽新蒲。","梧桐漸覆井，時鳥自相呼。","悠然念故鄉，乃在天一隅。","安得如浮雲，來往方須臾。"]', '["薄游何所媿，所媿在闲居。","親故不来往，中园时读书。","步欄滴餘雪，春塘抽新蒲。","梧桐漸覆井，时鸟自相呼。","悠然念故乡，乃在天一隅。","安得如浮云，来往方須臾。"]', '诗', 'shi', '', NULL, '閑居 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cda1be8-8a33-407e-8c91-e64406ccdd86', '送恂上人還吳', '送恂上人還吳', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["洛城本天邑，洛水即天池。","君王既行幸，法子復來儀。","虛室香花滿，清川楊柳棰。","乘閑道歸去，遠意誰能知。"]', '["洛城本天邑，洛水即天池。","君王既行幸，法子复来儀。","虛室香花满，清川楊柳棰。","乘闲道归去，远意誰能知。"]', '诗', 'shi', '', NULL, '送恂上人還吳 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00ef33e8-8439-4487-951a-39de4e32820c', '送周十一', '送周十一', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["秋風隕羣木，衆草下嚴霜。","復問子何如？自言之帝鄉。","豈無親所愛，將欲濟時康。","握手別征駕，返悲岐路長。"]', '["秋风隕羣木，衆草下嚴霜。","复问子何如？自言之帝乡。","豈無親所愛，將欲濟时康。","握手別征駕，返悲岐路长。"]', '诗', 'shi', '', NULL, '送周十一 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2cbc7026-922c-4124-b979-5e8885fadf40', '新豐主人', '新豐主人', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["新豐主人新酒熟，舊客還歸舊堂宿。","滿酌香含北砌花，盈尊色泛南軒竹。","雲散天高秋月明，東家少女解秦箏。","醉來忘却巴陵道，夢中疑是洛陽城。"]', '["新豐主人新酒熟，旧客還归旧堂宿。","满酌香含北砌花，盈尊色泛南軒竹。","云散天高秋月明，东家少女解秦箏。","醉来忘却巴陵道，梦中疑是洛陽城。"]', '诗', 'shi', '', NULL, '新豐主人 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('168d13a5-327f-48f3-8ddd-7a5a49b527e3', '登戲馬臺作', '登戲马台作', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["君不見宋公仗鉞誅燕後，英雄踴躍爭趨走。","小會衣冠呂梁壑，大徵甲卒碻磝口。","天門神武樹元勳，九日茱萸饗六軍。","泛泛樓船遊極浦，搖搖歌吹動浮雲。","居人滿目市朝變，覇業猶存齊楚甸。","泗水南流桐柏川，沂山北走瑯琊縣。","滄海沈沈晨霧開，彭城烈烈秋風來。","少年自古未得意，日暮蕭條登古臺。"]', '["君不见宋公仗鉞誅燕後，英雄踴躍爭趨走。","小會衣冠呂梁壑，大徵甲卒碻磝口。","天门神武樹元勳，九日茱萸饗六軍。","泛泛楼船游極浦，搖搖歌吹动浮云。","居人满目市朝变，覇業猶存齊楚甸。","泗水南流桐柏川，沂山北走瑯琊縣。","滄海沈沈晨霧开，彭城烈烈秋风来。","少年自古未得意，日暮蕭條登古台。"]', '诗', 'shi', '', NULL, '登戲馬臺作 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a90d93a8-6356-466e-9f1a-0322e86b696c', '貽從軍行', '貽從軍行', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["取勝小非用，來朝明光殿，東平不足先。","夢出鳳林間，夢還滄海闕。","萬里盡陰色，豈爲我離別。","馬上吹笛起寒風，道傍舞劒飛春雪。","男兒懸弧非一日，君去成高節。"]', '["取勝小非用，来朝明光殿，东平不足先。","梦出鳳林间，梦還滄海闕。","万里尽陰色，豈爲我離別。","马上吹笛起寒风，道傍舞劒飞春雪。","男兒懸弧非一日，君去成高節。"]', '诗', 'shi', '', NULL, '貽從軍行 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67f77015-69d7-456c-8fe4-a377ef023676', '酬李壺關奉使行縣憶諸公', '酬李壺关奉使行縣憶諸公', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["青楓江上滄浪吟，白月宮中鸚鵡林。","非有淨清心，同道同房若斷金。","離居忽有雲山意，清韻遙轉舟檝事。","去時能憶竹園遊，來時莫忘桃園記。"]', '["青楓江上滄浪吟，白月宮中鸚鵡林。","非有淨清心，同道同房若斷金。","離居忽有云山意，清韻遙轉舟檝事。","去时能憶竹园游，来时莫忘桃园記。"]', '诗', 'shi', '', NULL, '酬李壺關奉使行縣憶諸公 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('813334ea-1a01-4541-b616-aabc22964bd8', '薔薇', '薔薇', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["裊裊長數尋，青青不作林。","一莖獨秀當庭心，數枝分作滿庭陰。","春日遲遲欲將半，庭影離離正堪玩。","枝上鶯嬌不畏人，葉底蛾飛自相亂。","秦家女兒愛芳菲，畫眉相伴采葳蕤。","高處紅鬚欲就手，低邊綠刺已牽衣。","蒲萄架上朝光滿，楊柳園中暝鳥飛。","連袂踏歌從此去，風吹香氣逐人歸。"]', '["裊裊长數尋，青青不作林。","一莖独秀當庭心，數枝分作满庭陰。","春日遲遲欲將半，庭影離離正堪玩。","枝上鶯嬌不畏人，葉底蛾飞自相亂。","秦家女兒愛芳菲，畫眉相伴采葳蕤。","高处紅鬚欲就手，低邊綠刺已牽衣。","蒲萄架上朝光满，楊柳园中暝鸟飞。","連袂踏歌從此去，风吹香氣逐人归。"]', '诗', 'shi', '', NULL, '薔薇 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad5a956d-14eb-45d5-a62d-c54222a33233', '同張侍御宴北樓', '同張侍御宴北楼', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["今之太守古諸侯，出入雙旌垂七旒。","朝覽干戈時聽訟，暮延賓客復登樓。","西山漠漠崦嵫色，北渚沈沈江漢流。","良宵清淨方高會，繡服光輝聯皂蓋。","魚龍恍惚堦墀下，雲霧杳冥窗戶外。","水靈慷慨行泣珠，游女飄颻思解佩。","蒼蒼低月半遙城，落落疎星滿太清。","不分開襟悲楚奏，願言吹笛退胡兵。","軒后青丘埋䝟貐，周王白羽掃欃槍。","期君武節朝龍闕，余亦翱翔歸玉京。"]', '["今之太守古諸侯，出入雙旌垂七旒。","朝覽干戈时听訟，暮延賓客复登楼。","西山漠漠崦嵫色，北渚沈沈江漢流。","良宵清淨方高會，繡服光輝聯皂蓋。","鱼龙恍惚堦墀下，云霧杳冥窗戶外。","水靈慷慨行泣珠，游女飄颻思解佩。","蒼蒼低月半遙城，落落疎星满太清。","不分开襟悲楚奏，願言吹笛退胡兵。","軒后青丘埋䝟貐，周王白羽掃欃槍。","期君武節朝龙闕，余亦翱翔归玉京。"]', '诗', 'shi', '', NULL, '同張侍御宴北樓 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('147d5d99-0931-480b-bd62-60abc8ca4f11', '臨江亭五詠 一', '臨江亭五詠 一', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["晉家南作帝，京鎮北爲關。","江水中分地，城樓下帶山。","金陵事已往，青蓋理無還。","落日空亭上，愁看龍尾灣。"]', '["晉家南作帝，京鎮北爲关。","江水中分地，城楼下带山。","金陵事已往，青蓋理無還。","落日空亭上，愁看龙尾灣。"]', '诗', 'shi', '', NULL, '臨江亭五詠 一 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a26fa3bd-04b6-405d-ae8e-994758e3eac3', '臨江亭五詠 二', '臨江亭五詠 二', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["山橫小苑前，路盡大江邊。","此地興王業，無如宋主賢。","潮生建業水，風散廣陵煙。","直望[清]波裏，秪言別有天。"]', '["山橫小苑前，路尽大江邊。","此地兴王業，無如宋主賢。","潮生建業水，风散廣陵煙。","直望[清]波裏，秪言別有天。"]', '诗', 'shi', '', NULL, '臨江亭五詠 二 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c33b6028-10fc-404f-a91f-6be41609c3af', '臨江亭五詠 三', '臨江亭五詠 三', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["城頭落暮暉，城外擣秋衣。","江水青雲挹，蘆花白雪飛。","南州王氣疾，東國海風微。"]', '["城头落暮暉，城外擣秋衣。","江水青云挹，蘆花白雪飞。","南州王氣疾，东国海风微。"]', '诗', 'shi', '', NULL, '臨江亭五詠 三 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d43c41bb-229f-43e9-8ee6-b8102f5f42ec', '臨江亭五詠 四', '臨江亭五詠 四', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["古木嘯寒禽，層城帶夕陰。","梁園多綠柳，楚岸盡楓林。","山際空爲險，江流長自深。","平生何以恨，天地本無心。"]', '["古木嘯寒禽，層城带夕陰。","梁园多綠柳，楚岸尽楓林。","山際空爲險，江流长自深。","平生何以恨，天地本無心。"]', '诗', 'shi', '', NULL, '臨江亭五詠 四 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f6196e5-daaf-477c-883a-dc35808b9ab2', '臨江亭五詠 五', '臨江亭五詠 五', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["京山千里過，孤憤望中來。","江勢將天合，城門向水開。","落霞明楚岸，夕露濕吳臺。"]', '["京山千里過，孤憤望中来。","江勢將天合，城门向水开。","落霞明楚岸，夕露濕吳台。"]', '诗', 'shi', '', NULL, '臨江亭五詠 五 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('716f7354-2d8a-48c3-8647-70b2ac5a2e6a', '餞張七琚任宗城即環之季也同產八人俱以才名知', '餞張七琚任宗城即环之季也同產八人俱以才名知', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["他日曾遊魏，魏家餘趾存。","可憐宮殿所，但見桑榆繁。","此去拜新職，爲榮近故園。","高陽八才子，況復在君門。"]', '["他日曾游魏，魏家餘趾存。","可怜宮殿所，但见桑榆繁。","此去拜新職，爲榮近故园。","高陽八才子，況复在君门。"]', '诗', 'shi', '', NULL, '餞張七琚任宗城即環之季也同產八人俱以才名知 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7f6a757-4715-4def-972b-9f7d0accbbfe', '留別安慶李太守', '留別安慶李太守', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["明牧念行子，又言悲解攜。","初筵方落日，醉止到鳴雞。","過客來自北，大軍居在西。","兵家如討逆，敢以庶盤溪。"]', '["明牧念行子，又言悲解携。","初筵方落日，醉止到鳴雞。","過客来自北，大軍居在西。","兵家如討逆，敢以庶盤溪。"]', '诗', 'shi', '', NULL, '留別安慶李太守 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85114306-509d-4937-aa2c-02aadfa84705', '洛陽東門送別', '洛陽东门送別', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["東城別故人，臘月遲芳辰。","不惜孤舟去，其如兩地春。","花明洛陽苑，水綠小平津。","是日不相見，鶯聲徒自新。"]', '["东城別故人，臘月遲芳辰。","不惜孤舟去，其如兩地春。","花明洛陽苑，水綠小平津。","是日不相见，鶯声徒自新。"]', '诗', 'shi', '', NULL, '洛陽東門送別 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cc65c84-277a-45ab-8a97-c3c2b4497ff9', '漢陽即事', '漢陽即事', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["楚國千里遠，孰知方寸違。","春遊歡有客，夕寢賦無衣。","江水帶冰綠，桃花隨雨飛。","九歌有深意，捐佩乃言歸。"]', '["楚国千里远，孰知方寸違。","春游歡有客，夕寢賦無衣。","江水带冰綠，桃花隨雨飞。","九歌有深意，捐佩乃言归。"]', '诗', 'shi', '', NULL, '漢陽即事 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4f2909c-52b4-4786-930b-92169f597134', '泊江潭貽馬校書', '泊江潭貽马校书', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["明月掛青天，遙遙如目前。","故人遊畫閣，却望似雲邊。","水宿依漁父，歌聲好采蓮。","采蓮江上曲，今夕爲君傳。"]', '["明月掛青天，遙遙如目前。","故人游畫閣，却望似云邊。","水宿依漁父，歌声好采蓮。","采蓮江上曲，今夕爲君傳。"]', '诗', 'shi', '', NULL, '泊江潭貽馬校書 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('340134d6-aff3-428e-91f3-648ad3fd2fef', '送沈校書吳中搜書', '送沈校书吳中搜书', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["郊外亭臯遠，野中岐路分。","苑門臨渭水，山翠雜春雲。","秦閣多遺典，吳臺訪闕文。","君王思校理，莫滯清江濆。"]', '["郊外亭臯远，野中岐路分。","苑门臨渭水，山翠杂春云。","秦閣多遺典，吳台訪闕文。","君王思校理，莫滯清江濆。"]', '诗', 'shi', '', NULL, '送沈校書吳中搜書 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f871ab3-2946-4a55-b520-5d04d969d625', '寒夜江口泊舟', '寒夜江口泊舟', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["寒潮信未起，出浦纜孤舟。","一夜苦風浪，自然增旅愁。","吳山遲海月，楚火照江流。","欲有知音者，異鄉誰可求。"]', '["寒潮信未起，出浦纜孤舟。","一夜苦风浪，自然增旅愁。","吳山遲海月，楚火照江流。","欲有知音者，異乡誰可求。"]', '诗', 'shi', '', NULL, '寒夜江口泊舟 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07bc1851-2ed2-4ad7-bccb-e5a2725f3622', '苑外至龍興院作', '苑外至龙兴院作', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["朝遊天苑外，忽見法筵開。","山勢當空出，雲陰滿地來。","疎鐘清月殿，幽梵靜花臺。","日暮香林下，飄飄仙步迴。"]', '["朝游天苑外，忽见法筵开。","山勢當空出，云陰满地来。","疎鐘清月殿，幽梵静花台。","日暮香林下，飄飄仙步迴。"]', '诗', 'shi', '', NULL, '苑外至龍興院作 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69634ad9-987d-46aa-a611-fa2fa7774914', '題虬上人房', '題虬上人房', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["禪宮分兩地，釋子一爲心。","入道無來去，清言見古今。","江寒池水綠，山[暝]竹園深。","別有中天月，遙遙散夕陰。"]', '["禪宮分兩地，釋子一爲心。","入道無来去，清言见古今。","江寒池水綠，山[暝]竹园深。","別有中天月，遙遙散夕陰。"]', '诗', 'shi', '', NULL, '題虬上人房 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('acd9a51f-7359-44d7-b368-6ad43b0a2d1c', '詠山泉', '詠山泉', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["山中有流水，借問不知名。","映地爲天色，飛空作雨聲。","轉來深澗滿，分出小池平。","恬澹無人見，年年長自清。"]', '["山中有流水，借问不知名。","映地爲天色，飞空作雨声。","轉来深澗满，分出小池平。","恬澹無人见，年年长自清。"]', '诗', 'shi', '', NULL, '詠山泉 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('875ef17c-7dd9-45c8-9f1b-c6ba8f93bd81', '貽主客呂郎中', '貽主客呂郎中', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["上士既開天，中朝爲得賢。","青雲方羽翼，畫省比神仙。","委佩雲霄裏，含香日月前。","君王儻借問，客有上林篇。"]', '["上士既开天，中朝爲得賢。","青云方羽翼，畫省比神仙。","委佩云霄裏，含香日月前。","君王儻借问，客有上林篇。"]', '诗', 'shi', '', NULL, '貽主客呂郎中 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20de0cb4-fbe2-43c7-8305-239364b183c1', '京口留別徐大補闕趙二零陵', '京口留別徐大補闕趙二零陵', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["皇州月初曉，處處鼓鐘喧。","樹出蓬萊殿，城開閶闔門。","近臣朝瑣闥，詞客向文園。","獨有三川路，空傷遊子魂。"]', '["皇州月初晓，处处鼓鐘喧。","樹出蓬萊殿，城开閶闔门。","近臣朝瑣闥，词客向文园。","独有三川路，空傷游子魂。"]', '诗', 'shi', '', NULL, '京口留別徐大補闕趙二零陵 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25678390-be1b-4ceb-82d3-c06af67819c1', '答王十三維', '答王十三維', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["門生故來往，知欲命浮觴。","忽奉朝青閣，回車入上陽。","落花滿春水，疎柳映新塘。","是日歸來暮，勞君奏雅章。"]', '["门生故来往，知欲命浮觴。","忽奉朝青閣，回车入上陽。","落花满春水，疎柳映新塘。","是日归来暮，勞君奏雅章。"]', '诗', 'shi', '', NULL, '答王十三維 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa81d4a9-be50-455f-b42f-563be223f69c', '奉和中書徐侍郎中書省玩白雲寄頴陽趙大', '奉和中书徐侍郎中书省玩白云寄頴陽趙大', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["青闕朝初退，白雲遙在天。","非關取雷雨，故欲伴神仙。","泛灩鵷池曲，飄颻瑣闥前。","猶多遠山意，幸入侍臣篇。"]', '["青闕朝初退，白云遙在天。","非关取雷雨，故欲伴神仙。","泛灩鵷池曲，飄颻瑣闥前。","猶多远山意，幸入侍臣篇。"]', '诗', 'shi', '', NULL, '奉和中書徐侍郎中書省玩白雲寄頴陽趙大 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b2d83fc-df53-4d3d-9a40-8c20606fc3be', '和張太祝冬祭馬步', '和張太祝冬祭马步', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["故壇何肅肅，中野自無喧。","烈火見陳信，颺言聞永存。","房星隱曙色，朔風動寒原。","今日歌天馬，非關征大宛。"]', '["故壇何肅肅，中野自無喧。","烈火见陳信，颺言闻永存。","房星隐曙色，朔风动寒原。","今日歌天马，非关征大宛。"]', '诗', 'shi', '', NULL, '和張太祝冬祭馬步 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b676626-8a40-414f-af21-2ef31fcf2fa4', '祭風伯壇應張太祝作', '祭风伯壇應張太祝作', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["聖主御青春，綸言命使臣。","將修風伯祀，更福太平人。","帟幕宵聯事，壇場曉降神。","帝心矜動物，非爲屬車人。"]', '["聖主御青春，綸言命使臣。","將修风伯祀，更福太平人。","帟幕宵聯事，壇場晓降神。","帝心矜动物，非爲屬车人。"]', '诗', 'shi', '', NULL, '祭風伯壇應張太祝作 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a60e5ed-1bf6-4d87-87d4-86e8d56fac39', '尋徐山人遇馬舍人', '尋徐山人遇马舍人', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["泊舟伊川右，正見野人歸。","日暮春山綠，我心清且微。","巖聲風雨度，水氣雲霞飛。","復有金門客，來參蘿薜衣。"]', '["泊舟伊川右，正见野人归。","日暮春山綠，我心清且微。","巖声风雨度，水氣云霞飞。","复有金门客，来參蘿薜衣。"]', '诗', 'shi', '', NULL, '尋徐山人遇馬舍人 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8778b855-c076-4ed8-9323-37469ae46229', '夜觀妓', '夜观妓', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["白雪宜新舞，清宵召楚妃。","嬌童攜錦薦，侍女整羅衣。","花映垂鬟轉，香迎步履飛。","徐徐歛長袖，雙燭送將歸。"]', '["白雪宜新舞，清宵召楚妃。","嬌童携錦薦，侍女整羅衣。","花映垂鬟轉，香迎步履飞。","徐徐歛长袖，雙燭送將归。"]', '诗', 'shi', '', NULL, '夜觀妓 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c83c8b3-4b02-4620-bd30-fd5954105a69', '洛橋送別', '洛橋送別', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["河橋送客舟，河水正安流。","遠見輕橈動，遙憐故國遊。","海禽逢早鴈，江月值新秋。","一聽南津曲，分明散別愁。"]', '["河橋送客舟，河水正安流。","远见轻橈动，遙怜故国游。","海禽逢早鴈，江月值新秋。","一听南津曲，分明散別愁。"]', '诗', 'shi', '', NULL, '洛橋送別 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72c1861a-dc84-4b29-b0e1-7a72760c950f', '秦中送人覲省', '秦中送人覲省', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["二月清江外，遙遙餞故人。","南山晴有雪，東陌霽無塵。","騎別章臺晚，舟行洛水春。","知君梁苑去，日見白華新。"]', '["二月清江外，遙遙餞故人。","南山晴有雪，东陌霽無塵。","騎別章台晚，舟行洛水春。","知君梁苑去，日见白华新。"]', '诗', 'shi', '', NULL, '秦中送人覲省 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ffc26ef-fd5a-418e-807a-f555be01db9a', '洛中送人還江東', '洛中送人還江东', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["洛城春雨霽，相送下江鄉。","樹綠天津道，山明伊水陽。","孤舟從此去，客思一何長。","直望清波裏，唯餘落日光。"]', '["洛城春雨霽，相送下江乡。","樹綠天津道，山明伊水陽。","孤舟從此去，客思一何长。","直望清波裏，唯餘落日光。"]', '诗', 'shi', '', NULL, '洛中送人還江東 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('835ca302-684b-443d-8e07-8234fddb8ac3', '送姚六崑客任會稽何大蹇任孟縣', '送姚六崑客任會稽何大蹇任孟縣', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["越城臨渤澥，晉國在河汾。","仙綬兩鄉意，青郊一路分。","野棠春未發，田雀暮成羣。","他日思吳會，嘗因西北雲。"]', '["越城臨渤澥，晉国在河汾。","仙綬兩乡意，青郊一路分。","野棠春未發，田雀暮成羣。","他日思吳會，嘗因西北云。"]', '诗', 'shi', '', NULL, '送姚六崑客任會稽何大蹇任孟縣 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36cd07ff-cbc1-422b-8257-18aaa86edbc7', '洛潭送人覲省', '洛潭送人覲省', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["清洛帶芝田，東流入大川。","舟輕水復急，別望杳如仙。","細草生春岸，明霞散早天。","送君唯一曲，當是白華篇。"]', '["清洛带芝田，东流入大川。","舟轻水复急，別望杳如仙。","細草生春岸，明霞散早天。","送君唯一曲，當是白华篇。"]', '诗', 'shi', '', NULL, '洛潭送人覲省 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4da98d00-a669-436d-8212-1630dafb7824', '送人隨大夫和蕃', '送人隨大夫和蕃', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["西方有六國，國國願來賓。","聖主今無外，懷柔遣使臣。","大夫開幕府，才子作行人。","解劒聊相送，邊城二月春。"]', '["西方有六国，国国願来賓。","聖主今無外，懷柔遣使臣。","大夫开幕府，才子作行人。","解劒聊相送，邊城二月春。"]', '诗', 'shi', '', NULL, '送人隨大夫和蕃 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('645af21c-1afa-4cba-9334-8631c2b83d67', '仲夏餞魏四河北覲叔', '仲夏餞魏四河北覲叔', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["落日臨御溝，送君還北州。","樹涼征馬去，路暝歸人愁。","吳嶽夏雲盡，渭河秋水流。","東籬摘芳菊，想見竹林遊。"]', '["落日臨御溝，送君還北州。","樹涼征马去，路暝归人愁。","吳嶽夏云尽，渭河秋水流。","东籬摘芳菊，想见竹林游。"]', '诗', 'shi', '', NULL, '仲夏餞魏四河北覲叔 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13e1fad6-4593-4749-b593-3e44130088b2', '送人尋裴斐', '送人尋裴斐', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["柱史迴清憲，謫居臨漢川。","遲君千里駕，方外賞雲泉。","路斷因春水，山深隔暝煙。","湘江見遊女，寄摘一枝蓮。"]', '["柱史迴清憲，謫居臨漢川。","遲君千里駕，方外賞云泉。","路斷因春水，山深隔暝煙。","湘江见游女，寄摘一枝蓮。"]', '诗', 'shi', '', NULL, '送人尋裴斐 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df2ae035-c364-421b-b84b-c85f78bfbb19', '隴頭水送別', '隴头水送別', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["相送隴山頭，東西隴水流。","從來心膽盛，今日爲君愁。","暗雪迷征路，寒雲隱戍樓。","唯餘旌斾影，相逐去悠悠。"]', '["相送隴山头，东西隴水流。","從来心膽盛，今日爲君愁。","暗雪迷征路，寒云隐戍楼。","唯餘旌斾影，相逐去悠悠。"]', '诗', 'shi', '', NULL, '隴頭水送別 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3399d083-80e6-4cb3-ab5c-9c9986a46e0a', '送王上人還襄陽', '送王上人還襄陽', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["朝看法雲散，知有至人還。","送客臨伊水，行車出故關。","天花滿南國，精舍在空山。","雖復時來去，中心長日閑。"]', '["朝看法云散，知有至人還。","送客臨伊水，行车出故关。","天花满南国，精舍在空山。","雖复时来去，中心长日闲。"]', '诗', 'shi', '', NULL, '送王上人還襄陽 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d456416-fbd8-4121-91df-9c22cfe73646', '官莊池觀競渡', '官莊池观競渡', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["落日吹簫管，清池發櫂歌。","船爭先後渡，岸激去來波。","水葉藏魚鳥，林花間綺羅。","踟躕仙女處，猶似望天河。"]', '["落日吹簫管，清池發櫂歌。","船爭先後渡，岸激去来波。","水葉藏鱼鸟，林花间綺羅。","踟躕仙女处，猶似望天河。"]', '诗', 'shi', '', NULL, '官莊池觀競渡 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea180396-0d81-4084-ac98-c83f306b55e0', '重寄虬上人', '重寄虬上人', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["一作雲峰別，三看花柳朝。","青山隔遠路，明月空長霄。","鵲浴西江雨，雞鳴東海潮。","此情勞夢寐，況道雙林遙。"]', '["一作云峰別，三看花柳朝。","青山隔远路，明月空长霄。","鵲浴西江雨，雞鳴东海潮。","此情勞梦寐，況道雙林遙。"]', '诗', 'shi', '', NULL, '重寄虬上人 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('348682ac-e679-4f4f-935a-bbb2732ce446', '藍上茅茨期王維補闕', '藍上茅茨期王維補闕', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["山中人不見，雲去夕陽過。","淺瀨寒魚少，叢蘭秋蝶多。","老年疎世事，幽性樂天和。","酒熟思才子，谿頭望玉珂。"]', '["山中人不见，云去夕陽過。","淺瀨寒鱼少，叢蘭秋蝶多。","老年疎世事，幽性乐天和。","酒熟思才子，谿头望玉珂。"]', '诗', 'shi', '', NULL, '藍上茅茨期王維補闕 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9733ead-7d1e-4b64-abd5-f3e2955e9a55', '大酺得長字韻時任安宜尉', '大酺得长字韻时任安宜尉', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["大道啓元命，時人居太康。","中朝發玄澤，下國被天光。","明詔始端午，初筵當履霜。","鼓鼙迎爽氣，羽籥映新陽。","太守即懸圃，淮夷成葆疆。","小臣慙下位，拜手頌靈長。"]', '["大道啓元命，时人居太康。","中朝發玄澤，下国被天光。","明詔始端午，初筵當履霜。","鼓鼙迎爽氣，羽籥映新陽。","太守即懸圃，淮夷成葆疆。","小臣慙下位，拜手頌靈长。"]', '诗', 'shi', '', NULL, '大酺得長字韻時任安宜尉 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e741e6a-51c3-4eba-95b5-0bf714730803', '同張侍御鼎和京兆蕭兵曹華歲晚南園', '同張侍御鼎和京兆蕭兵曹华歲晚南园', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["公府傳休沐，私庭效陸沈。","方知從大隱，非復在幽林。","闕下忠貞志，人間孝友心。","既將冠蓋雅，仍與薜蘿深。","寒變中園柳，春歸上苑禽。","池涵青草色，山帶白雲陰。","潘岳閑居賦，鍾期流水琴。","一經當自足，何用遺黃金。"]', '["公府傳休沐，私庭效陸沈。","方知從大隐，非复在幽林。","闕下忠貞志，人间孝友心。","既將冠蓋雅，仍與薜蘿深。","寒变中园柳，春归上苑禽。","池涵青草色，山带白云陰。","潘岳闲居賦，鍾期流水琴。","一經當自足，何用遺黄金。"]', '诗', 'shi', '', NULL, '同張侍御鼎和京兆蕭兵曹華歲晚南園 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fee235e6-6eb0-4b97-8c3e-7c043f113a6e', '奉酬張五丈垂贈', '奉酬張五丈垂贈', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["綵服去江汜，白雲生大梁。","星辰動異色，羔鴈成新行。","日望天朝近，時憂郢路長。","情言間薖軸，惠念及滄浪。","松柏以之茂，江湖亦自忘。","賈生方弔屈，豈敢比南昌。"]', '["綵服去江汜，白云生大梁。","星辰动異色，羔鴈成新行。","日望天朝近，时憂郢路长。","情言间薖軸，惠念及滄浪。","松柏以之茂，江湖亦自忘。","賈生方弔屈，豈敢比南昌。"]', '诗', 'shi', '', NULL, '奉酬張五丈垂贈 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4daf63f-3c35-4f21-96d4-e8110e570e07', '秦中守歲', '秦中守歲', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["衆星已窮次，青帝方行春。","永感易成戚，離居難重陳。","闔門守初夜，燎火到清晨。","或念無生法，多傷未出塵。","廣庭日將晏，虛室自爲賓。","願以桑榆末，常逢甲子新。"]', '["衆星已窮次，青帝方行春。","永感易成戚，離居难重陳。","闔门守初夜，燎火到清晨。","或念無生法，多傷未出塵。","廣庭日將晏，虛室自爲賓。","願以桑榆末，常逢甲子新。"]', '诗', 'shi', '', NULL, '秦中守歲 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c92c83c-966e-4fc4-8b66-8e0e214dc3a0', '獻高使君大酺作', '獻高使君大酺作', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["肅穆郊禋畢，工歌賞事幷。","三朝遵湛露，一道洽仁明。","布德言皆應，無爲物自成。","花添羅綺色，鶯亂管弦聲。","獨有同高唱，空陪樂太平。"]', '["肅穆郊禋畢，工歌賞事幷。","三朝遵湛露，一道洽仁明。","布德言皆應，無爲物自成。","花添羅綺色，鶯亂管弦声。","独有同高唱，空陪乐太平。"]', '诗', 'shi', '', NULL, '獻高使君大酺作 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac094935-0541-45c9-9e19-5c9a24988acc', '滎陽馬氏二子', '滎陽马氏二子', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["聖君封太嶽，十月建行旃。","輦路開千里，寒雲霽九天。","故人多侍從，二子留伊川。","河兗冰初合，關城月屢圓。","暝過滎水上，聞說鄭卿賢。","材蔽行人右，名居東里先。","制巖開別業，桑柘亦依然。","待至金園側，相將居一廛。"]', '["聖君封太嶽，十月建行旃。","輦路开千里，寒云霽九天。","故人多侍從，二子留伊川。","河兗冰初合，关城月屢圓。","暝過滎水上，闻说鄭卿賢。","材蔽行人右，名居东里先。","制巖开別業，桑柘亦依然。","待至金园側，相將居一廛。"]', '诗', 'shi', '', NULL, '滎陽馬氏二子 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e73369ec-6774-4fb3-9a3b-1d71695c105b', '觀競渡', '观競渡', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["大夫沈楚水，千祀國人哀。","習櫂江流長，迎神雨霧開。","標隨綠雲動，船逆清波來。","下怖魚龍起，上驚鳧鴈迴。","能令秋大有，鼓吹遠相催。"]', '["大夫沈楚水，千祀国人哀。","習櫂江流长，迎神雨霧开。","標隨綠云动，船逆清波来。","下怖鱼龙起，上驚鳧鴈迴。","能令秋大有，鼓吹远相催。"]', '诗', 'shi', '', NULL, '觀競渡 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b28389ba-7323-4b97-81f9-7cd20532267c', '太學貽張筠', '太学貽張筠', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["璧池忝門子，俄頃變炎涼。","綠竹深虛館，清流響洞房。","園林在建業，新友去咸陽。","中夜鼓鐘靜，初秋漏刻長。","浮雲開太室，華蓋上明堂。","空此遠相望，勞歌還自傷。"]', '["璧池忝门子，俄頃变炎涼。","綠竹深虛館，清流响洞房。","园林在建業，新友去咸陽。","中夜鼓鐘静，初秋漏刻长。","浮云开太室，华蓋上明堂。","空此远相望，勞歌還自傷。"]', '诗', 'shi', '', NULL, '太學貽張筠 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f44da1e8-6289-4f0e-a607-7feb1cdeb2e6', '田家即事', '田家即事', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["桑柘悠悠水蘸堤，晚風晴景不妨犂。","高機猶織臥蠶子，下坂飢逢餉饁妻。","杏色滿林羊酪熟，麥涼浮壠雉媒低。","生時樂死皆由命，事在皇天志不迷。"]', '["桑柘悠悠水蘸堤，晚风晴景不妨犂。","高機猶织臥蠶子，下坂飢逢餉饁妻。","杏色满林羊酪熟，麦涼浮壠雉媒低。","生时乐死皆由命，事在皇天志不迷。"]', '诗', 'shi', '', NULL, '田家即事 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e78c496b-cfd3-4919-9634-a5c3253889e2', '洛陽道五首獻呂四郎中 一', '洛陽道五首獻呂四郎中 一', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["洛水春冰開，洛城春水綠。","朝看大道上，落花亂馬足。"]', '["洛水春冰开，洛城春水綠。","朝看大道上，落花亂马足。"]', '诗', 'shi', '', NULL, '洛陽道五首獻呂四郎中 一 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2e7bf8f-c30c-40a0-92c0-c9e1ddcd1ed5', '洛陽道五首獻呂四郎中 二', '洛陽道五首獻呂四郎中 二', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["劇孟不知名，千金買寶劍/。","出入平津邸，自言嬌且豔。"]', '["劇孟不知名，千金買寶劍/。","出入平津邸，自言嬌且豔。"]', '诗', 'shi', '', NULL, '洛陽道五首獻呂四郎中 二 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2799a70a-5cc0-421e-9e10-72eb23053ea5', '洛陽道五首獻呂四郎中 三', '洛陽道五首獻呂四郎中 三', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["大道直如髮，春日佳氣多。","五陵貴公子，雙雙鳴玉珂。"]', '["大道直如髮，春日佳氣多。","五陵貴公子，雙雙鳴玉珂。"]', '诗', 'shi', '', NULL, '洛陽道五首獻呂四郎中 三 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71f5dc4c-6e81-4e4b-a3e3-2534be3873ac', '洛陽道五首獻呂四郎中 四', '洛陽道五首獻呂四郎中 四', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["春風二月時，道傍柳堪把。","上枝覆官閣，下枝覆車馬。"]', '["春风二月时，道傍柳堪把。","上枝覆官閣，下枝覆车马。"]', '诗', 'shi', '', NULL, '洛陽道五首獻呂四郎中 四 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9beccc1-6838-4aac-a19c-ce1fa0b1404b', '洛陽道五首獻呂四郎中 五', '洛陽道五首獻呂四郎中 五', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["洛水照千門，千門碧空裏。","少年不得志，走馬遊新市。"]', '["洛水照千门，千门碧空裏。","少年不得志，走马游新市。"]', '诗', 'shi', '', NULL, '洛陽道五首獻呂四郎中 五 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d542486-50c6-40b9-adfe-909b5ff172c8', '同武平一員外遊湖', '同武平一員外游湖', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["竹吹留歌扇，蓮香入舞衣。","前溪多曲漵，乘興莫先歸。"]', '["竹吹留歌扇，蓮香入舞衣。","前溪多曲漵，乘兴莫先归。"]', '诗', 'shi', '', NULL, '同武平一員外遊湖 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90aca2d1-de03-466f-8f11-f2b648788de3', '長安道 一', '长安道 一', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["鳴鞭過酒肆，袨服遊倡門。","百萬一時盡，含情無片言。"]', '["鳴鞭過酒肆，袨服游倡门。","百万一时尽，含情無片言。"]', '诗', 'shi', '', NULL, '長安道 一 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95fc9ecc-7201-4fbf-8682-bc9e7156267a', '長安道 二', '长安道 二', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["西行一千里，暝色生寒樹。","暗聞歌吹聲，知是長安路。"]', '["西行一千里，暝色生寒樹。","暗闻歌吹声，知是长安路。"]', '诗', 'shi', '', NULL, '長安道 二 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe326097-17a7-4f35-a32b-417d412b149b', '江南曲四首 一', '江南曲四首 一', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["綠江深見底，高浪直翻空。","慣是湖邊住，舟輕不畏風。"]', '["綠江深见底，高浪直翻空。","慣是湖邊住，舟轻不畏风。"]', '诗', 'shi', '', NULL, '江南曲四首 一 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ba77fc3-15e1-49c2-bf76-fb6ba2147136', '江南曲四首 二', '江南曲四首 二', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["逐流牽荇葉，綠岸摘蘆苗。","爲惜鴛鴦鳥，輕輕動畫橈。"]', '["逐流牽荇葉，綠岸摘蘆苗。","爲惜鴛鴦鸟，轻轻动畫橈。"]', '诗', 'shi', '', NULL, '江南曲四首 二 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d095b65e-7e44-4e42-86c1-3708c499e237', '江南曲四首 三', '江南曲四首 三', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["日暮長江裏，相邀歸渡頭。","落花如有意，來去逐船流。"]', '["日暮长江裏，相邀归渡头。","落花如有意，来去逐船流。"]', '诗', 'shi', '', NULL, '江南曲四首 三 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('158cc8e9-d27d-4496-a0a5-8d9fcd7bc9eb', '江南曲四首 四', '江南曲四首 四', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["隔江看樹色，沿月聽歌聲。","不是長干住，那從此路行。"]', '["隔江看樹色，沿月听歌声。","不是长干住，那從此路行。"]', '诗', 'shi', '', NULL, '江南曲四首 四 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d9694d9-9424-41ba-8a0c-4e6a2bee769d', '關山月', '关山月', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["一鴈過連營，繁霜覆古城。","胡笳在何處？半夜起邊聲。"]', '["一鴈過連營，繁霜覆古城。","胡笳在何处？半夜起邊声。"]', '诗', 'shi', '', NULL, '關山月 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b28f66aa-6354-4298-96cd-10b5154acc98', '玉真公主山居', '玉真公主山居', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["山北天泉苑，山西鳳女家。","不言沁園好，獨隱武陵花。"]', '["山北天泉苑，山西鳳女家。","不言沁园好，独隐武陵花。"]', '诗', 'shi', '', NULL, '玉真公主山居 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99ba45d7-7930-4c5b-8b49-fdc9e5d1704e', '滄浪峽', '滄浪峽', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["滄浪臨古道，道上若成塵。","自有滄浪峽，誰爲無事人。"]', '["滄浪臨古道，道上若成塵。","自有滄浪峽，誰爲無事人。"]', '诗', 'shi', '', NULL, '滄浪峽 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e26b59de-597a-433f-8f89-49fc83e0407e', '奉真觀', '奉真观', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["真門逈向北，馳道直向西。","爲與天光近，雲色成虹霓。"]', '["真门逈向北，驰道直向西。","爲與天光近，云色成虹霓。"]', '诗', 'shi', '', NULL, '奉真觀 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3cd9814-5264-44c4-b2a0-7e42e0933d5b', '明妃曲四首 一', '明妃曲四首 一', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["西行隴上泣胡天，南向雲中指渭川。","毳幕夜來時宛轉，何由得似漢王邊。"]', '["西行隴上泣胡天，南向云中指渭川。","毳幕夜来时宛轉，何由得似漢王邊。"]', '诗', 'shi', '', NULL, '明妃曲四首 一 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0e8a0e1-b173-411f-9fce-9335163b797f', '明妃曲四首 二', '明妃曲四首 二', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["胡王知妾不勝悲，樂府皆傳漢國辭。","朝來馬上箜篌引，稍似宮中閑夜時。"]', '["胡王知妾不勝悲，乐府皆傳漢国辞。","朝来马上箜篌引，稍似宮中闲夜时。"]', '诗', 'shi', '', NULL, '明妃曲四首 二 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('302c12c6-de5f-41fc-8842-c158c4df3028', '明妃曲四首 三', '明妃曲四首 三', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["日暮驚沙亂雪飛，傍人相勸易羅衣。","強來前殿看歌舞，共待單于夜獵歸。"]', '["日暮驚沙亂雪飞，傍人相勸易羅衣。","強来前殿看歌舞，共待單于夜獵归。"]', '诗', 'shi', '', NULL, '明妃曲四首 三 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12d9d605-70e5-4c43-90c4-7a9d666a4f1d', '明妃曲四首 四', '明妃曲四首 四', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["彩騎雙雙引寶車，羌笛兩兩奏胡笳。","若爲別得橫橋路，莫隱宮中玉樹花。"]', '["彩騎雙雙引寶车，羌笛兩兩奏胡笳。","若爲別得橫橋路，莫隐宮中玉樹花。"]', '诗', 'shi', '', NULL, '明妃曲四首 四 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7363995-2c35-46d0-9e67-2ab8e9eed8a4', '同武平一員外遊湖五首時武貶金壇令 一', '同武平一員外游湖五首时武貶金壇令 一', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["紅荷碧篠夜相鮮，皂蓋蘭橈浮翠筵。","舟中對舞邯鄲曲，月下雙彈盧女弦。"]', '["紅荷碧篠夜相鲜，皂蓋蘭橈浮翠筵。","舟中对舞邯鄲曲，月下雙彈盧女弦。"]', '诗', 'shi', '', NULL, '同武平一員外遊湖五首時武貶金壇令 一 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e1c3eef-ba92-4723-93f8-071551e83329', '同武平一員外遊湖五首時武貶金壇令 二', '同武平一員外游湖五首时武貶金壇令 二', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["青林碧嶼暗相期，緩楫揮觥欲賦詩。","借問高歌凡幾轉，河低月落五更時。"]', '["青林碧嶼暗相期，緩楫揮觥欲賦诗。","借问高歌凡幾轉，河低月落五更时。"]', '诗', 'shi', '', NULL, '同武平一員外遊湖五首時武貶金壇令 二 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbea5bfe-3760-4eb7-9d10-92f699fa1004', '同武平一員外遊湖五首時武貶金壇令 三', '同武平一員外游湖五首时武貶金壇令 三', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["朝來仙閣聽弦歌，暝入花亭見綺羅。","池邊命酒憐風月，浦口回船惜芰荷。"]', '["朝来仙閣听弦歌，暝入花亭见綺羅。","池邊命酒怜风月，浦口回船惜芰荷。"]', '诗', 'shi', '', NULL, '同武平一員外遊湖五首時武貶金壇令 三 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8dd306e7-e6e9-41bc-a2b3-f7fa76c80738', '同武平一員外遊湖五首時武貶金壇令 四', '同武平一員外游湖五首时武貶金壇令 四', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["朦朧竹影蔽巖扉，淡蕩荷風飄舞衣。","舟尋綠水宵將半，月隱青林人未歸。"]', '["朦朧竹影蔽巖扉，淡蕩荷风飄舞衣。","舟尋綠水宵將半，月隐青林人未归。"]', '诗', 'shi', '', NULL, '同武平一員外遊湖五首時武貶金壇令 四 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3af69bfe-5e4a-4e81-9e75-f7d5c921515b', '同武平一員外遊湖五首時武貶金壇令 五', '同武平一員外游湖五首时武貶金壇令 五', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["花潭竹嶼傍幽蹊，畫檝浮空入夜溪。","芰荷覆水船難進，歌舞留人月易低。"]', '["花潭竹嶼傍幽蹊，畫檝浮空入夜溪。","芰荷覆水船难進，歌舞留人月易低。"]', '诗', 'shi', '', NULL, '同武平一員外遊湖五首時武貶金壇令 五 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('170f9a76-d5fb-43be-970d-a0568afba39b', '題茅山華陽洞', '題茅山华陽洞', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["華陽洞口片雲飛，細雨濛濛欲濕衣。","玉簫遍滿仙壇上，應是茅家兄弟歸。"]', '["华陽洞口片云飞，細雨濛濛欲濕衣。","玉簫遍满仙壇上，應是茅家兄弟归。"]', '诗', 'shi', '', NULL, '題茅山華陽洞 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94291c7d-6279-44e5-924f-bc2d5288ee1d', '寄孫山人', '寄孫山人', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["新林二月孤舟還，水滿清江花滿山。","借問故園隱君子，時時來往住人間。"]', '["新林二月孤舟還，水满清江花满山。","借问故园隐君子，时时来往住人间。"]', '诗', 'shi', '', NULL, '寄孫山人 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('041cde06-3afc-4e27-b4c4-eb8d39211c9b', '變行路難', '变行路难', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["向晚橫吹悲，風動馬嘶合。","前趨引旗節，千里陣雲帀。","單于下陰山，砂礫空颯颯。","封侯取一戰，豈復念閨閤。"]', '["向晚橫吹悲，风动马嘶合。","前趨引旗節，千里陣云帀。","單于下陰山，砂礫空颯颯。","封侯取一戰，豈复念閨閤。"]', '诗', 'shi', '', NULL, '變行路難 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d58a158-1a9b-4085-8ef7-b7b4e6adb66d', '塞下曲四首 一', '塞下曲四首 一', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["蟬鳴空桑林，八月蕭關道。","出塞入塞寒，處處黃蘆草。","從來幽幷客，皆共塵沙老。","莫學遊俠兒，矜夸紫騮好。"]', '["蟬鳴空桑林，八月蕭关道。","出塞入塞寒，处处黄蘆草。","從来幽幷客，皆共塵沙老。","莫学游俠兒，矜夸紫騮好。"]', '诗', 'shi', '', NULL, '塞下曲四首 一 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59fb3f01-65b2-416a-aefb-c13e502bfba1', '塞下曲四首 二', '塞下曲四首 二', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["飲馬渡秋水，水寒風似刀。","平沙日未沒，黯黯見臨洮。","昔日長城戰，咸言意氣高。","黃塵足今古，白骨亂蓬蒿。"]', '["饮马渡秋水，水寒风似刀。","平沙日未沒，黯黯见臨洮。","昔日长城戰，咸言意氣高。","黄塵足今古，白骨亂蓬蒿。"]', '诗', 'shi', '', NULL, '塞下曲四首 二 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4eb08533-cc6b-40cc-af72-fe3aae695224', '塞下曲四首 三', '塞下曲四首 三', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["奉詔甘泉宮，總徵天下兵。","朝廷備禮出，郡國豫郊迎。","紛紛幾萬人，去者無全生。","臣願節宮廐，分以賜邊城。"]', '["奉詔甘泉宮，總徵天下兵。","朝廷備禮出，郡国豫郊迎。","紛紛幾万人，去者無全生。","臣願節宮廐，分以賜邊城。"]', '诗', 'shi', '', NULL, '塞下曲四首 三 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2863d1fe-dd22-43a7-b067-4b323c8fec7f', '塞下曲四首 四', '塞下曲四首 四', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["邊頭何慘慘，已葬霍將軍。","部曲皆相弔，燕南代北聞。","功勳多被黜，兵馬亦尋分。","更遣黃龍戍，唯當哭塞雲。"]', '["邊头何慘慘，已葬霍將軍。","部曲皆相弔，燕南代北闻。","功勳多被黜，兵马亦尋分。","更遣黄龙戍，唯當哭塞云。"]', '诗', 'shi', '', NULL, '塞下曲四首 四 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56950b6b-d796-4436-a80a-cca1f325d978', '塞上曲', '塞上曲', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["秋風夜渡河，吹却鴈門桑。","遙見胡地獵，鞲馬宿嚴霜。","五道分兵去，孤軍百戰場。","功多翻下獄，士卒但心傷。"]', '["秋风夜渡河，吹却鴈门桑。","遙见胡地獵，鞲马宿嚴霜。","五道分兵去，孤軍百戰場。","功多翻下獄，士卒但心傷。"]', '诗', 'shi', '', NULL, '塞上曲 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23f9cc7d-51cf-4f53-a8ad-58f107aec73d', '從軍行二首 一', '從軍行二首 一', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["向夕臨大荒，朔風軫歸慮。","平沙萬里餘，飛鳥宿何處？","虜騎獵長原，翩翩傍河去。","邊聲搖白草，海氣生黃霧。","百戰苦風塵，十年履霜露。","雖投定遠筆，未坐將軍樹。","早知行路難，悔不理章句。"]', '["向夕臨大荒，朔风軫归慮。","平沙万里餘，飞鸟宿何处？","虜騎獵长原，翩翩傍河去。","邊声搖白草，海氣生黄霧。","百戰苦风塵，十年履霜露。","雖投定远笔，未坐將軍樹。","早知行路难，悔不理章句。"]', '诗', 'shi', '', NULL, '從軍行二首 一 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1118052-b14f-4b18-9a45-c4c53b95f2e0', '從軍行二首 二', '從軍行二首 二', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["秋草馬蹄輕，角弓持弦急。","去爲龍城戰，正值胡兵襲。","軍氣橫大荒，戰酣日將入。","長風金鼓動，白露鐵衣濕。","四起愁邊聲，南庭時佇立。","斷蓬孤自轉，寒雁飛相及。","萬里雲沙漲，平原冰霰澀。","惟聞漢使還，獨向刀環泣。"]', '["秋草马蹄轻，角弓持弦急。","去爲龙城戰，正值胡兵襲。","軍氣橫大荒，戰酣日將入。","长风金鼓动，白露鐵衣濕。","四起愁邊声，南庭时佇立。","斷蓬孤自轉，寒雁飞相及。","万里云沙漲，平原冰霰澀。","惟闻漢使還，独向刀环泣。"]', '诗', 'shi', '', NULL, '從軍行二首 二 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de4a1ec9-b488-4b00-bb31-469028426436', '少年行二首 一', '少年行二首 一', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["西陵俠少年，送客短長亭。","青槐夾兩道，白馬如流星。","聞道羽書急，單于寇井陘。","氣高輕赴難，誰顧燕山銘。"]', '["西陵俠少年，送客短长亭。","青槐夾兩道，白马如流星。","闻道羽书急，單于寇井陘。","氣高轻赴难，誰顧燕山銘。"]', '诗', 'shi', '', NULL, '少年行二首 一 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f4352c5-c777-414c-8645-c3912a704f85', '少年行二首 二', '少年行二首 二', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["走馬遠相尋，西樓下夕陰。","結交期一劒，留意贈千金。","高閣歌聲遠，重門柳色深。","夜闌須盡飲，莫負百年心。"]', '["走马远相尋，西楼下夕陰。","結交期一劒，留意贈千金。","高閣歌声远，重门柳色深。","夜闌須尽饮，莫負百年心。"]', '诗', 'shi', '', NULL, '少年行二首 二 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b48f64cf-d565-4964-a258-f44b07512fd8', '長歌行', '长歌行', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["曠野饒悲風，颼颼黃蒿草。","繫馬倚白楊，誰知我懷抱。","所是同袍者，相逢盡衰老。","北登漢家陵，南望長安道。","下有枯樹根，上有鼯鼠窠。","高皇子孫盡，千載無人過。","寶玉頻發掘，精靈其奈何？","人生須達命，有酒且長歌。"]', '["曠野饒悲风，颼颼黄蒿草。","繫马倚白楊，誰知我懷抱。","所是同袍者，相逢尽衰老。","北登漢家陵，南望长安道。","下有枯樹根，上有鼯鼠窠。","高皇子孫尽，千載無人過。","寶玉頻發掘，精靈其奈何？","人生須達命，有酒且长歌。"]', '诗', 'shi', '', NULL, '長歌行 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('164b3169-b72d-46ec-9302-bfb37d1f5295', '悲哉行', '悲哉行', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["勿聽白頭吟，人間易憂怨。","若非滄浪子，安得從所願。","北上太行山，臨風閱吹萬。","長雲數千里，倏忽還膚寸。","觀其微滅時，精意莫能論。","百年不容息，是處生意蔓。","始悟海上人，辭君永飛遯。"]', '["勿听白头吟，人间易憂怨。","若非滄浪子，安得從所願。","北上太行山，臨风閱吹万。","长云數千里，倏忽還膚寸。","观其微滅时，精意莫能論。","百年不容息，是处生意蔓。","始悟海上人，辞君永飞遯。"]', '诗', 'shi', '', NULL, '悲哉行 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bb7dd4c-9726-4ca3-aa8b-8f764f039848', '古意', '古意', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["桃花四面發，桃葉一枝開。","欲暮黃鸝囀，傷心玉鏡臺。","清箏向明月，半夜春風來。"]', '["桃花四面發，桃葉一枝开。","欲暮黄鸝囀，傷心玉镜台。","清箏向明月，半夜春风来。"]', '诗', 'shi', '', NULL, '古意 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cdb8ee8-f0b9-4e0b-9db3-10fc92b26ebb', '放歌行', '放歌行', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["南渡洛陽津，西望十二樓。","明堂坐天子，月朔朝諸侯。","清樂動千門，皇風被九州。","慶雲從東來，泱漭抱日流。","昇平貴論道，文墨將何求？","有詔徵草澤，微誠將獻謀。","冠冕如星羅，拜揖曹與周。","望塵非吾事，入賦且遲留。","幸蒙國士識，因脫負薪裘。","今者放歌行，以慰梁甫愁。","但營數斗祿，奉養每豐羞。","若得金膏遂，飛雲亦何儔。"]', '["南渡洛陽津，西望十二楼。","明堂坐天子，月朔朝諸侯。","清乐动千门，皇风被九州。","慶云從东来，泱漭抱日流。","昇平貴論道，文墨將何求？","有詔徵草澤，微誠將獻謀。","冠冕如星羅，拜揖曹與周。","望塵非吾事，入賦且遲留。","幸蒙国士識，因脫負薪裘。","今者放歌行，以慰梁甫愁。","但營數斗祿，奉養每豐羞。","若得金膏遂，飞云亦何儔。"]', '诗', 'shi', '', NULL, '放歌行 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53f1aab9-1c67-48a4-a0ed-cc777a10c389', '越女', '越女', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["越女作桂舟，還將桂爲楫。","湖上水渺漫，清江不可涉。","摘取芙蓉花，莫摘芙蓉葉。","將歸問夫壻，顏色何如妾。"]', '["越女作桂舟，還將桂爲楫。","湖上水渺漫，清江不可涉。","摘取芙蓉花，莫摘芙蓉葉。","將归问夫壻，顏色何如妾。"]', '诗', 'shi', '', NULL, '越女 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d41ca296-73e6-4e8f-8a05-36809d471157', '鄭縣宿陶太公館中贈馮六元二', '鄭縣宿陶太公館中贈馮六元二', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["儒有輕王侯，脫略當事務。","本家藍田下，非爲漁弋故。","無何困躬耕，且欲馳永路。","幽居與君近，出谷同所騖。","昨日辭石門，五年變秋露。","雲龍未相感，干謁亦已屢。","子爲黃綬羈，余忝蓬山顧。","京門望西嶽，百里見郊樹。","飛雨祠上來，靄然關中暮。","驅車鄭城宿，秉燭論往素。","山月出華陰，開此河渚霧。","清光比故人，豁達展心晤。","馮公尚戢翼，元子仍跼步。","拂衣易爲高，淪跡難有趣。","張范善終始，吾等豈不慕。","罷酒當涼風，屈伸備冥數。"]', '["儒有轻王侯，脫略當事務。","本家藍田下，非爲漁弋故。","無何困躬耕，且欲驰永路。","幽居與君近，出谷同所騖。","昨日辞石门，五年变秋露。","云龙未相感，干謁亦已屢。","子爲黄綬羈，余忝蓬山顧。","京门望西嶽，百里见郊樹。","飞雨祠上来，靄然关中暮。","驱车鄭城宿，秉燭論往素。","山月出华陰，开此河渚霧。","清光比故人，豁達展心晤。","馮公尚戢翼，元子仍跼步。","拂衣易爲高，淪跡难有趣。","張范善終始，吾等豈不慕。","罷酒當涼风，屈伸備冥數。"]', '诗', 'shi', '', NULL, '鄭縣宿陶太公館中贈馮六元二 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50043733-c059-4f9e-9897-5522f30348a1', '聽彈風入松闋贈楊補闕', '听彈风入松闋贈楊補闕', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["商風入我絃，夜竹深有露。","絃悲與林寂，清景不可度。","寥落幽居心，颼飀青松樹。","松風吹草白，溪水寒日暮。","聲意去復還，九變待一顧。","空山多雨雪，獨立君始悟。"]', '["商风入我絃，夜竹深有露。","絃悲與林寂，清景不可度。","寥落幽居心，颼飀青松樹。","松风吹草白，溪水寒日暮。","声意去复還，九变待一顧。","空山多雨雪，独立君始悟。"]', '诗', 'shi', '', NULL, '聽彈風入松闋贈楊補闕 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd5fc55a-6d76-446a-93e0-523b016a6aea', '緱氏尉沈興宗置酒南谿留贈', '緱氏尉沈兴宗置酒南谿留贈', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["林色與溪古，深篁引幽翠。","山尊在漁舟，棹月情已醉。","始窮清源口，壑絕人境異。","春泉滴空崖，萌草拆陰地。","久之風榛寂，遠聞樵聲至。","海雁時獨飛，永然滄洲意。","古時青冥客，滅跡淪一尉。","吾子躊躇心，豈其紛埃事。","緱峯信所剋，濟北余乃遂。","齊物意已會，息肩理猶未。","卷舒形性表，脫略賢哲議。","仲月期角巾，飯僧嵩陽寺。"]', '["林色與溪古，深篁引幽翠。","山尊在漁舟，棹月情已醉。","始窮清源口，壑絕人境異。","春泉滴空崖，萌草拆陰地。","久之风榛寂，远闻樵声至。","海雁时独飞，永然滄洲意。","古时青冥客，滅跡淪一尉。","吾子躊躇心，豈其紛埃事。","緱峯信所剋，濟北余乃遂。","齊物意已會，息肩理猶未。","卷舒形性表，脫略賢哲議。","仲月期角巾，飯僧嵩陽寺。"]', '诗', 'shi', '', NULL, '緱氏尉沈興宗置酒南谿留贈 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4f49265-6689-4a47-a119-6f8bba4272ba', '爲張僓贈閻使臣', '爲張僓贈閻使臣', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["哀哀獻玉人，楚國同悲辛。","泣盡繼以血，何由辨其真。","賴承琢磨惠，復使光輝新。","猶畏讒口疾，棄之如埃塵。"]', '["哀哀獻玉人，楚国同悲辛。","泣尽繼以血，何由辨其真。","賴承琢磨惠，复使光輝新。","猶畏讒口疾，棄之如埃塵。"]', '诗', 'shi', '', NULL, '爲張僓贈閻使臣 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb6d873b-73c8-4668-bdb9-7b6b3e989b51', '贈史昭', '贈史昭', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["東林月未升，廓落星與漢。","是夕鴻始來，齋中起長歎。","懷哉望南浦，眇然夜將半。","但有秋水聲，愁使心神亂。","握中何爲贈，瑤草已衰散。","海鱗未化時，各在天一岸。"]', '["东林月未升，廓落星與漢。","是夕鴻始来，斋中起长歎。","懷哉望南浦，眇然夜將半。","但有秋水声，愁使心神亂。","握中何爲贈，瑤草已衰散。","海鱗未化时，各在天一岸。"]', '诗', 'shi', '', NULL, '贈史昭 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bd15cbf-8fd9-46e6-9b4b-d193cefacad4', '秋山寄陳讜言', '秋山寄陳讜言', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["巖間寒事早，衆山木已黃。","北風何蕭蕭，茲夕露爲霜。","感激未能寐，中宵時慨慷。","黃蟲初悲鳴，玄鳥去我梁。","獨臥時易晚，離羣情更傷。","思君若不及，鴻雁今南翔。"]', '["巖间寒事早，衆山木已黄。","北风何蕭蕭，茲夕露爲霜。","感激未能寐，中宵时慨慷。","黄蟲初悲鳴，玄鸟去我梁。","独臥时易晚，離羣情更傷。","思君若不及，鴻雁今南翔。"]', '诗', 'shi', '', NULL, '秋山寄陳讜言 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5bb6013-e22e-47f6-ac1b-1cfb231eb73f', '出郴山口至疊石灣野人室中寄張十一', '出郴山口至叠石灣野人室中寄張十一', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["櫧柟無冬春，柯葉連峯稠。","陰壁下蒼黑，煙含清江樓。","景開獨沿曳，響答隨興酬。","旦夕望吾友，如何迅孤舟。","疊沙積爲崗，崩剝雨露幽。","石脉盡橫亙，潛潭何時流。","既見萬古色，頗盡一物由。","永與世人遠，氣還草木收。","盈縮理無餘，今往何必憂。","郴土羣山高，耆老如中州。","孰云議舛降，豈是娛宦遊。","陰火昔所伏，丹砂將爾謀。","昨臨蘇耽井，復向衡陽求。","同疚來相依，脫身當有籌。","數月乃離居，風湍成阻脩。","野人善竹器，童子能谿謳。","寒夜波蕩漾，羇鴻去悠悠。"]', '["櫧柟無冬春，柯葉連峯稠。","陰壁下蒼黑，煙含清江楼。","景开独沿曳，响答隨兴酬。","旦夕望吾友，如何迅孤舟。","叠沙積爲崗，崩剝雨露幽。","石脉尽橫亙，潛潭何时流。","既见万古色，頗尽一物由。","永與世人远，氣還草木收。","盈縮理無餘，今往何必憂。","郴土羣山高，耆老如中州。","孰云議舛降，豈是娛宦游。","陰火昔所伏，丹砂將爾謀。","昨臨蘇耽井，复向衡陽求。","同疚来相依，脫身當有籌。","數月乃離居，风湍成阻脩。","野人善竹器，童子能谿謳。","寒夜波蕩漾，羇鴻去悠悠。"]', '诗', 'shi', '', NULL, '出郴山口至疊石灣野人室中寄張十一 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09ce19c2-d94c-4d26-898a-6ad89bcba2d5', '宿灞上寄侍御璵弟', '宿灞上寄侍御璵弟', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["獨飲灞上亭，寒山青門外。","長雲驟落日，桑棗寂已晦。","古人驅馳者，宿此凡幾代。","佐邑由東南，豈不知進退。","吾宗秉全璞，楚得璆琳最。","茅山就一徵，柏署起三載。","道契非物理，神交無留礙。","知我滄溟心，脫略腐儒輩。","孟冬鑾輿出，陽谷羣臣會。","半夜馳道喧，五侯擁軒蓋。","是時燕齊客，獻術蓬瀛內。","甚悅我皇心，得與王母對。","賤臣欲干謁，稽首期殞碎。","哲弟感我情，問易窮否泰。","良馬足尚踠，寶刀光未淬。","昨聞羽書飛，兵氣連朔塞。","諸將多失律，廟堂始追悔。","安能召書生，願得論要害。","戎夷非草木，侵逐使狼狽。","雖有屠城功，亦有降虜輩。","兵糧如山積，恩澤如雨霈。","羸卒不可興，磧地無足愛。","若用匹夫策，坐令軍圍潰。","不費黃金資，寧求白璧賚。","明主憂既遠，邊事亦可大。","荷寵務推誠，離言深慷慨。","霜搖直指草，燭引明光珮。","公論日夕阻，朝廷磋跎會。","孤城海門月，萬里流光帶。","不應百尺松，空老鍾山靄。"]', '["独饮灞上亭，寒山青门外。","长云驟落日，桑棗寂已晦。","古人驱驰者，宿此凡幾代。","佐邑由东南，豈不知進退。","吾宗秉全璞，楚得璆琳最。","茅山就一徵，柏署起三載。","道契非物理，神交無留礙。","知我滄溟心，脫略腐儒輩。","孟冬鑾輿出，陽谷羣臣會。","半夜驰道喧，五侯擁軒蓋。","是时燕齊客，獻術蓬瀛內。","甚悅我皇心，得與王母对。","賤臣欲干謁，稽首期殞碎。","哲弟感我情，问易窮否泰。","良马足尚踠，寶刀光未淬。","昨闻羽书飞，兵氣連朔塞。","諸將多失律，廟堂始追悔。","安能召书生，願得論要害。","戎夷非草木，侵逐使狼狽。","雖有屠城功，亦有降虜輩。","兵糧如山積，恩澤如雨霈。","羸卒不可兴，磧地無足愛。","若用匹夫策，坐令軍圍潰。","不費黄金資，寧求白璧賚。","明主憂既远，邊事亦可大。","荷寵務推誠，離言深慷慨。","霜搖直指草，燭引明光珮。","公論日夕阻，朝廷磋跎會。","孤城海门月，万里流光带。","不應百尺松，空老鍾山靄。"]', '诗', 'shi', '', NULL, '宿灞上寄侍御璵弟 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9e083a1-454a-4c43-ba9e-d14f55b3b05c', '次汝中寄河南陳贊府', '次汝中寄河南陳贊府', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["汝山方聯延，伊水纔明滅。","遙見入楚雲，又此空館月。","紛然馳夢想，不謂遠離別。","京邑多歡娛，衡湘蹔沿越。","明湖春草遍，秋桂白花發。","豈惟長思君，日夕在魏闕。"]', '["汝山方聯延，伊水纔明滅。","遙见入楚云，又此空館月。","紛然驰梦想，不謂远離別。","京邑多歡娛，衡湘蹔沿越。","明湖春草遍，秋桂白花發。","豈惟长思君，日夕在魏闕。"]', '诗', 'shi', '', NULL, '次汝中寄河南陳贊府 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2fec465-cea1-4829-b12d-3ba37a267562', '同從弟銷南齋玩月憶山陰崔少府', '同從弟銷南斋玩月憶山陰崔少府', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["高臥南齋時，開帷月初吐。","清輝淡水木，演漾在窗戶。","苒苒幾盈虛，澄澄變今古。","美人清江畔，是夜越吟苦。","千里其如何，微風吹蘭杜。"]', '["高臥南斋时，开帷月初吐。","清輝淡水木，演漾在窗戶。","苒苒幾盈虛，澄澄变今古。","美人清江畔，是夜越吟苦。","千里其如何，微风吹蘭杜。"]', '诗', 'shi', '', NULL, '同從弟銷南齋玩月憶山陰崔少府 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5fdfac2-f74d-41d3-bcae-536c540185f2', '代扶風主人答', '代扶风主人答', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["殺氣凝不流，風悲日彩寒。","浮埃起四遠，遊子彌不歡。","依然宿扶風，沽酒聊自寬。","寸心亦未理，長鋏誰能彈。","主人就我飲，對我還慨歎。","便泣數行淚，因歌行路難。","十五役邊地，三回討樓蘭。","連年不解甲，積日無所餐。","將軍降匈奴，國使沒桑乾。","去時三十萬，獨自還長安。","不信沙場苦，君看刀箭瘢。","鄉親悉零落，冢墓亦摧殘。","仰攀青松枝，慟絕傷心肝。","禽獸悲不去，路傍誰忍看。","幸逢休明代，寰宇靜波瀾。","老馬思伏櫪，長鳴力已殫。","少年與運會，何事發悲端。","天子初封禪，賢良刷羽翰。","三邊悉如此，否泰亦須觀。"]', '["殺氣凝不流，风悲日彩寒。","浮埃起四远，游子彌不歡。","依然宿扶风，沽酒聊自寬。","寸心亦未理，长鋏誰能彈。","主人就我饮，对我還慨歎。","便泣數行泪，因歌行路难。","十五役邊地，三回討楼蘭。","連年不解甲，積日無所餐。","將軍降匈奴，国使沒桑乾。","去时三十万，独自還长安。","不信沙場苦，君看刀箭瘢。","乡親悉零落，冢墓亦摧殘。","仰攀青松枝，慟絕傷心肝。","禽獸悲不去，路傍誰忍看。","幸逢休明代，寰宇静波瀾。","老马思伏櫪，长鳴力已殫。","少年與運會，何事發悲端。","天子初封禪，賢良刷羽翰。","三邊悉如此，否泰亦須观。"]', '诗', 'shi', '', NULL, '代扶風主人答 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c8adce2-b817-4ee1-84ee-b9fd7c85c705', '酬鴻臚裴主簿雨後北樓見贈', '酬鴻臚裴主簿雨後北楼见贈', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["暮霞照新晴，歸雲猶相逐。","有懷晨昏暇，想見登眺目。","問禮侍彤襜，題詩訪茅屋。","高樓多古今，陳事滿陵谷。","地久微子封，臺餘孝王築。","裴回顧霄漢，豁達俯川陸。","遠水對孤城，長天向喬木。","公門何清靜，列戟森已肅。","不歎攜手稀，常思著鞭速。","終當拂羽翰，輕舉隨鴻鵠。"]', '["暮霞照新晴，归云猶相逐。","有懷晨昏暇，想见登眺目。","问禮侍彤襜，題诗訪茅屋。","高楼多古今，陳事满陵谷。","地久微子封，台餘孝王築。","裴回顧霄漢，豁達俯川陸。","远水对孤城，长天向喬木。","公门何清静，列戟森已肅。","不歎携手稀，常思著鞭速。","終當拂羽翰，轻舉隨鴻鵠。"]', '诗', 'shi', '', NULL, '酬鴻臚裴主簿雨後北樓見贈 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05a34af3-82f7-444f-8efc-b52e111e3b9c', '送任五之桂林', '送任五之桂林', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["楚客醉孤舟，越水將引棹。","山爲兩鄉別，月帶千里貌。","羇譴同繒綸，僻幽聞虎豹。","桂林寒色在，苦節知所效。"]', '["楚客醉孤舟，越水將引棹。","山爲兩乡別，月带千里貌。","羇譴同繒綸，僻幽闻虎豹。","桂林寒色在，苦節知所效。"]', '诗', 'shi', '', NULL, '送任五之桂林 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1d0f9ec-2d44-404b-bcbf-a58ced75163c', '山中別龐十', '山中別龐十', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["幽娟松篠徑，月出寒蟬鳴。","散髮臥其下，誰知孤隱情。","吟時白雲合，釣處玄潭清。","瓊樹方杳靄，鳳兮保其貞。"]', '["幽娟松篠徑，月出寒蟬鳴。","散髮臥其下，誰知孤隐情。","吟时白云合，釣处玄潭清。","瓊樹方杳靄，鳳兮保其貞。"]', '诗', 'shi', '', NULL, '山中別龐十 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d290d360-9e99-4762-ad6e-7d138c6f8f14', '留別伊闕張少府郭大都尉', '留別伊闕張少府郭大都尉', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["遷客就一醉，主人空金罍。","江湖青山底，欲去仍裴回。","郭侯未相識，策馬伊川來。","把手相勸勉，不應老塵埃。","孟陽逢山舊，仙館留清才。","日晚勸趣別，風長雲逐開。","幸隨板輿遠，負譴何憂哉。","唯有仗忠信，音書報雲雷。"]', '["遷客就一醉，主人空金罍。","江湖青山底，欲去仍裴回。","郭侯未相識，策马伊川来。","把手相勸勉，不應老塵埃。","孟陽逢山旧，仙館留清才。","日晚勸趣別，风长云逐开。","幸隨板輿远，負譴何憂哉。","唯有仗忠信，音书報云雷。"]', '诗', 'shi', '', NULL, '留別伊闕張少府郭大都尉 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad0dd3dc-9c4b-4e80-aee4-2f9d52a7b3e5', '送韋十二兵曹', '送韋十二兵曹', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["縣職如長纓，終日檢我身。","平明趨郡府，不得展故人。","故人念江湖，富貴如埃塵。","迹在戎府掾，心遊天台春。","獨立浦邊鶴，白雲長相親。","南風忽至吳，分散還入秦。","寒夜天光白，海淨月色真。","對坐論歲暮，絃悲豈無因。","平生馳驅分，非謂桮酒仁。","出處兩不合，忠貞何由伸。","看君孤舟去，且欲歌垂綸。"]', '["縣職如长纓，終日檢我身。","平明趨郡府，不得展故人。","故人念江湖，富貴如埃塵。","迹在戎府掾，心游天台春。","独立浦邊鹤，白云长相親。","南风忽至吳，分散還入秦。","寒夜天光白，海淨月色真。","对坐論歲暮，絃悲豈無因。","平生驰驱分，非謂桮酒仁。","出处兩不合，忠貞何由伸。","看君孤舟去，且欲歌垂綸。"]', '诗', 'shi', '', NULL, '送韋十二兵曹 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43e802aa-a927-4265-913c-71934873c8da', '東京府縣諸公與綦毋潛李頎相送至白馬寺宿', '东京府縣諸公與綦毋潛李頎相送至白马寺宿', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["鞍馬上東門，裴回入孤舟。","賢豪相追送，即櫂千里流。","赤岸落日在，空波微煙收。","薄宦忘機括，醉來即淹留。","月明見古寺，林外登高樓。","南風開長廊，夏夜如涼秋。","江月照吳縣，西歸夢中遊。"]', '["鞍马上东门，裴回入孤舟。","賢豪相追送，即櫂千里流。","赤岸落日在，空波微煙收。","薄宦忘機括，醉来即淹留。","月明见古寺，林外登高楼。","南风开长廊，夏夜如涼秋。","江月照吳縣，西归梦中游。"]', '诗', 'shi', '', NULL, '東京府縣諸公與綦毋潛李頎相送至白馬寺宿 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5c07ab4-d299-42a6-84c7-632a10972653', '送東林廉上人歸廬山', '送东林廉上人归廬山', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["石溪流已亂，苔徑人漸微。","日暮東林下，山僧還獨歸。","昔爲廬峰意，況與遠公違。","道性深寂寞，世情多是非。","會尋名山去，豈復望清輝。"]', '["石溪流已亂，苔徑人漸微。","日暮东林下，山僧還独归。","昔爲廬峰意，況與远公違。","道性深寂寞，世情多是非。","會尋名山去，豈复望清輝。"]', '诗', 'shi', '', NULL, '送東林廉上人歸廬山 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f964804f-ca79-4a0f-9848-59fb38ef25fe', '留別武陵袁丞', '留別武陵袁丞', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["皇恩暫遷謫，待罪逢知己。","從此武陵溪，孤舟二千里。","桃花遺古岸，金澗流春水。","誰識馬將軍，忠貞抱生死。"]', '["皇恩暫遷謫，待罪逢知己。","從此武陵溪，孤舟二千里。","桃花遺古岸，金澗流春水。","誰識马將軍，忠貞抱生死。"]', '诗', 'shi', '', NULL, '留別武陵袁丞 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b11d2370-bbb9-4b88-a7be-8ccffa020353', '別劉諝', '別劉諝', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["天地寒更雨，蒼茫楚城陰。","一尊廣陵酒，十載衡陽心。","倚仗不可料，悲歡豈易尋。","相逢成遠別，後會何如今。","身在江海上，雲連京國深。","行當務功業，策馬何駸駸。"]', '["天地寒更雨，蒼茫楚城陰。","一尊廣陵酒，十載衡陽心。","倚仗不可料，悲歡豈易尋。","相逢成远別，後會何如今。","身在江海上，云連京国深。","行當務功業，策马何駸駸。"]', '诗', 'shi', '', NULL, '別劉諝 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b160db2-46d2-46ad-8770-f69b92f0f5d9', '岳陽別李十七越賓', '岳陽別李十七越賓', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["相逢楚水寒，舟在洞庭驛。","具陳江波事，不異淪棄跡。","杉上秋雨聲，悲切蒹葭夕。","彈琴收餘響，來送千里客。","平明孤帆心，歲晚濟代策。","時在身未充，瀟湘不盈畫。","湖小洲渚聯，澹淡煙景碧。","魚鱉自有性，龜龍無能易。","譴黜同所安，風土任所適。","閉門觀玄化，攜手遺損益。"]', '["相逢楚水寒，舟在洞庭驛。","具陳江波事，不異淪棄跡。","杉上秋雨声，悲切蒹葭夕。","彈琴收餘响，来送千里客。","平明孤帆心，歲晚濟代策。","时在身未充，瀟湘不盈畫。","湖小洲渚聯，澹淡煙景碧。","鱼鱉自有性，龟龙無能易。","譴黜同所安，风土任所適。","閉门观玄化，携手遺損益。"]', '诗', 'shi', '', NULL, '岳陽別李十七越賓 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('419db4f0-72c6-4a05-aa1f-d5865f9cea66', '留別岑參兄弟', '留別岑參兄弟', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["江城建業樓，山盡滄海頭。","副職守茲縣，東南櫂孤舟。","長安故人宅，秣馬經前秋。","便以風雪暮，還爲縱飲留。","貂蟬七葉貴，鴻鵠萬里遊。","何必念鐘鼎，所在烹肥牛。","爲君嘯一曲，且莫彈箜篌。","徒見枯者豔，誰言直如鉤。","岑家雙瓊樹，騰光難爲儔。","誰言青門悲，俯期吳山幽。","日西石門嶠，月吐金陵洲。","追隨探靈怪，豈不驕王侯。"]', '["江城建業楼，山尽滄海头。","副職守茲縣，东南櫂孤舟。","长安故人宅，秣马經前秋。","便以风雪暮，還爲縱饮留。","貂蟬七葉貴，鴻鵠万里游。","何必念鐘鼎，所在烹肥牛。","爲君嘯一曲，且莫彈箜篌。","徒见枯者豔，誰言直如鉤。","岑家雙瓊樹，腾光难爲儔。","誰言青门悲，俯期吳山幽。","日西石门嶠，月吐金陵洲。","追隨探靈怪，豈不驕王侯。"]', '诗', 'shi', '', NULL, '留別岑參兄弟 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d6dee47-6ddd-441f-b9d8-6db3ebad15ce', '送劉眘虛歸取宏詞解', '送劉眘虛归取宏词解', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["太清聞海鶴，遊子引鄉眄。","聲隨羽儀遠，勢與歸雲便。","青桂春再榮，白雲暮來變。","遷飛在禮儀，豈復淚如霰。"]', '["太清闻海鹤，游子引乡眄。","声隨羽儀远，勢與归云便。","青桂春再榮，白云暮来变。","遷飞在禮儀，豈复泪如霰。"]', '诗', 'shi', '', NULL, '送劉眘虛歸取宏詞解 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef29aec7-ca2f-4211-a43f-0c8f911b4a40', '巴陵別劉處士', '巴陵別劉处士', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["劉生隱岳陽，心遠洞庭水。","偃帆入山郭，一宿楚雲裏。","竹映秋館深，月寒江風起。","煙波桂陽接，日夕數千里。","嫋嫋清夜猿，孤舟坐如此。","湘中有來鴈，雨雪候音旨。"]', '["劉生隐岳陽，心远洞庭水。","偃帆入山郭，一宿楚云裏。","竹映秋館深，月寒江风起。","煙波桂陽接，日夕數千里。","嫋嫋清夜猿，孤舟坐如此。","湘中有来鴈，雨雪候音旨。"]', '诗', 'shi', '', NULL, '巴陵別劉處士 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b33dda30-2f9e-4737-9b72-c46bca256ae7', '宿裴氏山莊', '宿裴氏山莊', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["蒼蒼竹林暮，吾亦知所投。","靜坐山齋月，清溪聞遠流。","西峰下微雨，向曉白雲收。","遂解塵中組，終南春可遊。"]', '["蒼蒼竹林暮，吾亦知所投。","静坐山斋月，清溪闻远流。","西峰下微雨，向晓白云收。","遂解塵中組，終南春可游。"]', '诗', 'shi', '', NULL, '宿裴氏山莊 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04814106-730a-460e-8fb8-4fc831c69c19', '淇上酬薛據兼寄郭微', '淇上酬薛據兼寄郭微', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["自從別京華，我心乃蕭索。","十年守章句，萬里空寥落。","北上登薊門，茫茫見沙漠。","倚劒對風塵，慨然思衞霍。","拂衣去燕趙，驅馬悵不樂。","天長滄洲路，日暮邯鄲郭。","酒肆或淹留，漁澤屢棲泊。","獨行備艱難，孰辭千鼎鑊。","皇情念淳古，時俗何浮薄。","理道須任賢，安人在求瘼。","故交負奇才，逸氣包謇諤。","隱軫經濟策，縱橫建安作。","才望忽先鳴，風期無宿諾。","飄颻勞州縣，迢遞限言謔。","東馳眇貝丘，西顧彌虢略。","淇水徒自深，浮雲不堪託。","吾謀適可用，天道豈遼廓。","不然買山田，一身與耕鑿。"]', '["自從別京华，我心乃蕭索。","十年守章句，万里空寥落。","北上登薊门，茫茫见沙漠。","倚劒对风塵，慨然思衞霍。","拂衣去燕趙，驱马悵不乐。","天长滄洲路，日暮邯鄲郭。","酒肆或淹留，漁澤屢棲泊。","独行備艱难，孰辞千鼎鑊。","皇情念淳古，时俗何浮薄。","理道須任賢，安人在求瘼。","故交負奇才，逸氣包謇諤。","隐軫經濟策，縱橫建安作。","才望忽先鳴，风期無宿諾。","飄颻勞州縣，迢遞限言謔。","东驰眇貝丘，西顧彌虢略。","淇水徒自深，浮云不堪託。","吾謀適可用，天道豈遼廓。","不然買山田，一身與耕鑿。"]', '诗', 'shi', '', NULL, '淇上酬薛據兼寄郭微 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23ac0351-1020-42fc-bdc8-bfef10d6884d', '詠史', '詠史', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["荷畚至洛陽，杖策遊北門。","天下盡兵甲，豺狼滿中原。","明夷方遘患，顧我徒崩犇。","自慙菲薄才，誤蒙國士恩。","位重任亦重，時危志彌敦。","西北未及終，東南不可吞。","進則耻保躬，退乃爲觸藩。","歎息嵩山老，而後知其尊。"]', '["荷畚至洛陽，杖策游北门。","天下尽兵甲，豺狼满中原。","明夷方遘患，顧我徒崩犇。","自慙菲薄才，誤蒙国士恩。","位重任亦重，时危志彌敦。","西北未及終，东南不可吞。","進則耻保躬，退乃爲觸藩。","歎息嵩山老，而後知其尊。"]', '诗', 'shi', '', NULL, '詠史 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1239be59-986f-4e78-bf47-05890b138c78', '雜興', '杂兴', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["握中銅匕首，粉剉楚山鐵。","義士頻報讎，殺人不曾缺。","可悲燕丹事，終被狼虎滅。","一舉無兩全，荆軻遂爲血。","誠知匹夫勇，何取萬人傑。","無道吞諸侯，坐見九州裂。"]', '["握中銅匕首，粉剉楚山鐵。","義士頻報讎，殺人不曾缺。","可悲燕丹事，終被狼虎滅。","一舉無兩全，荆軻遂爲血。","誠知匹夫勇，何取万人傑。","無道吞諸侯，坐见九州裂。"]', '诗', 'shi', '', NULL, '雜興 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57a79dc1-1257-4ed3-a9ed-73dc32a3b9f2', '秋興', '秋兴', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["日暮西北堂，涼風洗脩木。","著書在南窗，門館常肅肅。","苔草延古意，視聽轉幽獨。","或問余所營，刈黍就寒谷。"]', '["日暮西北堂，涼风洗脩木。","著书在南窗，门館常肅肅。","苔草延古意，視听轉幽独。","或问余所營，刈黍就寒谷。"]', '诗', 'shi', '', NULL, '秋興 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6a5ec30-5c21-45b2-948d-19a9fd188b08', '齋心', '斋心', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["女蘿覆石壁，溪水幽濛朧。","紫葛蔓黃花，娟娟寒露中。","朝飲花上露，夜臥松下風。","雲英化爲水，光采與我同。","日月蕩精魄，寥寥天宇空。"]', '["女蘿覆石壁，溪水幽濛朧。","紫葛蔓黄花，娟娟寒露中。","朝饮花上露，夜臥松下风。","云英化爲水，光采與我同。","日月蕩精魄，寥寥天宇空。"]', '诗', 'shi', '', NULL, '齋心 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6769d8dd-8a90-4329-8745-1cb2913e2c6b', '獨遊', '独游', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["林臥情每閒，獨遊景常晏。","時從灞陵下，垂釣往南澗。","手攜雙鯉魚，目送千里鴈。","悟彼飛有適，知此罹憂患。","放之清冷泉，因得省疎慢。","永懷青岑客，廻首白雲間。","神超物無違，豈繫名與宦。"]', '["林臥情每閒，独游景常晏。","时從灞陵下，垂釣往南澗。","手携雙鯉鱼，目送千里鴈。","悟彼飞有適，知此罹憂患。","放之清冷泉，因得省疎慢。","永懷青岑客，廻首白云间。","神超物無違，豈繫名與宦。"]', '诗', 'shi', '', NULL, '獨遊 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90d156d0-52f7-4ad1-b2ee-cc00e8c71d0c', '香積寺禮拜萬廻平等二聖僧塔', '香積寺禮拜万廻平等二聖僧塔', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["真無御化來，借有乘化歸。","如彼雙塔內，孰能知是非。","愚也駭蒼生，聖哉爲帝師。","當爲時世出，不由天地資。","萬廻主此方，平等性無違。","今我一禮心，億劫同不移。","肅肅松柏下，諸天來有時。"]', '["真無御化来，借有乘化归。","如彼雙塔內，孰能知是非。","愚也駭蒼生，聖哉爲帝師。","當爲时世出，不由天地資。","万廻主此方，平等性無違。","今我一禮心，億劫同不移。","肅肅松柏下，諸天来有时。"]', '诗', 'shi', '', NULL, '香積寺禮拜萬廻平等二聖僧塔 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0667b06-7bbd-4535-bd82-674f80de66e8', '就道士問周易參同契', '就道士问周易參同契', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["仙人騎白鹿，髮短耳何長。","時余采菖蒲，忽見嵩之陽。","稽首求丹經，乃出懷中方。","披讀了不悟，歸來問嵇康。","嗟余無道骨，發我入太行。"]', '["仙人騎白鹿，髮短耳何长。","时余采菖蒲，忽见嵩之陽。","稽首求丹經，乃出懷中方。","披读了不悟，归来问嵇康。","嗟余無道骨，發我入太行。"]', '诗', 'shi', '', NULL, '就道士問周易參同契 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c707d94-cd1d-4d2c-9e43-f01c4c833bf5', '諸官遊招隱寺', '諸官游招隐寺', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["山館人已空，青蘿換風雨。","自從永明世，月向龍宮吐。","鑿井長幽泉，白雲今如古。","應真坐松柏，錫杖挂窗戶。","口云七十餘，能救諸有苦。","回指巖樹花，如聞道場鼓。","金色身壤滅，真如性無主。","僚友同一心，清光遣誰取。"]', '["山館人已空，青蘿換风雨。","自從永明世，月向龙宮吐。","鑿井长幽泉，白云今如古。","應真坐松柏，錫杖挂窗戶。","口云七十餘，能救諸有苦。","回指巖樹花，如闻道場鼓。","金色身壤滅，真如性無主。","僚友同一心，清光遣誰取。"]', '诗', 'shi', '', NULL, '諸官遊招隱寺 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a278c8c6-278f-4915-a5be-445f4510fcfc', '宴南亭', '宴南亭', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["寒江暎村林，亭上納鮮潔。","楚客共閑飲，靜坐金管闋。","酣竟日入山，暝來雲歸穴。","城樓空杳靄，猿鳥備清切。","物狀如絲綸，上心爲予決。","訪君東溪事，早晚樵路絕。"]', '["寒江暎村林，亭上納鲜潔。","楚客共闲饮，静坐金管闋。","酣竟日入山，暝来云归穴。","城楼空杳靄，猿鸟備清切。","物狀如絲綸，上心爲予決。","訪君东溪事，早晚樵路絕。"]', '诗', 'shi', '', NULL, '宴南亭 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2baab2c0-0277-404b-b393-f2ded40154e9', '何九於客舍集', '何九於客舍集', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["客有住桂陽，亦如巢林鳥。","罍觴且終宴，功業曾未了。","山月空霽時，江明高樓曉。","門前泊舟檝，行次入松篠。","此意投贈君，滄波風褭褭。"]', '["客有住桂陽，亦如巢林鸟。","罍觴且終宴，功業曾未了。","山月空霽时，江明高楼晓。","门前泊舟檝，行次入松篠。","此意投贈君，滄波风褭褭。"]', '诗', 'shi', '', NULL, '何九於客舍集 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c91fabc9-f344-41bb-8737-233d0063b9f3', '洛陽尉劉晏與府掾諸公茶集天宮寺岸道上人房', '洛陽尉劉晏與府掾諸公茶集天宮寺岸道上人房', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["良友呼我宿，月明懸天宮。","道安風塵外，灑掃青林中。","削去府縣理，豁然神機空。","自從三湘還，始得今夕同。","舊居太行北，遠宦滄溟東。","各有四方事，白雲處處通。"]', '["良友呼我宿，月明懸天宮。","道安风塵外，灑掃青林中。","削去府縣理，豁然神機空。","自從三湘還，始得今夕同。","旧居太行北，远宦滄溟东。","各有四方事，白云处处通。"]', '诗', 'shi', '', NULL, '洛陽尉劉晏與府掾諸公茶集天宮寺岸道上人房 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('282a0ad4-b2d4-466d-af04-cdda44a7a75d', '觀江淮名勝圖', '观江淮名勝圖', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["刻意吟雲山，尤知隱淪妙。","遠公何爲者，再詣臨海嶠。","而我高其風，披圖得遺照。","援毫無逃境，遂展千里眺。","淡掃荆門煙，明標赤城燒。","青葱林間嶺，隱見淮海徼。","但指香爐頂，無聞白猿嘯。","沙門既云滅，獨往豈殊調。","感對懷拂衣，胡寧事漁釣。","安期始遺舃，千古謝榮耀。","投跡庶可齊，滄浪有孤棹。"]', '["刻意吟云山，尤知隐淪妙。","远公何爲者，再詣臨海嶠。","而我高其风，披圖得遺照。","援毫無逃境，遂展千里眺。","淡掃荆门煙，明標赤城燒。","青葱林间嶺，隐见淮海徼。","但指香爐頂，無闻白猿嘯。","沙门既云滅，独往豈殊調。","感对懷拂衣，胡寧事漁釣。","安期始遺舃，千古謝榮耀。","投跡庶可齊，滄浪有孤棹。"]', '诗', 'shi', '', NULL, '觀江淮名勝圖 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2e47b92-21d8-42c9-ba84-3812c4f83be9', '灞上閒居', '灞上閒居', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["鴻都有歸客，偃臥滋陽村。","軒冕無枉顧，清川照我門。","空林網夕陽，寒鳥赴荒園。","廓落時得意，懷哉莫與言。","庭前有孤鶴，欲啄常翩翻。","爲我銜素書，弔彼顏與原。","二君既不朽，所以慰其魂。"]', '["鴻都有归客，偃臥滋陽村。","軒冕無枉顧，清川照我门。","空林網夕陽，寒鸟赴荒园。","廓落时得意，懷哉莫與言。","庭前有孤鹤，欲啄常翩翻。","爲我銜素书，弔彼顏與原。","二君既不朽，所以慰其魂。"]', '诗', 'shi', '', NULL, '灞上閒居 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9385e47f-e958-4a76-8886-fe62c5fa353a', '風涼原上作', '风涼原上作', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["陰岑宿雲歸，烟霧濕松柏。","風淒日初曉，下嶺望川澤。","遠山無晦明，秋水千里白。","佳氣盤未央，聖人在凝碧。","關門阻天下，信是帝王宅。","海內方晏然，廟堂有奇策。","時貞守全運，罷去遊說客。","予忝蘭臺人，幽尋免貽責。"]', '["陰岑宿云归，烟霧濕松柏。","风淒日初晓，下嶺望川澤。","远山無晦明，秋水千里白。","佳氣盤未央，聖人在凝碧。","关门阻天下，信是帝王宅。","海內方晏然，廟堂有奇策。","时貞守全運，罷去游说客。","予忝蘭台人，幽尋免貽責。"]', '诗', 'shi', '', NULL, '風涼原上作 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00fc6fd0-df00-4284-8c21-b5428b3fbfe3', '裴六書堂', '裴六书堂', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["閑堂閉空陰，竹林但清響。","窗下長嘯客，區中無遺想。","經綸精微言，兼濟當獨往。"]', '["闲堂閉空陰，竹林但清响。","窗下长嘯客，區中無遺想。","經綸精微言，兼濟當独往。"]', '诗', 'shi', '', NULL, '裴六書堂 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8cfc3c2-8ee8-414b-bc14-ca88cbc074d9', '江上聞笛', '江上闻笛', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["橫笛怨江月，扁舟何處尋。","聲長楚山外，曲繞胡關深。","相去萬餘里，遙傳此夜心。","寥寥浦漵寒，響盡惟幽林。","不知誰家子，復奏邯鄲音。","水客皆擁棹，空霜遂盈襟。","羸馬望北走，遷人悲越吟。","何當邊草白，旌節隴城陰。"]', '["橫笛怨江月，扁舟何处尋。","声长楚山外，曲繞胡关深。","相去万餘里，遙傳此夜心。","寥寥浦漵寒，响尽惟幽林。","不知誰家子，复奏邯鄲音。","水客皆擁棹，空霜遂盈襟。","羸马望北走，遷人悲越吟。","何當邊草白，旌節隴城陰。"]', '诗', 'shi', '', NULL, '江上聞笛 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b44bc27-50b9-4144-be84-410f7941e8e6', '太湖秋夕', '太湖秋夕', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["水宿煙雨寒，洞庭霜落微。","月明移舟去，夜靜魂夢歸。","暗覺海風度，蕭蕭聞鴈飛。"]', '["水宿煙雨寒，洞庭霜落微。","月明移舟去，夜静魂梦归。","暗覺海风度，蕭蕭闻鴈飞。"]', '诗', 'shi', '', NULL, '太湖秋夕 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a529e61e-b9c4-4457-b11f-e1a8adb0dc3e', '趙十四兄見訪', '趙十四兄见訪', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["客來舒長簟，開閤延清風。","但有無絃琴，共君盡尊中。","晚來常讀易，頃者欲還嵩。","世事何須道，黃精且養蒙。","嵇康殊寡識，張翰獨知終。","忽憶鱸魚鱠，扁舟往江東。"]', '["客来舒长簟，开閤延清风。","但有無絃琴，共君尽尊中。","晚来常读易，頃者欲還嵩。","世事何須道，黄精且養蒙。","嵇康殊寡識，張翰独知終。","忽憶鱸鱼鱠，扁舟往江东。"]', '诗', 'shi', '', NULL, '趙十四兄見訪 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60afe2ef-0e28-4455-bac8-24aa00cd1a74', '過華陰', '過华陰', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["雲起太華山，雲山互明滅。","東峯始含景，了了見松雪。","羇人感幽棲，窅暎轉奇絕。","欣然忘所疲，永望吟不輟。","信宿百餘里，出關玩新月。","何意昨來心，遇物遂遷別。","人生屢如此，何以肆愉悅。"]', '["云起太华山，云山互明滅。","东峯始含景，了了见松雪。","羇人感幽棲，窅暎轉奇絕。","欣然忘所疲，永望吟不輟。","信宿百餘里，出关玩新月。","何意昨来心，遇物遂遷別。","人生屢如此，何以肆愉悅。"]', '诗', 'shi', '', NULL, '過華陰 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e928c12-d3b1-4840-8867-576663f81d93', '九江口作', '九江口作', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["漭漭江勢闊，雨開潯陽秋。","驛門是高岸，望盡黃蘆洲。","水與五谿合，心期萬里遊。","明時無棄才，謫去隨孤舟。","鷙鳥立寒木，丈夫佩吳鉤。","何當報君恩，却繫單于頭。"]', '["漭漭江勢闊，雨开潯陽秋。","驛门是高岸，望尽黄蘆洲。","水與五谿合，心期万里游。","明时無棄才，謫去隨孤舟。","鷙鸟立寒木，丈夫佩吳鉤。","何當報君恩，却繫單于头。"]', '诗', 'shi', '', NULL, '九江口作 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d460a10d-224c-41e0-9665-a35da5b44b74', '大梁途中作', '大梁途中作', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["怏怏步長道，客行渺無端。","郊原欲下雪，天地稜稜寒。","當時每酣醉，不覺行路難。","今日無酒錢，悽惶向誰歎。"]', '["怏怏步长道，客行渺無端。","郊原欲下雪，天地稜稜寒。","當时每酣醉，不覺行路难。","今日無酒錢，悽惶向誰歎。"]', '诗', 'shi', '', NULL, '大梁途中作 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('855dcf8e-3e27-4525-8560-7d6d8d0e87f8', '途中作', '途中作', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["遊人愁歲晏，早起遵王畿。","墜葉吹未曉，疎林月微微。","驚禽棲不定，寒獸相因依。","歎此霜露下，復聞鴻雁飛。","渺然江南意，惜與中途違。","羇旅悲壯髮，別離念征衣。","永圖豈勞止，明節期所歸。","寧厭楚山曲，無人長掩扉。"]', '["游人愁歲晏，早起遵王畿。","墜葉吹未晓，疎林月微微。","驚禽棲不定，寒獸相因依。","歎此霜露下，复闻鴻雁飞。","渺然江南意，惜與中途違。","羇旅悲壯髮，別離念征衣。","永圖豈勞止，明節期所归。","寧厭楚山曲，無人长掩扉。"]', '诗', 'shi', '', NULL, '途中作 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed95661a-f947-4d65-a60e-3bd852c3e8b5', '山行入涇州', '山行入涇州', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["倦此山路長，停驂問賓御。","林巒信回惑，白日落何處。","徙倚望長風，滔滔引歸慮。","微雨隨雲收，濛濛傍山去。","西臨有邊邑，北走盡亭戍。","涇水橫白烟，州城隱寒樹。","所嗟異風俗，已自少情趣。","豈伊懷土多，觸目忻所遇。"]', '["倦此山路长，停驂问賓御。","林巒信回惑，白日落何处。","徙倚望长风，滔滔引归慮。","微雨隨云收，濛濛傍山去。","西臨有邊邑，北走尽亭戍。","涇水橫白烟，州城隐寒樹。","所嗟異风俗，已自少情趣。","豈伊懷土多，觸目忻所遇。"]', '诗', 'shi', '', NULL, '山行入涇州 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f9ae5aa-5395-44d6-ae8a-17ea0d9b686f', '小敷谷龍潭祠作', '小敷谷龙潭祠作', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["崖谷歕疾流，地中有雷集。","百泉勢相蕩，巨石皆却立。","跳波沸崢嶸，深處不可挹。","昏爲蛟龍怒，清見雲雨入。","靈怪祟偏祠，廢興自茲邑。","沈淫頃多昧，檐宇遂不葺。","吾聞被明典，盛德惟世及。","生人載山川，血食報原隰。","豈伊駭微險，將以循甿揖。","口飛振呂梁，忠信亦我習。","波流浸已廣，悔吝在所汲。","谿水有清源，褰裳靡沾濕。"]', '["崖谷歕疾流，地中有雷集。","百泉勢相蕩，巨石皆却立。","跳波沸崢嶸，深处不可挹。","昏爲蛟龙怒，清见云雨入。","靈怪祟偏祠，廢兴自茲邑。","沈淫頃多昧，檐宇遂不葺。","吾闻被明典，盛德惟世及。","生人載山川，血食報原隰。","豈伊駭微險，將以循甿揖。","口飞振呂梁，忠信亦我習。","波流浸已廣，悔吝在所汲。","谿水有清源，褰裳靡沾濕。"]', '诗', 'shi', '', NULL, '小敷谷龍潭祠作 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ad65b95-a0ca-4c3e-8e61-5c30f3982fcb', '段宥廰孤桐', '段宥廰孤桐', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["鳳皇所宿處，月暎孤桐寒。","槁葉零落盡，空柯蒼翠殘。","虛心誰能見，直影非無端。","響發調尚苦，清商勞一彈。"]', '["鳳皇所宿处，月暎孤桐寒。","槁葉零落尽，空柯蒼翠殘。","虛心誰能见，直影非無端。","响發調尚苦，清商勞一彈。"]', '诗', 'shi', '', NULL, '段宥廰孤桐 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d96acefe-8efc-46bc-b85e-6e4ad42098f9', '琴', '琴', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["孤桐秘虛鳴，樸素傳幽真。","髣髴絃指外，遂見初古人。","意遠風雪苦，時來江山春。","高宴未終曲，誰能辨經綸。"]', '["孤桐秘虛鳴，樸素傳幽真。","髣髴絃指外，遂见初古人。","意远风雪苦，时来江山春。","高宴未終曲，誰能辨經綸。"]', '诗', 'shi', '', NULL, '琴 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ffb7a6f-2fa1-4d50-bd51-830cede927b1', '初日', '初日', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["初日淨金閨，先照牀前暖。","斜光入羅幕，稍稍親絲管。","雲髮不能梳，楊花更吹滿。"]', '["初日淨金閨，先照牀前暖。","斜光入羅幕，稍稍親絲管。","云髮不能梳，楊花更吹满。"]', '诗', 'shi', '', NULL, '初日 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('635319ce-1936-4ca2-8eff-6d074e7f23b3', '失題', '失題', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["姦雄乃得志，遂使羣心搖。","赤風蕩中原，烈火無遺巢。","一人計不用，萬里空蕭條。"]', '["姦雄乃得志，遂使羣心搖。","赤风蕩中原，烈火無遺巢。","一人計不用，万里空蕭條。"]', '诗', 'shi', '', NULL, '失題 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69419d0e-57f6-415c-a9dc-3af999ba4af1', '贈宇文中丞', '贈宇文中丞', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["僕本濩落人，辱當州郡使。","量力頗及早，謝歸今即已。","蕭蕭若凌虛，衿帶頃消靡。","車服卒然來，涔陽作遊子。","鬱鬱寡開顏，默默獨行李。","忽逢平生友，一笑方在此。","秋清寧風日，楚思浩雲水。","爲語弋林者，冥冥鴻遠矣。"]', '["僕本濩落人，辱當州郡使。","量力頗及早，謝归今即已。","蕭蕭若凌虛，衿带頃消靡。","车服卒然来，涔陽作游子。","鬱鬱寡开顏，默默独行李。","忽逢平生友，一笑方在此。","秋清寧风日，楚思浩云水。","爲語弋林者，冥冥鴻远矣。"]', '诗', 'shi', '', NULL, '贈宇文中丞 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3e4a490-0aea-4eae-84c7-9698ae1ae112', '箜篌引', '箜篌引', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["盧谿郡南夜泊舟，夜聞兩岸羌戎謳。","其時月黑猿啾啾，微雨霑衣令人愁。","有一遷客登高樓，不言不寐彈箜篌。","彈作薊門桑葉秋，風沙颯颯青冢頭。","將軍鐵驄汗血流，深入匈奴戰未休。","黃旗一點兵馬收，亂殺胡人積如丘。","瘡病驅來配邊州，仍披漠北羔羊裘。","顏色飢枯掩面羞，眼眶淚滴深兩眸。","思還本鄉食犛牛，欲語不得指咽喉。","或有強壯能吚嚘，意說被他邊將讎。","五世屬藩漢主留，碧毛氈帳河曲遊。","橐駞五萬部落稠，勅賜飛鳳金兜鍪。","爲君百戰如過籌，靜掃陰山無鳥投。","家藏鐵券特承優，黃金千斤不稱求。","九族分離作楚囚，深谿寂寞絃苦幽。","草木悲感聲颼飀，僕本東山爲國憂。","明光殿前論九疇，簏讀兵書盡冥搜。","爲君掌上施權謀，洞曉山川無與儔。","紫宸詔發遠懷柔，搖筆飛霜如奪鉤。","鬼神不得知其由，憐愛蒼生比蚍蜉。","朔河屯兵須漸抽，盡遣降來拜御溝。"]', '["盧谿郡南夜泊舟，夜闻兩岸羌戎謳。","其时月黑猿啾啾，微雨霑衣令人愁。","有一遷客登高楼，不言不寐彈箜篌。","彈作薊门桑葉秋，风沙颯颯青冢头。","將軍鐵驄汗血流，深入匈奴戰未休。","黄旗一点兵马收，亂殺胡人積如丘。","瘡病驱来配邊州，仍披漠北羔羊裘。","顏色飢枯掩面羞，眼眶泪滴深兩眸。","思還本乡食犛牛，欲語不得指咽喉。","或有強壯能吚嚘，意说被他邊將讎。","五世屬藩漢主留，碧毛氈帳河曲游。","橐駞五万部落稠，勅賜飞鳳金兜鍪。","爲君百戰如過籌，静掃陰山無鸟投。","家藏鐵券特承優，黄金千斤不稱求。","九族分離作楚囚，深谿寂寞絃苦幽。","草木悲感声颼飀，僕本东山爲国憂。","明光殿前論九疇，簏读兵书尽冥搜。","爲君掌上施權謀，洞晓山川無與儔。","紫宸詔發远懷柔，搖笔飞霜如奪鉤。","鬼神不得知其由，怜愛蒼生比蚍蜉。","朔河屯兵須漸抽，尽遣降来拜御溝。"]', '诗', 'shi', '', NULL, '箜篌引 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2c9541f-6f63-4982-9b55-a1db3d69074c', '烏棲曲', '烏棲曲', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["白馬逐朱車，黃昏入狹邪。","柳樹烏爭宿，爭枝未得飛上屋。","東房少婦壻從軍，每聽烏啼知夜分。"]', '["白马逐朱车，黄昏入狹邪。","柳樹烏爭宿，爭枝未得飞上屋。","东房少婦壻從軍，每听烏啼知夜分。"]', '诗', 'shi', '', NULL, '烏棲曲 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9aeead3-57a1-45a0-a5bc-11c95f29d912', '城傍曲', '城傍曲', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["秋風鳴桑條，草白狐兔驕。","邯鄲飲來酒未消，城北原平掣皂鵰。","射殺空營兩騰虎，廻身却月佩弓弰。"]', '["秋风鳴桑條，草白狐兔驕。","邯鄲饮来酒未消，城北原平掣皂鵰。","射殺空營兩腾虎，廻身却月佩弓弰。"]', '诗', 'shi', '', NULL, '城傍曲 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a64d7ec-1335-4ce5-b62c-32df33b30023', '行路難', '行路难', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["雙絲作綆繫銀瓶，百尺寒泉轆轤上。","懸絲一絕不可望，似妾傾心在君掌。","人生意氣好遷捐，只重狂花不重賢。","宴罷調箏奏離鶴，廻嬌轉盼泣君前。","君不見眼前事，豈保須臾心勿異。","西山日下雨足稀，側有浮雲無所寄。","但願莫忘前者言，剉骨黃塵亦無愧。","行路難，勸君酒，莫辭煩，美酒千鍾猶可盡，心中片愧何可論。","一聞漢主思故劍，使妾長嗟萬古魂。"]', '["雙絲作綆繫銀瓶，百尺寒泉轆轤上。","懸絲一絕不可望，似妾傾心在君掌。","人生意氣好遷捐，只重狂花不重賢。","宴罷調箏奏離鹤，廻嬌轉盼泣君前。","君不见眼前事，豈保須臾心勿異。","西山日下雨足稀，側有浮云無所寄。","但願莫忘前者言，剉骨黄塵亦無愧。","行路难，勸君酒，莫辞煩，美酒千鍾猶可尽，心中片愧何可論。","一闻漢主思故劍，使妾长嗟万古魂。"]', '诗', 'shi', '', NULL, '行路難 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a434b036-2f84-4c96-9c2c-69220136bc26', '奉贈張荆州', '奉贈張荆州', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["祝融之峯紫雲銜，翠如何其雪嶄嵓。","邑西有路緣石壁，我欲從之臥穹嵌。","魚有心兮脫網罟，江無人兮鳴楓杉。","王君飛舄仍未去，蘇耽宅中意遙緘。"]', '["祝融之峯紫云銜，翠如何其雪嶄嵓。","邑西有路緣石壁，我欲從之臥穹嵌。","鱼有心兮脫網罟，江無人兮鳴楓杉。","王君飞舄仍未去，蘇耽宅中意遙緘。"]', '诗', 'shi', '', NULL, '奉贈張荆州 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4fa2499-efbe-4dbe-923e-595d1287d1f7', '駕出長安', '駕出长安', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["聖德超千古，皇風扇九圍。","天廻萬象出，駕動六龍飛。","淑氣來黃道，祥雲覆紫微。","太平多扈從，文物有光輝。"]', '["聖德超千古，皇风扇九圍。","天廻万象出，駕动六龙飞。","淑氣来黄道，祥云覆紫微。","太平多扈從，文物有光輝。"]', '诗', 'shi', '', NULL, '駕出長安 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6330cca9-54a6-4827-a2c1-de8220f9c496', '駕幸河東', '駕幸河东', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["晉水千廬合，汾橋萬國從。","開唐天業盛，入沛聖恩濃。","下輦廻三象，題碑任六龍。","睿明懸日月，千歲此時逢。"]', '["晉水千廬合，汾橋万国從。","开唐天業盛，入沛聖恩濃。","下輦廻三象，題碑任六龙。","睿明懸日月，千歲此时逢。"]', '诗', 'shi', '', NULL, '駕幸河東 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81f5afd8-0601-4111-a7cb-5d51c7e3ce1e', '胡笳曲', '胡笳曲', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["城南虜已合，一夜幾重圍。","自有金笳引，能霑出塞衣。","聽臨關月苦，清入海風微。","三奏高樓曉，胡人掩涕歸。"]', '["城南虜已合，一夜幾重圍。","自有金笳引，能霑出塞衣。","听臨关月苦，清入海风微。","三奏高楼晓，胡人掩涕归。"]', '诗', 'shi', '', NULL, '胡笳曲 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe4f6fe3-9d6e-4cc3-8b19-519690162ee1', '潞府客亭寄崔鳳童', '潞府客亭寄崔鳳童', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["蕭條郡城閉，旅館空寒烟。","秋月對愁客，山鐘搖暮天。","新知偶相訪，斗酒情依然。","一宿阻長會，清風徒滿川。"]', '["蕭條郡城閉，旅館空寒烟。","秋月对愁客，山鐘搖暮天。","新知偶相訪，斗酒情依然。","一宿阻长會，清风徒满川。"]', '诗', 'shi', '', NULL, '潞府客亭寄崔鳳童 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3f81284-82d4-45a4-a5b7-1459a14ee51f', '和振上人秋夜懷士會', '和振上人秋夜懷士會', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["白露傷草木，山風吹夜寒。","遙林夢親友，高興發雲端。","郭外秋聲急，城邊月色殘。","瑤琴多遠思，更爲客中彈。"]', '["白露傷草木，山风吹夜寒。","遙林梦親友，高兴發云端。","郭外秋声急，城邊月色殘。","瑤琴多远思，更爲客中彈。"]', '诗', 'shi', '', NULL, '和振上人秋夜懷士會 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b3591a3-51fc-40fa-aff4-58931f659018', '送李擢遊江東', '送李擢游江东', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["清洛日夜漲，微風引孤舟。","離腸便千里，遠夢生江樓。","楚國橙橘暗，吳門煙雨愁。","東南具今古，歸望山雲秋。"]', '["清洛日夜漲，微风引孤舟。","離腸便千里，远梦生江楼。","楚国橙橘暗，吳门煙雨愁。","东南具今古，归望山云秋。"]', '诗', 'shi', '', NULL, '送李擢遊江東 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e367588d-d1a1-4835-81ca-93e11c86b416', '沙苑南渡頭', '沙苑南渡头', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["秋霧連雲白，歸心浦漵懸。","津人空守纜，村館復臨川。","篷隔蒼茫雨，波連演漾田。"]', '["秋霧連云白，归心浦漵懸。","津人空守纜，村館复臨川。","篷隔蒼茫雨，波連演漾田。"]', '诗', 'shi', '', NULL, '沙苑南渡頭 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('acf02553-a3dc-433d-800c-f7b1df696fe4', '客廣陵', '客廣陵', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["樓頭廣陵近，九月在南徐。","秋色明海縣，寒烟生里閭。","夜帆歸楚客，昨日度江書。","爲問易名叟，垂綸不見魚。"]', '["楼头廣陵近，九月在南徐。","秋色明海縣，寒烟生里閭。","夜帆归楚客，昨日度江书。","爲问易名叟，垂綸不见鱼。"]', '诗', 'shi', '', NULL, '客廣陵 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31f007fa-da7e-4b7a-9531-c55b74675814', '靜法師東齋', '静法師东斋', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["築室在人境，遂得真隱情。","春盡草木變，雨來池館清。","琴書全雅道，視聽已無生。","閉戶脫三界，白雲自虛盈。"]', '["築室在人境，遂得真隐情。","春尽草木变，雨来池館清。","琴书全雅道，視听已無生。","閉戶脫三界，白云自虛盈。"]', '诗', 'shi', '', NULL, '靜法師東齋 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f67f7764-1321-4c2e-acdd-ee0b70946616', '素上人影塔', '素上人影塔', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["物化同枯木，希夷明月珠。","本來生滅盡，何者是虛無。","一坐看如故，千齡獨向隅。","至人非別有，方外不應殊。"]', '["物化同枯木，希夷明月珠。","本来生滅尽，何者是虛無。","一坐看如故，千齡独向隅。","至人非別有，方外不應殊。"]', '诗', 'shi', '', NULL, '素上人影塔 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('494d0e6c-6ba8-4675-8346-f2d3c2dc31e1', '遇薛明府謁聰上人', '遇薛明府謁聰上人', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["欣逢柏梁故，共謁聰公禪。","石室無人到，繩牀見虎眠。","陰崖常抱雪，枯澗爲生泉。","出處雖雲異，同歡在法筵。"]', '["欣逢柏梁故，共謁聰公禪。","石室無人到，繩牀见虎眠。","陰崖常抱雪，枯澗爲生泉。","出处雖云異，同歡在法筵。"]', '诗', 'shi', '', NULL, '遇薛明府謁聰上人 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10f0af8f-fc6d-4567-a0c4-99ae6c552a60', '謁焦鍊師', '謁焦鍊師', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["中峯青苔壁，一點雲生時。","豈意石堂裏，得逢焦鍊師。","爐香淨琴案，松影閑瑤墀。","拜受長年藥，翩翻西海期。"]', '["中峯青苔壁，一点云生时。","豈意石堂裏，得逢焦鍊師。","爐香淨琴案，松影闲瑤墀。","拜受长年藥，翩翻西海期。"]', '诗', 'shi', '', NULL, '謁焦鍊師 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbd3b9f0-53a9-468a-a6ec-96498624d8a9', '宿京江口期劉昚虛不至', '宿京江口期劉昚虛不至', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["霜天起長望，殘月生海門。","風靜夜潮滿，城高寒氣昏。","故人何寂寞，久已乖清言。","明發不能寐，徒盈江上尊。"]', '["霜天起长望，殘月生海门。","风静夜潮满，城高寒氣昏。","故人何寂寞，久已乖清言。","明發不能寐，徒盈江上尊。"]', '诗', 'shi', '', NULL, '宿京江口期劉昚虛不至 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53464ad6-c788-4688-b38d-4634a524a2f6', '寒食即事', '寒食即事', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["晉陽寒食地，風俗舊來傳。","雨滅龍蛇火，春生鴻雁天。","泣多流水漲，歌發舞雲旋。","西見之推廟，空爲人所憐。"]', '["晉陽寒食地，风俗旧来傳。","雨滅龙蛇火，春生鴻雁天。","泣多流水漲，歌發舞云旋。","西见之推廟，空爲人所怜。"]', '诗', 'shi', '', NULL, '寒食即事 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba7f3fd4-cf73-48c1-b6bc-2e26b66bf75a', '九日登高', '九日登高', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["青山遠近帶皇州，霽景重陽上北樓。","雨歇亭臯仙菊潤，霜飛天苑御梨秋。","茱萸插鬢花宜壽，翡翠橫釵舞作愁。","謾說陶潛籬下醉，何曾得見此風流。"]', '["青山远近带皇州，霽景重陽上北楼。","雨歇亭臯仙菊潤，霜飞天苑御梨秋。","茱萸插鬢花宜壽，翡翠橫釵舞作愁。","謾说陶潛籬下醉，何曾得见此风流。"]', '诗', 'shi', '', NULL, '九日登高 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f7e5cd4-f302-4cc4-b79d-2abb0b6e3088', '萬歲樓', '万歲楼', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["江上巍巍萬歲樓，不知經歷幾千秋。","年年喜見山長在，日日悲看水獨流。","猿狖何曾離暮嶺，鸕鶿空自泛寒洲。","誰堪登望雲烟裏，向晚茫茫發旅愁。"]', '["江上巍巍万歲楼，不知經歷幾千秋。","年年喜见山长在，日日悲看水独流。","猿狖何曾離暮嶺，鸕鶿空自泛寒洲。","誰堪登望云烟裏，向晚茫茫發旅愁。"]', '诗', 'shi', '', NULL, '萬歲樓 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('607042a4-3dbc-46f3-8491-91baf1566991', '夏月花萼樓酺宴應制', '夏月花萼楼酺宴應制', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["土德三元正，堯心萬國同。","汾陰備冬禮，長樂應和風。","賜慶垂天澤，流歡舊渚宮。","樓臺生海上，簫鼓出天中。","霧曉筵初接，宵長曲未終。","雨隨青幕合，月照舞羅空。","玉陛分朝列，文章發聖聰。","愚臣忝書賦，歌詠頌絲桐。"]', '["土德三元正，堯心万国同。","汾陰備冬禮，长乐應和风。","賜慶垂天澤，流歡旧渚宮。","楼台生海上，簫鼓出天中。","霧晓筵初接，宵长曲未終。","雨隨青幕合，月照舞羅空。","玉陛分朝列，文章發聖聰。","愚臣忝书賦，歌詠頌絲桐。"]', '诗', 'shi', '', NULL, '夏月花萼樓酺宴應制 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8280b48-5458-437b-908b-4cbf50cd982b', '送歐陽會稽之任', '送歐陽會稽之任', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["懷祿貴心賞，東流山水長。","官移會稽郡，地邇上虞鄉。","緩帶屏紛雜，漁舟臨訟堂。","逶迤迴谿趣，猿嘯飛鳥行。","萬室霽朝雨，千峰迎夕陽。","輝輝遠洲暎，曖曖澄湖光。","白髮有高士，青春期上皇。","應須枉車歇，爲我訪荷裳。"]', '["懷祿貴心賞，东流山水长。","官移會稽郡，地邇上虞乡。","緩带屏紛杂，漁舟臨訟堂。","逶迤迴谿趣，猿嘯飞鸟行。","万室霽朝雨，千峰迎夕陽。","輝輝远洲暎，曖曖澄湖光。","白髮有高士，青春期上皇。","應須枉车歇，爲我訪荷裳。"]', '诗', 'shi', '', NULL, '送歐陽會稽之任 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aebc05f0-516c-4909-83c3-f9e51a2a1a6c', '同王維集青龍寺曇壁上人兄院五韻', '同王維集青龙寺曇壁上人兄院五韻', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["本來清淨所，竹樹引幽陰。","簷外含山翠，人間出世心。","圓通無有象，聖境不能侵。","真是吾兄法，何妨友弟深。","天香自然會，靈異識鐘音。"]', '["本来清淨所，竹樹引幽陰。","簷外含山翠，人间出世心。","圓通無有象，聖境不能侵。","真是吾兄法，何妨友弟深。","天香自然會，靈異識鐘音。"]', '诗', 'shi', '', NULL, '同王維集青龍寺曇壁上人兄院五韻 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c18e5b00-f843-4768-a1d7-a12394d603ea', '東谿翫月', '东谿翫月', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["月從斷山口，遙吐柴門端。","萬木分空霽，流陰中夜攢。","光連虛象白，氣與風露寒。","谷靜秋泉響，巖深青靄殘。","澄清入幽夢，破影抱空巒。","恍惚琴窗裏，松谿曉思難。"]', '["月從斷山口，遙吐柴门端。","万木分空霽，流陰中夜攢。","光連虛象白，氣與风露寒。","谷静秋泉响，巖深青靄殘。","澄清入幽梦，破影抱空巒。","恍惚琴窗裏，松谿晓思难。"]', '诗', 'shi', '', NULL, '東谿翫月 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8878861-e55c-453c-ac79-3f728e9d0842', '朝來曲', '朝来曲', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["月昃鳴珂動，花連繡戶春。","盤龍玉臺鏡，唯待畫眉人。"]', '["月昃鳴珂动，花連繡戶春。","盤龙玉台镜，唯待畫眉人。"]', '诗', 'shi', '', NULL, '朝來曲 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33a97617-dcc4-4a08-81d6-24063abfd0e8', '從軍行', '從軍行', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["大將軍出戰，白日暗榆關。","三面黃金甲，單于破膽還。"]', '["大將軍出戰，白日暗榆关。","三面黄金甲，單于破膽還。"]', '诗', 'shi', '', NULL, '從軍行 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('351313ad-b817-4198-93c5-ef305c824210', '答武陵田太守', '答武陵田太守', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["仗劒行千里，微軀感一言。","曾爲大梁客，不負信陵恩。"]', '["仗劒行千里，微軀感一言。","曾爲大梁客，不負信陵恩。"]', '诗', 'shi', '', NULL, '答武陵田太守 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efa00292-744f-487f-8940-e86c65c23a3f', '題灞池二首 一', '題灞池二首 一', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["腰鎌欲何之，東園刈秋韭。","世事不復論，悲歌和樵叟。"]', '["腰鎌欲何之，东园刈秋韭。","世事不复論，悲歌和樵叟。"]', '诗', 'shi', '', NULL, '題灞池二首 一 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('850a9520-0620-445c-98e9-ed842822cf9e', '題灞池二首 二', '題灞池二首 二', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["開門望長川，薄暮見漁者。","借問白頭翁，垂綸幾年也。"]', '["开门望长川，薄暮见漁者。","借问白头翁，垂綸幾年也。"]', '诗', 'shi', '', NULL, '題灞池二首 二 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7d3f6a6-75be-486c-96ae-4b9590b35695', '題僧房', '題僧房', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["椶櫚花滿院，苔蘚入閑房。","彼此名言絕，空中聞異香。"]', '["椶櫚花满院，苔蘚入闲房。","彼此名言絕，空中闻異香。"]', '诗', 'shi', '', NULL, '題僧房 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('beff880b-695c-4643-8115-250be332ddc0', '擊磬老人', '擊磬老人', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["雙峰褐衣久，一磬白眉長。","誰識野人意，徒看春草芳。"]', '["雙峰褐衣久，一磬白眉长。","誰識野人意，徒看春草芳。"]', '诗', 'shi', '', NULL, '擊磬老人 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4529cb2e-4db1-4a15-a062-1f4d83e45989', '送胡大', '送胡大', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["荆門不堪別，況乃瀟湘秋。","何處遙望君，江邊明月樓。"]', '["荆门不堪別，況乃瀟湘秋。","何处遙望君，江邊明月楼。"]', '诗', 'shi', '', NULL, '送胡大 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d878a2ff-a8ba-498f-a325-6cc5d54ff4ab', '送郭司倉', '送郭司倉', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["暎門淮水綠，留騎主人心。","明月隨良掾，春潮夜夜深。"]', '["暎门淮水綠，留騎主人心。","明月隨良掾，春潮夜夜深。"]', '诗', 'shi', '', NULL, '送郭司倉 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e49dac06-6bd7-4be3-bee9-dfe76bfb648e', '送李十五', '送李十五', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["怨別秦楚深，江中秋雲起。","天長杳無隔，月影在寒水。"]', '["怨別秦楚深，江中秋云起。","天长杳無隔，月影在寒水。"]', '诗', 'shi', '', NULL, '送李十五 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1275df2-d211-448e-88d6-554a7dccc11e', '送張四', '送張四', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["楓林已愁暮，楚水復堪悲。","別後冷山月，清猿無斷時。"]', '["楓林已愁暮，楚水复堪悲。","別後冷山月，清猿無斷时。"]', '诗', 'shi', '', NULL, '送張四 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7382129c-d8e3-407e-9a23-d9d22738aada', '武陵田太守席送司馬盧谿', '武陵田太守席送司马盧谿', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["諸侯分楚郡，飲餞五谿春。","山水清暉遠，俱憐一逐臣。"]', '["諸侯分楚郡，饮餞五谿春。","山水清暉远，俱怜一逐臣。"]', '诗', 'shi', '', NULL, '武陵田太守席送司馬盧谿 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fa83a19-32a8-4404-8bd3-27716ab651c6', '送譚八之桂林', '送譚八之桂林', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["客心仍在楚，江館復臨湘。","別意猿鳥外，天寒桂水長。"]', '["客心仍在楚，江館复臨湘。","別意猿鸟外，天寒桂水长。"]', '诗', 'shi', '', NULL, '送譚八之桂林 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5dc35e8f-eb85-4bfb-9426-f8c53cb97408', '送劉十五之郡', '送劉十五之郡', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["平明江霧寒，客馬江上發。","扁舟事洛陽，窅窅含楚月。"]', '["平明江霧寒，客马江上發。","扁舟事洛陽，窅窅含楚月。"]', '诗', 'shi', '', NULL, '送劉十五之郡 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ac86eeb-6fbe-4fea-bbb2-f2cabb97d68e', '從軍行七首 一', '從軍行七首 一', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["烽火城西百尺樓，黃昏獨上海風秋。","更吹羌笛關山月，無那金閨萬里愁。"]', '["烽火城西百尺楼，黄昏独上海风秋。","更吹羌笛关山月，無那金閨万里愁。"]', '诗', 'shi', '', NULL, '從軍行七首 一 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b657130-529b-4128-b4bb-279af91baed1', '從軍行七首 二', '從軍行七首 二', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["琵琶起舞換新聲，總是關山舊別情。","撩亂邊愁聽不盡，高高秋月照長城。"]', '["琵琶起舞換新声，總是关山旧別情。","撩亂邊愁听不尽，高高秋月照长城。"]', '诗', 'shi', '', NULL, '從軍行七首 二 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80f4b4f0-96e5-46a9-a634-f152b9f390d8', '從軍行七首 三', '從軍行七首 三', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["關城榆葉早疎黃，日暮雲沙古戰場。","表請回軍掩塵骨，莫教兵士哭龍荒。"]', '["关城榆葉早疎黄，日暮云沙古戰場。","表請回軍掩塵骨，莫教兵士哭龙荒。"]', '诗', 'shi', '', NULL, '從軍行七首 三 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb92a089-72f0-44c2-93f8-060124eaa0a9', '從軍行七首 四', '從軍行七首 四', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["青海長雲暗雪山，孤城遙望玉門關。","黃沙百戰穿金甲，不破樓蘭終不還。"]', '["青海长云暗雪山，孤城遙望玉门关。","黄沙百戰穿金甲，不破楼蘭終不還。"]', '诗', 'shi', '', NULL, '從軍行七首 四 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('924151b2-fb99-456c-8788-a3265159792e', '從軍行七首 五', '從軍行七首 五', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["大漠風塵日色昏，紅旗半捲出轅門。","前軍夜戰洮河北，已報生擒吐谷渾。"]', '["大漠风塵日色昏，紅旗半捲出轅门。","前軍夜戰洮河北，已報生擒吐谷渾。"]', '诗', 'shi', '', NULL, '從軍行七首 五 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e19fbd6b-a7de-46b8-be86-125c3941777f', '從軍行七首 六', '從軍行七首 六', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["胡瓶落膊紫薄汗，碎葉城西秋月團。","明敕星馳封寶劒，辭君一夜取樓蘭。"]', '["胡瓶落膊紫薄汗，碎葉城西秋月團。","明敕星驰封寶劒，辞君一夜取楼蘭。"]', '诗', 'shi', '', NULL, '從軍行七首 六 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca7390ce-3f21-4291-a03b-de83e46060f9', '從軍行七首 七', '從軍行七首 七', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["玉門山嶂幾千重，山北山南總是烽。","人依遠戍須看火，馬踏深山不見蹤。"]', '["玉门山嶂幾千重，山北山南總是烽。","人依远戍須看火，马踏深山不见蹤。"]', '诗', 'shi', '', NULL, '從軍行七首 七 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de6b7e3d-03cd-4daa-bdc2-7fb820fda441', '出塞二首 一', '出塞二首 一', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["秦時明月漢時關，萬里長征人未還。","但使龍城飛將在，不教胡馬度陰山。"]', '["秦时明月漢时关，万里长征人未還。","但使龙城飞將在，不教胡马度陰山。"]', '诗', 'shi', '', NULL, '出塞二首 一 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25e93094-40d5-45ee-845d-b15dc6a5c1c3', '出塞二首 二', '出塞二首 二', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["騮馬新跨白玉鞍，戰罷沙場月色寒。","城頭鐵鼓聲猶振，匣裏金刀血未乾。"]', '["騮马新跨白玉鞍，戰罷沙場月色寒。","城头鐵鼓声猶振，匣裏金刀血未乾。"]', '诗', 'shi', '', NULL, '出塞二首 二 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84f40b5c-4c5b-43c4-822a-d2b92c7b41e1', '采蓮曲二首 一', '采蓮曲二首 一', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["吳姬越豔楚王妃，爭弄蓮舟水濕衣。","來時浦口花迎入，采罷江頭月送歸。"]', '["吳姬越豔楚王妃，爭弄蓮舟水濕衣。","来时浦口花迎入，采罷江头月送归。"]', '诗', 'shi', '', NULL, '采蓮曲二首 一 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5383487f-7c1f-43ee-9cf9-c1f44a4a0e45', '采蓮曲二首 二', '采蓮曲二首 二', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["荷葉羅裙一色裁，芙蓉向臉兩邊開。","亂入池中看不見，聞歌始覺有人來。"]', '["荷葉羅裙一色裁，芙蓉向臉兩邊开。","亂入池中看不见，闻歌始覺有人来。"]', '诗', 'shi', '', NULL, '采蓮曲二首 二 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e1e21da-a20a-4c12-9c5d-5ae05d2df153', '殿前曲二首 一', '殿前曲二首 一', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["貴人妝梳殿前催，香風吹入殿後來。","仗引笙歌大宛馬，白蓮花發照池臺。"]', '["貴人妝梳殿前催，香风吹入殿後来。","仗引笙歌大宛马，白蓮花發照池台。"]', '诗', 'shi', '', NULL, '殿前曲二首 一 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5432f819-f445-4cb3-bf9a-e6692bbd033a', '殿前曲二首 二', '殿前曲二首 二', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["胡部笙歌西殿頭，梨園弟子和涼州。","新聲一段高樓月，聖主千秋樂未休。"]', '["胡部笙歌西殿头，梨园弟子和涼州。","新声一段高楼月，聖主千秋乐未休。"]', '诗', 'shi', '', NULL, '殿前曲二首 二 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0fa1454-f337-4343-ab4a-2a42dfdf4e8f', '春宮曲', '春宮曲', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["昨夜風開露井桃，未央前殿月輪高。","平陽歌舞新承寵，簾外春寒賜錦袍。"]', '["昨夜风开露井桃，未央前殿月輪高。","平陽歌舞新承寵，簾外春寒賜錦袍。"]', '诗', 'shi', '', NULL, '春宮曲 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b5f5a9f-754b-4dda-8b18-bac4598eb0fe', '西宮春怨', '西宮春怨', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["西宮夜靜百花香，欲捲珠簾春恨長。","斜抱雲和深見月，朦朧樹色隱昭陽。"]', '["西宮夜静百花香，欲捲珠簾春恨长。","斜抱云和深见月，朦朧樹色隐昭陽。"]', '诗', 'shi', '', NULL, '西宮春怨 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('786a91cb-4e20-4cdb-951e-70abfcf1af85', '西宮秋怨', '西宮秋怨', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["芙蓉不及美人妝，水殿風來珠翠香。","誰分含啼掩秋扇，空懸明月待君王。"]', '["芙蓉不及美人妝，水殿风来珠翠香。","誰分含啼掩秋扇，空懸明月待君王。"]', '诗', 'shi', '', NULL, '西宮秋怨 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('913bf762-71a5-46bf-88d9-af85385191c6', '長信秋詞五首 一', '长信秋词五首 一', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["金井梧桐秋葉黃，珠簾不捲夜來霜。","熏籠玉枕無顏色，臥聽南宮清漏長。"]', '["金井梧桐秋葉黄，珠簾不捲夜来霜。","熏籠玉枕無顏色，臥听南宮清漏长。"]', '诗', 'shi', '', NULL, '長信秋詞五首 一 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('620823bf-6fe5-4db1-aef1-ea1e91b97397', '長信秋詞五首 二', '长信秋词五首 二', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["高殿秋砧響夜闌，霜深猶憶御衣寒。","銀燈青瑣裁縫歇，還向金城明主看。"]', '["高殿秋砧响夜闌，霜深猶憶御衣寒。","銀灯青瑣裁縫歇，還向金城明主看。"]', '诗', 'shi', '', NULL, '長信秋詞五首 二 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88ffb109-8e3f-4175-9352-8e02c28a4d9f', '長信秋詞五首 三', '长信秋词五首 三', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["奉帚平明金殿開，且將團扇暫裴回。","玉顏不及寒鴉色，猶帶[昭]陽日影來。"]', '["奉帚平明金殿开，且將團扇暫裴回。","玉顏不及寒鴉色，猶带[昭]陽日影来。"]', '诗', 'shi', '', NULL, '長信秋詞五首 三 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2c2c33b-fd1d-4aa2-9558-2b55137adec4', '長信秋詞五首 四', '长信秋词五首 四', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["真成薄命久尋思，夢見君王覺後疑。","火照西宮知夜飲，分明複道奉恩時。"]', '["真成薄命久尋思，梦见君王覺後疑。","火照西宮知夜饮，分明複道奉恩时。"]', '诗', 'shi', '', NULL, '長信秋詞五首 四 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('058b2020-c2cd-44fb-9657-358a5468ac2d', '長信秋詞五首 五', '长信秋词五首 五', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["長信宮中秋月明，昭陽殿下擣衣聲。","白露堂中細草跡，紅羅帳裏不勝情。"]', '["长信宮中秋月明，昭陽殿下擣衣声。","白露堂中細草跡，紅羅帳裏不勝情。"]', '诗', 'shi', '', NULL, '長信秋詞五首 五 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3af49c81-e4be-4724-9b7b-1b41966e9d69', '青樓曲二首 一', '青楼曲二首 一', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["白馬金鞍從武皇，旌旗十萬宿長楊。","樓頭小婦鳴箏坐，遙見飛塵入建章。"]', '["白马金鞍從武皇，旌旗十万宿长楊。","楼头小婦鳴箏坐，遙见飞塵入建章。"]', '诗', 'shi', '', NULL, '青樓曲二首 一 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d12908bf-0ec6-4137-9ea8-fce8383fda4a', '青樓曲二首 二', '青楼曲二首 二', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["馳道楊花滿御溝，紅妝縵綰上青樓。","金章紫綬千餘騎，夫壻朝回初拜侯。"]', '["驰道楊花满御溝，紅妝縵綰上青楼。","金章紫綬千餘騎，夫壻朝回初拜侯。"]', '诗', 'shi', '', NULL, '青樓曲二首 二 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fea4e9e-800a-4d1d-bad2-2a4019ae787b', '青樓怨', '青楼怨', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["香幃風動花入樓，高調鳴箏緩夜愁。","腸斷關山不解說，依依殘月下簾鉤。"]', '["香幃风动花入楼，高調鳴箏緩夜愁。","腸斷关山不解说，依依殘月下簾鉤。"]', '诗', 'shi', '', NULL, '青樓怨 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8209ce8e-92c6-4123-b130-1186ed714dfa', '浣紗女', '浣紗女', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["錢塘江邊是誰家，江上女兒全勝花。","吳王在時不得出，今日公然來浣紗。"]', '["錢塘江邊是誰家，江上女兒全勝花。","吳王在时不得出，今日公然来浣紗。"]', '诗', 'shi', '', NULL, '浣紗女 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ac3f099-73da-43e8-a4e5-1dbbd9427491', '閨怨', '閨怨', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["閨中少婦不曾愁，春日凝妝上翠樓。","忽見陌頭楊柳色，悔教夫壻覓封侯。"]', '["閨中少婦不曾愁，春日凝妝上翠楼。","忽见陌头楊柳色，悔教夫壻覓封侯。"]', '诗', 'shi', '', NULL, '閨怨 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3286b733-02a6-4c21-951d-c873830a08b8', '甘泉歌', '甘泉歌', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["乘輿執玉已登壇，細草霑衣春殿寒。","昨夜雲生拜初月，萬年甘露水晶盤。"]', '["乘輿執玉已登壇，細草霑衣春殿寒。","昨夜云生拜初月，万年甘露水晶盤。"]', '诗', 'shi', '', NULL, '甘泉歌 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb12783c-1c1b-44c4-82ce-7cf9e3096a9e', '蕭駙馬宅花燭', '蕭駙马宅花燭', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["青鸞飛入合歡宮，紫鳳銜花出禁中。","可憐今夜千門裏，銀漢星回一道通。"]', '["青鸾飞入合歡宮，紫鳳銜花出禁中。","可怜今夜千门裏，銀漢星回一道通。"]', '诗', 'shi', '', NULL, '蕭駙馬宅花燭 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92f55a8c-7778-4802-9991-d76b0e4fdb48', '觀獵', '观獵', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["角鷹初下秋草稀，鐵驄拋鞚去如飛。","少年獵得平原兔，馬後橫捎意氣歸。"]', '["角鷹初下秋草稀，鐵驄拋鞚去如飞。","少年獵得平原兔，马後橫捎意氣归。"]', '诗', 'shi', '', NULL, '觀獵 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('033dcca7-d4de-479e-b804-2cadf83a1ff6', '寄穆侍御出幽州', '寄穆侍御出幽州', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["一從恩譴度瀟湘，塞北江南萬里長。","莫道薊門書信少，鴈飛猶得到衡陽。"]', '["一從恩譴度瀟湘，塞北江南万里长。","莫道薊门书信少，鴈飞猶得到衡陽。"]', '诗', 'shi', '', NULL, '寄穆侍御出幽州 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86637a29-5545-453f-9bbf-fc2a0a83c6d1', '寄陶副使', '寄陶副使', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["聞道將軍破海門，如何遠謫渡湘沅。","春來明主封西嶽，自有還君紫綬恩。"]', '["闻道將軍破海门，如何远謫渡湘沅。","春来明主封西嶽，自有還君紫綬恩。"]', '诗', 'shi', '', NULL, '寄陶副使 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26f3af10-4553-416c-9d86-c110264a16dc', '至南陵答皇甫岳', '至南陵答皇甫岳', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["與君同病復漂淪，昨夜宣城別故人。","明主恩深非歲久，長江還共五谿濱。"]', '["與君同病复漂淪，昨夜宣城別故人。","明主恩深非歲久，长江還共五谿濱。"]', '诗', 'shi', '', NULL, '至南陵答皇甫岳 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d60591c0-2c20-48b3-aa03-8f40188cb455', '西江寄越弟', '西江寄越弟', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["南浦逢君嶺外還，沅谿更遠洞庭山。","堯時恩澤如春雨，夢裏相逢同入關。"]', '["南浦逢君嶺外還，沅谿更远洞庭山。","堯时恩澤如春雨，梦裏相逢同入关。"]', '诗', 'shi', '', NULL, '西江寄越弟 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94054365-0488-4baa-ad3c-ff7fffaebf1d', '李四倉曹宅夜飲', '李四倉曹宅夜饮', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["霜天留後故情歡，銀燭金爐夜不寒。","欲問吳江別來意，青山明月夢中看。"]', '["霜天留後故情歡，銀燭金爐夜不寒。","欲问吳江別来意，青山明月梦中看。"]', '诗', 'shi', '', NULL, '李四倉曹宅夜飲 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a64addc-bcd1-4e2a-91ff-4f060a803ecb', '宴春源', '宴春源', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["源向春城花幾重，江明深翠引諸峯。","與君醉失松溪路，山館寥寥傳暝鐘。"]', '["源向春城花幾重，江明深翠引諸峯。","與君醉失松溪路，山館寥寥傳暝鐘。"]', '诗', 'shi', '', NULL, '宴春源 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7646be95-fa97-4cc3-b7e2-3ae09962288d', '龍標野宴', '龙標野宴', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["沅溪夏晚足涼風，春酒相攜就竹叢。","莫道絃歌愁遠謫，青山明月不曾空。"]', '["沅溪夏晚足涼风，春酒相携就竹叢。","莫道絃歌愁远謫，青山明月不曾空。"]', '诗', 'shi', '', NULL, '龍標野宴 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a52785c6-d98a-45ed-a53d-60043e8b5de7', '聽流人水調子', '听流人水調子', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["孤舟微月對楓林，分付鳴箏與客心。","嶺色千重萬重雨，斷絃收與淚痕深。"]', '["孤舟微月对楓林，分付鳴箏與客心。","嶺色千重万重雨，斷絃收與泪痕深。"]', '诗', 'shi', '', NULL, '聽流人水調子 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4cf1877-336f-42e8-be4d-5164d41e698a', '梁苑', '梁苑', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["梁園秋竹古時烟，城外風悲欲暮天。","萬乘旌旗何處在？平臺賓客有誰憐。"]', '["梁园秋竹古时烟，城外风悲欲暮天。","万乘旌旗何处在？平台賓客有誰怜。"]', '诗', 'shi', '', NULL, '梁苑 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddb632ea-fedf-4c02-8eec-770487b01d18', '武陵龍興觀黃道士房問易因題', '武陵龙兴观黄道士房问易因題', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["齋心問易太陽宮，八卦真形一氣中。","仙老言餘鶴飛去，玉清壇上雨濛濛。"]', '["斋心问易太陽宮，八卦真形一氣中。","仙老言餘鹤飞去，玉清壇上雨濛濛。"]', '诗', 'shi', '', NULL, '武陵龍興觀黃道士房問易因題 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e03215e-a131-48cf-9e89-3544a6cdc967', '送魏二', '送魏二', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["醉別江樓橘柚香，江風引雨入舟涼。","憶君遙在瀟湘月，愁聽清猿夢裏長。"]', '["醉別江楼橘柚香，江风引雨入舟涼。","憶君遙在瀟湘月，愁听清猿梦裏长。"]', '诗', 'shi', '', NULL, '送魏二 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe05e0de-1a35-4213-accd-f7e7b8f0938e', '別李浦之京', '別李浦之京', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["故園今在灞陵西，江畔逢君醉不迷。","小弟鄰莊尚漁獵，一封書寄數行啼。"]', '["故园今在灞陵西，江畔逢君醉不迷。","小弟鄰莊尚漁獵，一封书寄數行啼。"]', '诗', 'shi', '', NULL, '別李浦之京 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6a15f09-69eb-40aa-b596-8fe565c97980', '送狄宗亨', '送狄宗亨', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["秋在水清山暮蟬，洛陽樹色鳴臯烟。","送君歸去愁不盡，又惜空度涼風天。"]', '["秋在水清山暮蟬，洛陽樹色鳴臯烟。","送君归去愁不尽，又惜空度涼风天。"]', '诗', 'shi', '', NULL, '送狄宗亨 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e793ba8b-96b3-4124-964a-e29324b00d4b', '送薛大赴安陸', '送薛大赴安陸', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["津頭雲雨暗湘山，遷客離憂楚地顏。","遙送扁舟安陸郡，天邊何處穆陵關。"]', '["津头云雨暗湘山，遷客離憂楚地顏。","遙送扁舟安陸郡，天邊何处穆陵关。"]', '诗', 'shi', '', NULL, '送薛大赴安陸 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('090b7792-2942-4f3c-a34d-caccd066c76f', '芙蓉樓送辛漸二首 一', '芙蓉楼送辛漸二首 一', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["寒雨連天夜入湖，平明送客楚山孤。","洛陽親友如相問，一片冰心在玉壺。"]', '["寒雨連天夜入湖，平明送客楚山孤。","洛陽親友如相问，一片冰心在玉壺。"]', '诗', 'shi', '', NULL, '芙蓉樓送辛漸二首 一 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31d3f836-d70b-48d7-875d-9c3aa4bcada4', '芙蓉樓送辛漸二首 二', '芙蓉楼送辛漸二首 二', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["丹陽城南秋海陰，丹陽城北楚雲深。","高樓送客不能醉，寂寂寒江明月心。"]', '["丹陽城南秋海陰，丹陽城北楚云深。","高楼送客不能醉，寂寂寒江明月心。"]', '诗', 'shi', '', NULL, '芙蓉樓送辛漸二首 二 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f24db79-b073-4320-99ef-04d7c8098ec3', '重別李評事', '重別李評事', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["莫道秋江離別難，舟船明日是長安。","吳姬緩舞留君醉，隨意青楓白露寒。"]', '["莫道秋江離別难，舟船明日是长安。","吳姬緩舞留君醉，隨意青楓白露寒。"]', '诗', 'shi', '', NULL, '重別李評事 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('412f7f57-4b3c-474d-822c-dc07d62cd331', '別陶副使歸南海', '別陶副使归南海', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["南越歸人夢海樓，廣陵新月海亭秋。","寶刀留贈長相憶，當取戈船萬戶侯。"]', '["南越归人梦海楼，廣陵新月海亭秋。","寶刀留贈长相憶，當取戈船万戶侯。"]', '诗', 'shi', '', NULL, '別陶副使歸南海 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2acbe16-2b35-4ed8-b78c-17b46cb7f29f', '送人歸江夏', '送人归江夏', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["寒江綠水楚雲深，莫道離憂遷遠心。","曉夕雙帆歸鄂渚，愁將孤月夢中尋。"]', '["寒江綠水楚云深，莫道離憂遷远心。","晓夕雙帆归鄂渚，愁將孤月梦中尋。"]', '诗', 'shi', '', NULL, '送人歸江夏 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46b46545-ecff-4c12-9bc7-eb965242a575', '送李五', '送李五', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["玉盌金罍傾送君，江西日入起黃雲。","扁舟乘月暫來去，誰道滄浪吳楚分。"]', '["玉盌金罍傾送君，江西日入起黄云。","扁舟乘月暫来去，誰道滄浪吳楚分。"]', '诗', 'shi', '', NULL, '送李五 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a01bf09-a6fb-492e-a45c-218178f36768', '送十五舅', '送十五舅', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["深林秋水近日空，歸棹演漾清陰中。","夕浦離觴意何已，草根寒露悲鳴蟲。"]', '["深林秋水近日空，归棹演漾清陰中。","夕浦離觴意何已，草根寒露悲鳴蟲。"]', '诗', 'shi', '', NULL, '送十五舅 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('feebecab-b17a-4a26-b13e-9d600b007ae3', '留別郭八', '留別郭八', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["長亭駐馬未能前，井邑蒼茫含暮煙。","醉別何須更惆悵，回頭不語但垂鞭。"]', '["长亭駐马未能前，井邑蒼茫含暮煙。","醉別何須更惆悵，回头不語但垂鞭。"]', '诗', 'shi', '', NULL, '留別郭八 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbdf6e69-b4c1-477f-92f7-d529b4f0d54e', '送竇七', '送竇七', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["清江月色傍林秋，波上熒熒望一舟。","鄂渚輕帆須早發，江邊明月爲君留。"]', '["清江月色傍林秋，波上熒熒望一舟。","鄂渚轻帆須早發，江邊明月爲君留。"]', '诗', 'shi', '', NULL, '送竇七 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4aeb5456-eac8-4a62-abf0-ec9114edeb02', '巴陵送李十二', '巴陵送李十二', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["搖曳巴陵洲渚分，清江傳語便風聞。","山長不見秋城色，日暮蒹葭空水雲。"]', '["搖曳巴陵洲渚分，清江傳語便风闻。","山长不见秋城色，日暮蒹葭空水云。"]', '诗', 'shi', '', NULL, '巴陵送李十二 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08769eec-7058-49ba-952d-e72368eadce5', '送裴圖南', '送裴圖南', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["黃河渡頭歸問津，離家幾日茱萸新。","漫道閨中飛破鏡，猶看陌上別行人。"]', '["黄河渡头归问津，離家幾日茱萸新。","漫道閨中飞破镜，猶看陌上別行人。"]', '诗', 'shi', '', NULL, '送裴圖南 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06fbf086-4bf5-46ce-aa6e-4ba5f8c8b4b1', '留別司馬太守', '留別司马太守', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["辰陽太守念王孫，遠謫沅谿何可論。","黃鶴青雲當一舉，明珠吐著抱君恩。"]', '["辰陽太守念王孫，远謫沅谿何可論。","黄鹤青云當一舉，明珠吐著抱君恩。"]', '诗', 'shi', '', NULL, '留別司馬太守 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12c81418-a970-476b-a48d-698a7bf84a58', '盧溪主人', '盧溪主人', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["武陵溪口駐扁舟，溪水隨君向北流。","行到荆門上三峽，莫將孤月對猿愁。"]', '["武陵溪口駐扁舟，溪水隨君向北流。","行到荆门上三峽，莫將孤月对猿愁。"]', '诗', 'shi', '', NULL, '盧溪主人 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ceb0c2f7-ffaf-4fee-a995-10cda09ea1e1', '送程六', '送程六', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["冬夜傷離在五溪，青魚雪落鱠橙虀。","武岡前路看斜月，片片舟中雲向西。"]', '["冬夜傷離在五溪，青鱼雪落鱠橙虀。","武岡前路看斜月，片片舟中云向西。"]', '诗', 'shi', '', NULL, '送程六 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6b1b4f5-49c9-47d5-9e05-ebd77e98bdc8', '送朱越', '送朱越', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["遠別舟中蔣山暮，君行舉首燕城路。","薊門秋月隱黃雲，期向金陵醉江樹。"]', '["远別舟中蔣山暮，君行舉首燕城路。","薊门秋月隐黄云，期向金陵醉江樹。"]', '诗', 'shi', '', NULL, '送朱越 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3d5c955-93ef-4b75-a83b-0d23b9e959bd', '別辛漸', '別辛漸', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["別館蕭條風雨寒，扁舟月色渡江看。","酒酣不識關西道，却望春江雲尚殘。"]', '["別館蕭條风雨寒，扁舟月色渡江看。","酒酣不識关西道，却望春江云尚殘。"]', '诗', 'shi', '', NULL, '別辛漸 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('789c0699-8187-42a6-b910-fb9b999d75bd', '送柴侍御', '送柴侍御', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["流水通波接武岡，送君不覺有離傷。","青山一道同雲雨，眀月何曽是兩鄉。"]', '["流水通波接武岡，送君不覺有離傷。","青山一道同云雨，眀月何曽是兩乡。"]', '诗', 'shi', '', NULL, '送柴侍御 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4edca98-5fd3-4ddd-9702-aa7d2f367947', '送萬大歸長沙', '送万大归长沙', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["桂陽秋水長沙縣，楚竹離聲爲君變。","青山隱隱孤舟微，白鶴雙飛忽相見。"]', '["桂陽秋水长沙縣，楚竹離声爲君变。","青山隐隐孤舟微，白鹤雙飞忽相见。"]', '诗', 'shi', '', NULL, '送萬大歸長沙 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27e987a5-b66b-4738-baf5-68e205f3c08e', '送吳十九往沅陵', '送吳十九往沅陵', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["沅江流水到辰陽，谿口逢君驛路長。","遠謫誰知望雷雨，明年春水共還鄉。"]', '["沅江流水到辰陽，谿口逢君驛路长。","远謫誰知望雷雨，明年春水共還乡。"]', '诗', 'shi', '', NULL, '送吳十九往沅陵 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70205727-903d-4bde-8c28-07e9bf09d538', '別皇甫五', '別皇甫五', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["漵浦潭陽隔楚山，離尊不用起愁顏。","明祠靈響期昭應，天澤俱從此路還。"]', '["漵浦潭陽隔楚山，離尊不用起愁顏。","明祠靈响期昭應，天澤俱從此路還。"]', '诗', 'shi', '', NULL, '別皇甫五 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82f43aa2-768a-47e3-a45f-acbb1bab2f6a', '送崔參軍往龍溪', '送崔參軍往龙溪', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["龍溪只在龍標上，秋月孤山兩相向。","譴謫離心是丈夫，鴻恩共侍春江漲。"]', '["龙溪只在龙標上，秋月孤山兩相向。","譴謫離心是丈夫，鴻恩共侍春江漲。"]', '诗', 'shi', '', NULL, '送崔參軍往龍溪 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6138239c-63b4-4622-a5ca-279a8031be4b', '送鄭判官', '送鄭判官', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["東楚吳山驛樹微，軺車銜命奉恩輝。","英僚攜出新豐酒，半道遙看驄馬歸。"]', '["东楚吳山驛樹微，軺车銜命奉恩輝。","英僚携出新豐酒，半道遙看驄马归。"]', '诗', 'shi', '', NULL, '送鄭判官 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e0db2d1-597f-4634-a8e8-bd1c907824ba', '送姚司法歸吳', '送姚司法归吳', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["吳掾留觴楚郡心，洞庭秋雨海門陰。","但令意遠扁舟近，不道滄江百丈深。"]', '["吳掾留觴楚郡心，洞庭秋雨海门陰。","但令意远扁舟近，不道滄江百丈深。"]', '诗', 'shi', '', NULL, '送姚司法歸吳 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f893ef56-fa7c-49ef-a8aa-fa2cb9b3fc52', '送高三之桂林', '送高三之桂林', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["留君夜飲對瀟湘，從此歸舟客夢長。","嶺上梅花侵雪暗，歸時還拂桂花香。"]', '["留君夜饮对瀟湘，從此归舟客梦长。","嶺上梅花侵雪暗，归时還拂桂花香。"]', '诗', 'shi', '', NULL, '送高三之桂林 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('159c125a-24c6-4756-bb38-8f6a893ae608', '旅望', '旅望', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["白花原頭望京師，黃河水流無盡時。","窮秋曠野行人絕，馬首東來知是誰。"]', '["白花原头望京師，黄河水流無尽时。","窮秋曠野行人絕，马首东来知是誰。"]', '诗', 'shi', '', NULL, '旅望 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6298051e-adce-4496-809f-634dcf2a1125', '題朱鍊師山房', '題朱鍊師山房', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["叩齒焚香出世塵，齋壇鳴磬步虛人。","百花仙醞能留客，一飯胡麻度幾春。"]', '["叩齒焚香出世塵，斋壇鳴磬步虛人。","百花仙醞能留客，一飯胡麻度幾春。"]', '诗', 'shi', '', NULL, '題朱鍊師山房 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b0c70cb-8ae5-4ffe-867e-3835b1352408', '武陵開元觀黃鍊師院三首 一', '武陵开元观黄鍊師院三首 一', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["松間白髮黃尊師，童子燒香禹步時。","欲訪桃源入溪路，忽聞雞犬使人疑。"]', '["松间白髮黄尊師，童子燒香禹步时。","欲訪桃源入溪路，忽闻雞犬使人疑。"]', '诗', 'shi', '', NULL, '武陵開元觀黃鍊師院三首 一 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31370c6a-1ac6-4416-884d-32eddb837892', '武陵開元觀黃鍊師院三首 二', '武陵开元观黄鍊師院三首 二', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["先賢盛說桃花源，塵忝何堪武陵郡。","聞道秦時避地人，至今不與人通問。"]', '["先賢盛说桃花源，塵忝何堪武陵郡。","闻道秦时避地人，至今不與人通问。"]', '诗', 'shi', '', NULL, '武陵開元觀黃鍊師院三首 二 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74430fb7-b24d-4751-9904-4fa4a574788a', '武陵開元觀黃鍊師院三首 三', '武陵开元观黄鍊師院三首 三', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["山觀空虛清靜門，從官役吏擾塵喧。","暫因問俗到真境，便欲投誠依道源。"]', '["山观空虛清静门，從官役吏擾塵喧。","暫因问俗到真境，便欲投誠依道源。"]', '诗', 'shi', '', NULL, '武陵開元觀黃鍊師院三首 三 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0305b271-93d4-435e-ab64-43cb17ccd5e4', '河上老人歌', '河上老人歌', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["河上老人坐古槎，合丹只用青蓮花。","至今八十如四十，口道滄溟是我家。"]', '["河上老人坐古槎，合丹只用青蓮花。","至今八十如四十，口道滄溟是我家。"]', '诗', 'shi', '', NULL, '河上老人歌 王昌齡 shi');
